INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f968ba8-1a23-4916-8b55-97f03e8cfe1e', '橫吹曲辭 洛陽陌', '橫吹曲辞 洛陽陌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白玉誰家郎，回車渡天津。","看花東上陌，驚動洛陽人。"]', '["白玉誰家郎，回车渡天津。","看花东上陌，驚动洛陽人。"]', '诗', 'shi', '', NULL, '橫吹曲辭 洛陽陌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c62ec987-4594-4d23-b0b1-868fcfbd7127', '橫吹曲辭 長安道', '橫吹曲辞 长安道', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["長安甲第高入雲，誰家居住霍將軍。","日晚朝回擁賓從，路傍拜揖何紛紛。","莫言炙手手可熱，須臾火盡灰亦滅。","莫言貧賤即可欺，人生富貴自有時。","一朝天子賜顏色，世上悠悠應始知。"]', '["长安甲第高入云，誰家居住霍將軍。","日晚朝回擁賓從，路傍拜揖何紛紛。","莫言炙手手可熱，須臾火尽灰亦滅。","莫言貧賤即可欺，人生富貴自有时。","一朝天子賜顏色，世上悠悠應始知。"]', '诗', 'shi', '', NULL, '橫吹曲辭 長安道 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3f85bae-5866-43c9-a99f-fd09db0cd459', '橫吹曲辭 長安道', '橫吹曲辞 长安道', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["胡風激秦樹，賤子風中泣。","家家朱門開，得見不可入。","長安十二衢，投樹鳥亦急。","高閣何人家？笙簧正喧吸。"]', '["胡风激秦樹，賤子风中泣。","家家朱门开，得见不可入。","长安十二衢，投樹鸟亦急。","高閣何人家？笙簧正喧吸。"]', '诗', 'shi', '', NULL, '橫吹曲辭 長安道 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b8e2e8-9352-4d4a-ad32-f66c1e622fff', '橫吹曲辭 長安道', '橫吹曲辞 长安道', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["長安道，人無衣，馬無草，何不歸來山中老。"]', '["长安道，人無衣，马無草，何不归来山中老。"]', '诗', 'shi', '', NULL, '橫吹曲辭 長安道 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a30357-99b0-4446-b35d-61a530b2c621', '橫吹曲辭 長安道', '橫吹曲辞 长安道', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["此地無駐馬，夜中猶走輪。","所以路旁草，少於衣上塵。"]', '["此地無駐马，夜中猶走輪。","所以路旁草，少於衣上塵。"]', '诗', 'shi', '', NULL, '橫吹曲辭 長安道 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ab8a232-27bf-4de3-b67c-28e4735fea7f', '橫吹曲辭 長安道', '橫吹曲辞 长安道', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["漢家宮殿含雲煙，兩宮十里相連延。","晨霞出沒弄丹闕，春雨依微自甘泉。","春雨依微春尚早，長安貴遊愛芳草。","寶馬橫來下建章，香車却轉避馳道。","貴遊誰最貴，衛霍世難比。","何能蒙主恩？幸遇邊塵起。","歸來甲第拱皇居，朱門峨峨臨九衢。","中有流蘇合歡之寶帳，一百二十鳳皇羅列含明珠。","下有錦鋪翠被之粲爛，博山吐香五雲散。","麗人綺閣情飄颻，頭上鴛釵雙翠翹。","低鬟曳袖回春雪，聚黛一聲愁碧霄。","山珍海錯棄藩籬，烹犢炰羔如折葵。","既請列侯封部曲，還將金印授廬兒。","歡榮若此何所苦，但苦白日西南馳。"]', '["漢家宮殿含云煙，兩宮十里相連延。","晨霞出沒弄丹闕，春雨依微自甘泉。","春雨依微春尚早，长安貴游愛芳草。","寶马橫来下建章，香车却轉避驰道。","貴游誰最貴，衛霍世难比。","何能蒙主恩？幸遇邊塵起。","归来甲第拱皇居，朱门峨峨臨九衢。","中有流蘇合歡之寶帳，一百二十鳳皇羅列含明珠。","下有錦鋪翠被之粲爛，博山吐香五云散。","丽人綺閣情飄颻，头上鴛釵雙翠翹。","低鬟曳袖回春雪，聚黛一声愁碧霄。","山珍海錯棄藩籬，烹犢炰羔如折葵。","既請列侯封部曲，還將金印授廬兒。","歡榮若此何所苦，但苦白日西南驰。"]', '诗', 'shi', '', NULL, '橫吹曲辭 長安道 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cca28bc8-2689-4419-bf3b-e5fef10f5db5', '橫吹曲辭 長安道', '橫吹曲辞 长安道', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["花枝缺處青樓開，豔歌一曲酒一杯。","美人勸我急行樂，自古朱顏不再來。","君不見外州客，長安道，一回來，一回老。"]', '["花枝缺处青楼开，豔歌一曲酒一杯。","美人勸我急行乐，自古朱顏不再来。","君不见外州客，长安道，一回来，一回老。"]', '诗', 'shi', '', NULL, '橫吹曲辭 長安道 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ceec82c4-c989-407d-9ef4-476c34a0d92a', '橫吹曲辭 長安道', '橫吹曲辞 长安道', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["汲汲復營營，東西連兩京。","關繻古若在，山岳累應成。","各自有身事，不相知姓名。","交馳喧衆類，分散入重城。","此路去無盡，萬方人始生。","空餘片言苦，來往覓劉楨。"]', '["汲汲复營營，东西連兩京。","关繻古若在，山岳累應成。","各自有身事，不相知姓名。","交驰喧衆類，分散入重城。","此路去無尽，万方人始生。","空餘片言苦，来往覓劉楨。"]', '诗', 'shi', '', NULL, '橫吹曲辭 長安道 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b26fac4-9f06-4ba0-9c7a-6a7be1300830', '橫吹曲辭 長安道', '橫吹曲辞 长安道', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["憧憧合合，八表一轍。","黃塵霧合，車馬火熱。","名湯風雨，利輾霜雪。","千車萬駄，半宿關月。","上有堯禹，下有夔契。","紫氣銀輪兮常覆金闕，仙掌捧日兮濁河澄澈。","愚將草木兮有言，與華封人兮不別。"]', '["憧憧合合，八表一轍。","黄塵霧合，车马火熱。","名湯风雨，利輾霜雪。","千车万駄，半宿关月。","上有堯禹，下有夔契。","紫氣銀輪兮常覆金闕，仙掌捧日兮濁河澄澈。","愚將草木兮有言，與华封人兮不別。"]', '诗', 'shi', '', NULL, '橫吹曲辭 長安道 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5da08f58-6acd-43e7-9fac-464b2f167280', '橫吹曲辭 長安道', '橫吹曲辞 长安道', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["秦地平如掌，層城出雲漢。","樓閣九衢春，車馬千門旦。","綠柳開復合，紅塵聚還散。","日晚鬬雞回，經過狹斜看。"]', '["秦地平如掌，層城出云漢。","楼閣九衢春，车马千门旦。","綠柳开复合，紅塵聚還散。","日晚鬬雞回，經過狹斜看。"]', '诗', 'shi', '', NULL, '橫吹曲辭 長安道 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d39a3dfa-9d38-4b9f-9a13-d3063b0b47bd', '橫吹曲辭 梅花落', '橫吹曲辞 梅花落', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["梅嶺花初發，天山雪未開。","雪處疑花滿，花邊似雪回。","因風入舞袖，雜粉向妝臺。","匈奴幾萬里，春至不知來。"]', '["梅嶺花初發，天山雪未开。","雪处疑花满，花邊似雪回。","因风入舞袖，杂粉向妝台。","匈奴幾万里，春至不知来。"]', '诗', 'shi', '', NULL, '橫吹曲辭 梅花落 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cee17360-6fa9-4406-9794-394ac59be538', '橫吹曲辭 梅花落', '橫吹曲辞 梅花落', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["鐵騎幾時回，金閨怨早梅。","雪中花已落，風暖葉應開。","夕逐新春管，香迎小歲杯。","感時何足貴，書裏報輪臺。"]', '["鐵騎幾时回，金閨怨早梅。","雪中花已落，风暖葉應开。","夕逐新春管，香迎小歲杯。","感时何足貴，书裏報輪台。"]', '诗', 'shi', '', NULL, '橫吹曲辭 梅花落 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00522c4a-6d4b-48a8-bc12-cc5dd744feca', '橫吹曲辭 梅花落', '橫吹曲辞 梅花落', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["新歲芳梅樹，繁苞四面同。","春風吹漸落，一夜幾枝空。","小婦今如此，長城恨不窮。","莫將遼海雪，來比後庭中。"]', '["新歲芳梅樹，繁苞四面同。","春风吹漸落，一夜幾枝空。","小婦今如此，长城恨不窮。","莫將遼海雪，来比後庭中。"]', '诗', 'shi', '', NULL, '橫吹曲辭 梅花落 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43d23382-d543-4aba-8a11-ed524328785d', '橫吹曲辭 紫騮馬', '橫吹曲辞 紫騮马', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["騮馬照金鞍，轉戰入皐蘭。","塞門風稍急，長城水正寒。","雪暗鳴珂重，山長噴玉難。","不辭橫絕漠，流血幾時乾。"]', '["騮马照金鞍，轉戰入皐蘭。","塞门风稍急，长城水正寒。","雪暗鳴珂重，山长噴玉难。","不辞橫絕漠，流血幾时乾。"]', '诗', 'shi', '', NULL, '橫吹曲辭 紫騮馬 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49016fc5-51cc-4d01-896d-a6e14768ce6e', '橫吹曲辭 紫騮馬', '橫吹曲辞 紫騮马', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["紫騮行且嘶，雙飜碧玉蹄。","臨流不肎渡，似惜錦障泥。","白雪關山遠，黃雲海樹迷。","揮鞭萬里去，安得念春閨。"]', '["紫騮行且嘶，雙飜碧玉蹄。","臨流不肎渡，似惜錦障泥。","白雪关山远，黄云海樹迷。","揮鞭万里去，安得念春閨。"]', '诗', 'shi', '', NULL, '橫吹曲辭 紫騮馬 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d876872-31d8-49d7-a9cf-efbf71e5827b', '橫吹曲辭 紫騮馬', '橫吹曲辞 紫騮马', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["爭場看鬬雞，白鼻紫騧嘶。","漳水春歸晚，叢臺日向低。","歇鞍珠作汗，試劒玉如泥。","爲謝紅梁燕，年年妾獨棲。"]', '["爭場看鬬雞，白鼻紫騧嘶。","漳水春归晚，叢台日向低。","歇鞍珠作汗，試劒玉如泥。","爲謝紅梁燕，年年妾独棲。"]', '诗', 'shi', '', NULL, '橫吹曲辭 紫騮馬 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('890d8eee-81f6-40f8-8887-810b30665d5f', '橫吹曲辭 紫騮馬', '橫吹曲辞 紫騮马', '2786fd43-c8b2-4f59-8888-3266a361aae5', '唐', '["渥洼奇骨本難求，況是豪家重紫騮。","臕大宜懸銀壓銙，力渾欺却玉銜頭。","生獰弄影風隨起，躞蹀衝塵汗滿溝。","若遇丈夫皆調御，任從騎取覓封侯。"]', '["渥洼奇骨本难求，況是豪家重紫騮。","臕大宜懸銀壓銙，力渾欺却玉銜头。","生獰弄影风隨起，躞蹀衝塵汗满溝。","若遇丈夫皆調御，任從騎取覓封侯。"]', '诗', 'shi', '', NULL, '橫吹曲辭 紫騮馬 秦韜玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0919893a-6302-4409-87ac-c1208e2e2f87', '橫吹曲辭 驄馬', '橫吹曲辞 驄马', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["浮雲何權奇，絕足勢未知。","長嘶青海風，躞蹀振雲絲。","由來渥洼種，本是蒼龍兒。","穆滿不再活，無人崑閬騎。","君識躍嶠怯，寧勞耀金羈。","青芻與白水，空笑駑駘肥。","伯樂儻一見，應驚耳長垂。","當思八荒外，逐日向瑤池。"]', '["浮云何權奇，絕足勢未知。","长嘶青海风，躞蹀振云絲。","由来渥洼種，本是蒼龙兒。","穆满不再活，無人崑閬騎。","君識躍嶠怯，寧勞耀金羈。","青芻與白水，空笑駑駘肥。","伯乐儻一见，應驚耳长垂。","當思八荒外，逐日向瑤池。"]', '诗', 'shi', '', NULL, '橫吹曲辭 驄馬 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f1e20b5-a8e4-45cd-a1e2-45710eec46fb', '橫吹曲辭 驄馬曲', '橫吹曲辞 驄马曲', '89f94449-ac92-404d-b909-316245450dfd', '唐', '["連錢出塞蹋沙蓬，豈比當時御史驄。","逐北自諳深磧路，連嘶誰念靜邊功。","登山每與青雲合，弄影應知碧草同。","今日虜平將換妾，不如羅袖舞春風。"]', '["連錢出塞蹋沙蓬，豈比當时御史驄。","逐北自諳深磧路，連嘶誰念静邊功。","登山每與青云合，弄影應知碧草同。","今日虜平將換妾，不如羅袖舞春风。"]', '诗', 'shi', '', NULL, '橫吹曲辭 驄馬曲 紀唐天 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a61fdeb6-e633-4c36-bb30-d57d1e392c1c', '橫吹曲辭 雨雪曲', '橫吹曲辞 雨雪曲', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["天山一丈雪，雜雨夜霏霏。","溼馬胡歌亂，經烽漢火微。","丁零蘇武別，疎勒范羌歸。","若著關頭過，長榆葉定稀。"]', '["天山一丈雪，杂雨夜霏霏。","溼马胡歌亂，經烽漢火微。","丁零蘇武別，疎勒范羌归。","若著关头過，长榆葉定稀。"]', '诗', 'shi', '', NULL, '橫吹曲辭 雨雪曲 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db40b5ca-03a8-4d1f-a4e4-cde477bee05e', '橫吹曲辭 雨雪曲', '橫吹曲辞 雨雪曲', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["邊聲四合殷河流，雨雪飛來徧隴頭。","鐵嶺探人迷鳥道，陰山飛將溼貂裘。","斜飄旌斾過戎帳，半雜風沙入戍樓。"]', '["邊声四合殷河流，雨雪飞来徧隴头。","鐵嶺探人迷鸟道，陰山飞將溼貂裘。","斜飄旌斾過戎帳，半杂风沙入戍楼。"]', '诗', 'shi', '', NULL, '橫吹曲辭 雨雪曲 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1aa5a8ef-0eb9-4029-b228-bc979d9f332e', '橫吹曲辭 劉生', '橫吹曲辞 劉生', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["劉生氣不平，抱劒欲專征。","報恩爲豪俠，死難在橫行。","翠羽裝劒鞘，黃金飾馬纓。","但令一顧重，不吝百身輕。"]', '["劉生氣不平，抱劒欲專征。","報恩爲豪俠，死难在橫行。","翠羽裝劒鞘，黄金飾马纓。","但令一顧重，不吝百身轻。"]', '诗', 'shi', '', NULL, '橫吹曲辭 劉生 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e1a40e5-4dea-4e85-bd84-3228170fc287', '橫吹曲辭 雍臺歌', '橫吹曲辞 雍台歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["太子池南樓百尺，八窗新樹疎簾隔。","黃金鋪首畫鉤陳，羽葆亭童拂交戟。","盤紆闌楯臨高臺，帳殿臨流鸞扇開。","早雁聲鳴細波起，映花鹵簿龍飛回。"]', '["太子池南楼百尺，八窗新樹疎簾隔。","黄金鋪首畫鉤陳，羽葆亭童拂交戟。","盤紆闌楯臨高台，帳殿臨流鸾扇开。","早雁声鳴細波起，映花鹵簿龙飞回。"]', '诗', 'shi', '', NULL, '橫吹曲辭 雍臺歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aef25d83-2ce0-4cb7-a958-65b5cc7a1620', '橫吹曲辭 捉搦歌', '橫吹曲辞 捉搦歌', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["門上關，牆上棘，窗中女子聲唧唧，洛陽大道徒自直。","女子心在婆舍側，嗚嗚籠鳥觸四隅。","養男男娶婦，養女女嫁夫。","阿婆六十翁七十，不知女子長日泣，從他嫁去無悒悒。"]', '["门上关，牆上棘，窗中女子声唧唧，洛陽大道徒自直。","女子心在婆舍側，嗚嗚籠鸟觸四隅。","養男男娶婦，養女女嫁夫。","阿婆六十翁七十，不知女子长日泣，從他嫁去無悒悒。"]', '诗', 'shi', '', NULL, '橫吹曲辭 捉搦歌 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e74b2d34-c0a4-4049-a02d-b2d9aa00fd80', '橫吹曲辭 幽州胡馬客歌', '橫吹曲辞 幽州胡马客歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["幽州胡馬客，綠眼虎皮冠。","笑拂兩隻箭，萬人不可干。","彎弓若轉月，白雁落雲端。","雙雙掉鞭行，遊獵向樓蘭。","出門不顧後，報國死何難。","天驕五單于，狼戾好凶殘。","牛馬散北海，割鮮若虎餐。","雖居燕支山，不道朔雪寒。","婦女馬上笑，顏如赬玉盤。","飜入射鳥獸，花月醉雕鞍。","旄頭四光芒，爭戰若蜂攢。","白刃灑赤血，流沙爲之丹。","名將古誰是，疲兵良可歎。","何時天狼滅？父子得閑安。"]', '["幽州胡马客，綠眼虎皮冠。","笑拂兩隻箭，万人不可干。","彎弓若轉月，白雁落云端。","雙雙掉鞭行，游獵向楼蘭。","出门不顧後，報国死何难。","天驕五單于，狼戾好凶殘。","牛马散北海，割鲜若虎餐。","雖居燕支山，不道朔雪寒。","婦女马上笑，顏如赬玉盤。","飜入射鸟獸，花月醉雕鞍。","旄头四光芒，爭戰若蜂攢。","白刃灑赤血，流沙爲之丹。","名將古誰是，疲兵良可歎。","何时天狼滅？父子得闲安。"]', '诗', 'shi', '', NULL, '橫吹曲辭 幽州胡馬客歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5f83ccf-1f85-4b43-87e5-b24df8131f39', '橫吹曲辭 白鼻騧', '橫吹曲辞 白鼻騧', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["銀鞍白鼻騧，綠地障泥錦。","細雨春風花落時，揮鞭且就胡姬飲。"]', '["銀鞍白鼻騧，綠地障泥錦。","細雨春风花落时，揮鞭且就胡姬饮。"]', '诗', 'shi', '', NULL, '橫吹曲辭 白鼻騧 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b412160a-39d1-46f6-8e10-424610aea93e', '橫吹曲辭 白鼻騧', '橫吹曲辞 白鼻騧', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["爲底胡姬酒，長來白鼻騧。","摘蓮拋水上，郎意在浮花。"]', '["爲底胡姬酒，长来白鼻騧。","摘蓮拋水上，郎意在浮花。"]', '诗', 'shi', '', NULL, '橫吹曲辭 白鼻騧 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('173dc126-6533-471f-bf00-5fc637471b64', '相和歌辭 箜篌引', '相和歌辞 箜篌引', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["公乎公乎，提壺將焉如？","屈平沈湘不足慕，徐衍入海誠爲愚。","公乎公乎，牀有菅席盤有魚。","北里有賢兄，東鄰有小姑。","隴畝油油黍與葫，瓦甒濁醪蟻浮浮。","黍可食，醪可飲，公乎公乎其奈居。","被髮奔流竟何如？賢兄小姑哭嗚嗚。"]', '["公乎公乎，提壺將焉如？","屈平沈湘不足慕，徐衍入海誠爲愚。","公乎公乎，牀有菅席盤有鱼。","北里有賢兄，东鄰有小姑。","隴畝油油黍與葫，瓦甒濁醪蟻浮浮。","黍可食，醪可饮，公乎公乎其奈居。","被髮奔流竟何如？賢兄小姑哭嗚嗚。"]', '诗', 'shi', '', NULL, '相和歌辭 箜篌引 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf5f4147-1e1c-4bb6-84ab-0e6a6a402325', '相和歌辭 公無渡河', '相和歌辞 公無渡河', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃河西來決崐崘，咆吼萬里觸龍門。","波滔天，堯咨嗟。","大禹理百川，兒啼不窺家。","殺湍湮洪水，九州始蠶麻。","其害乃去，茫然風沙。","被髮之叟狂而癡，清晨徑流欲奚爲。","旁人不惜妻止之，公無渡河苦渡之。","虎可搏，河難憑。","公果溺死流海湄，有長鯨白齒若雪山。","公乎公乎，挂骨於其間，箜篌所悲竟不還。"]', '["黄河西来決崐崘，咆吼万里觸龙门。","波滔天，堯咨嗟。","大禹理百川，兒啼不窺家。","殺湍湮洪水，九州始蠶麻。","其害乃去，茫然风沙。","被髮之叟狂而癡，清晨徑流欲奚爲。","旁人不惜妻止之，公無渡河苦渡之。","虎可搏，河难憑。","公果溺死流海湄，有长鯨白齒若雪山。","公乎公乎，挂骨於其间，箜篌所悲竟不還。"]', '诗', 'shi', '', NULL, '相和歌辭 公無渡河 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98ce6f68-fa8f-42b6-a5d6-5447079d3a04', '相和歌辭 公無渡河', '相和歌辞 公無渡河', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["渡頭惡天兩岸遠，波濤塞川如疊坂。","幸無白刃驅向前，何用將身自棄捐。","蛟龍齧屍魚食血，黃泥直下無青天。","男兒縱輕婦人語，惜君性命還須取。","婦人無力挽斷衣，舟沈身死悔難追，公無渡河公自爲。"]', '["渡头惡天兩岸远，波濤塞川如叠坂。","幸無白刃驱向前，何用將身自棄捐。","蛟龙齧屍鱼食血，黄泥直下無青天。","男兒縱轻婦人語，惜君性命還須取。","婦人無力挽斷衣，舟沈身死悔难追，公無渡河公自爲。"]', '诗', 'shi', '', NULL, '相和歌辭 公無渡河 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19afaf8e-aaa5-4a06-9e92-5fc4cdecb40c', '相和歌辭 公無渡河', '相和歌辞 公無渡河', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["黃河怒浪連天來，大響谹谹如殷雷。","龍伯驅風不敢上，百川噴雪高崔嵬。","二十五弦何太哀？請公勿渡立裴回。","下有狂蛟鋸爲尾，裂帆截櫂磨霜齒。","神錐鑿石塞神潭，白馬䟃𧽼赤塵起。","公乎躍馬揚玉鞭，滅沒高蹄日千里。"]', '["黄河怒浪連天来，大响谹谹如殷雷。","龙伯驱风不敢上，百川噴雪高崔嵬。","二十五弦何太哀？請公勿渡立裴回。","下有狂蛟鋸爲尾，裂帆截櫂磨霜齒。","神錐鑿石塞神潭，白马䟃𧽼赤塵起。","公乎躍马揚玉鞭，滅沒高蹄日千里。"]', '诗', 'shi', '', NULL, '相和歌辭 公無渡河 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fe01760-2d47-4df6-b61d-518cf952af9d', '相和歌辭 公無渡河', '相和歌辞 公無渡河', '1e83089e-457c-454a-aba3-02dac6374fc6', '唐', '["濁波洋洋兮凝曉霧，公無渡河兮公苦渡。","風號水激兮呼不聞，提壺看入兮中流去。","浪擺衣裳兮隨步沒，沈屍深入兮蛟螭窟。","蛟螭盡醉兮君血乾，推出黃沙兮泛君骨。","當時君死妾何適？遂就波瀾合魂魄。","願持精衛銜石心，窮取河源塞泉脈。"]', '["濁波洋洋兮凝晓霧，公無渡河兮公苦渡。","风號水激兮呼不闻，提壺看入兮中流去。","浪擺衣裳兮隨步沒，沈屍深入兮蛟螭窟。","蛟螭尽醉兮君血乾，推出黄沙兮泛君骨。","當时君死妾何適？遂就波瀾合魂魄。","願持精衛銜石心，窮取河源塞泉脈。"]', '诗', 'shi', '', NULL, '相和歌辭 公無渡河 王叡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edc474d8-bb0f-469e-9367-328d9aefb568', '相和歌辭 江南曲', '相和歌辞 江南曲', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["妾住越城南，離居不自堪。","採花驚曙鳥，摘葉餧春蠶。","嬾結茱萸帶，愁安玳瑁簪。","侍臣消瘦盡，日暮碧江潭。"]', '["妾住越城南，離居不自堪。","採花驚曙鸟，摘葉餧春蠶。","嬾結茱萸带，愁安玳瑁簪。","侍臣消瘦尽，日暮碧江潭。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ba4d426-8dd5-4a77-9566-98d96222417f', '相和歌辭 江南曲', '相和歌辞 江南曲', '60641e34-aad2-4bed-98a6-ae98ef7538d7', '唐', '["美人何蕩漾，湖上風月長。","玉手欲有贈，裴回雙鳴璫。","歌聲隨淥水，怨色起朝陽。","日暮還家望，雲波橫洞房。"]', '["美人何蕩漾，湖上风月长。","玉手欲有贈，裴回雙鳴璫。","歌声隨淥水，怨色起朝陽。","日暮還家望，云波橫洞房。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 劉眘虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('681ba31a-2c38-484a-ab65-f2b93d5e70c8', '相和歌辭 江南曲', '相和歌辞 江南曲', '6d93cdf1-8e8e-48f5-91b1-02c067000da9', '唐', '["長干斜路北，近浦是兒家。","有意來相訪，明朝出浣紗。","發向橫塘口，船開值急流。","知郎舊時意，且請攏船頭。","昨暝逗南陵，風聲波浪阻。","入浦不逢人，歸家誰信汝。","未曉已成妝，乘潮去茫茫。","因從京口渡，使報邵陵王。","始下芙蓉樓，言發琅邪岸。","急爲打船開，惡許傍人見。"]', '["长干斜路北，近浦是兒家。","有意来相訪，明朝出浣紗。","發向橫塘口，船开值急流。","知郎旧时意，且請攏船头。","昨暝逗南陵，风声波浪阻。","入浦不逢人，归家誰信汝。","未晓已成妝，乘潮去茫茫。","因從京口渡，使報邵陵王。","始下芙蓉楼，言發琅邪岸。","急爲打船开，惡許傍人见。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 丁仙芝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14fb10e9-07e9-4b03-97ad-680f40db3518', '相和歌辭 江南曲八首 一', '相和歌辞 江南曲八首 一', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["暮宿南洲草，晨行北岸林。","日懸滄海闊，水隔洞庭深。","煙景無留意，風波有異潯。","歲遊難極目，春戲易爲心。","朝夕無榮遇，芳菲已滿襟。"]', '["暮宿南洲草，晨行北岸林。","日懸滄海闊，水隔洞庭深。","煙景無留意，风波有異潯。","歲游难極目，春戲易爲心。","朝夕無榮遇，芳菲已满襟。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲八首 一 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26b530b0-e610-4d5c-b8a1-0d7a9b648dac', '相和歌辭 江南曲八首 二', '相和歌辞 江南曲八首 二', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["豔唱潮初落，江花露未晞。","春洲驚翡翠，朱服弄芳菲。","畫舫煙中淺，青陽日際微。","錦帆衝浪溼，羅袖拂行衣。","含情罷所采，相歎惜流暉。"]', '["豔唱潮初落，江花露未晞。","春洲驚翡翠，朱服弄芳菲。","畫舫煙中淺，青陽日際微。","錦帆衝浪溼，羅袖拂行衣。","含情罷所采，相歎惜流暉。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲八首 二 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3966527-45c8-469f-8d74-cc906151e51a', '相和歌辭 江南曲八首 三', '相和歌辞 江南曲八首 三', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["君爲隴西客，妾遇江南春。","朝遊含靈果，夕采弄風蘋。","果氣時不歇，蘋花日自新。","以此江南物，持贈隴西人。","空盈萬里懷，欲贈竟無因。"]', '["君爲隴西客，妾遇江南春。","朝游含靈果，夕采弄风蘋。","果氣时不歇，蘋花日自新。","以此江南物，持贈隴西人。","空盈万里懷，欲贈竟無因。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲八首 三 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5641758a-d34f-4d86-8631-5f0b17869fc3', '相和歌辭 江南曲八首 四', '相和歌辞 江南曲八首 四', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["皓如楚江月，靄若吳岫雲。","波中自皎鏡，山上亦氛氳。","明月留照妾，輕雲持贈君。","山川各離散，光氣乃殊分。","天涯一爲別，江北自相聞。"]', '["皓如楚江月，靄若吳岫云。","波中自皎镜，山上亦氛氳。","明月留照妾，轻云持贈君。","山川各離散，光氣乃殊分。","天涯一爲別，江北自相闻。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲八首 四 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae6937be-51cb-4b1f-b735-cfa0644fd547', '相和歌辭 江南曲八首 五', '相和歌辞 江南曲八首 五', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["艤舟乘潮去，風帆振草涼。","潮平見楚甸，天際望維揚。","洄泝經千里，煙波接兩鄉。","雲明江嶼出，日照海流長。","此中逢歲晏，浦樹落花芳。"]', '["艤舟乘潮去，风帆振草涼。","潮平见楚甸，天際望維揚。","洄泝經千里，煙波接兩乡。","云明江嶼出，日照海流长。","此中逢歲晏，浦樹落花芳。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲八首 五 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03999410-ba31-4a8a-8718-340aa7d38735', '相和歌辭 江南曲八首 六', '相和歌辞 江南曲八首 六', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["暮春三月晴，維揚吳楚城。","城臨大江汜，迴映洞浦清。","晴雲曲金閣，珠樓碧煙裏。","月明芳樹羣鳥飛，風過長林雜花起。","可憐離別誰家子，於此一至情何已。"]', '["暮春三月晴，維揚吳楚城。","城臨大江汜，迴映洞浦清。","晴云曲金閣，珠楼碧煙裏。","月明芳樹羣鸟飞，风過长林杂花起。","可怜離別誰家子，於此一至情何已。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲八首 六 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f7c6229-2a76-4879-821a-62a021153b46', '相和歌辭 江南曲八首 七', '相和歌辞 江南曲八首 七', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["北堂紅草盛丰茸，南湖碧水照芙蓉。","朝遊暮起金花盡，漸覺羅裳珠露濃。","自惜妍華三五歲，已歎關山千萬重。","人情一去無還日，欲贈懷芳怨不逢。"]', '["北堂紅草盛丰茸，南湖碧水照芙蓉。","朝游暮起金花尽，漸覺羅裳珠露濃。","自惜妍华三五歲，已歎关山千万重。","人情一去無還日，欲贈懷芳怨不逢。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲八首 七 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('368cbc24-d33d-4ef5-9940-c16acc077d73', '相和歌辭 江南曲八首 八', '相和歌辞 江南曲八首 八', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["憶昔江南年盛時，平生怨在長洲曲。","冠蓋星繁湘水上，衝風摽落洞庭淥。","落花舞袖紅紛紛，朝霞高閣洗晴雲。","誰言此處嬋娟子，珠玉爲心以奉君。"]', '["憶昔江南年盛时，平生怨在长洲曲。","冠蓋星繁湘水上，衝风摽落洞庭淥。","落花舞袖紅紛紛，朝霞高閣洗晴云。","誰言此处嬋娟子，珠玉爲心以奉君。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲八首 八 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e1e7436-6f97-47ee-8d91-e540fe2b1edc', '相和歌辭 江南曲', '相和歌辞 江南曲', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["偶向江邊采白蘋，還隨女伴賽江神。","衆中不敢分明語，暗擲金錢卜遠人。"]', '["偶向江邊采白蘋，還隨女伴賽江神。","衆中不敢分明語，暗擲金錢卜远人。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb111748-d8f1-4a5e-b618-b70272a7a642', '相和歌辭 江南曲', '相和歌辞 江南曲', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["嫁得瞿塘賈，朝朝誤妾期。","早知潮有信，嫁與弄潮兒。"]', '["嫁得瞿塘賈，朝朝誤妾期。","早知潮有信，嫁與弄潮兒。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17cd4a8b-9987-47b8-9d44-034c98f8f939', '相和歌辭 江南曲', '相和歌辞 江南曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["汀洲白蘋草，柳惲乘馬歸。","江頭樝樹香，岸上蝴蝶飛。","酒杯若葉露，玉軫蜀桐虛。","朱樓通水陌，沙暖一雙魚。"]', '["汀洲白蘋草，柳惲乘马归。","江头樝樹香，岸上蝴蝶飞。","酒杯若葉露，玉軫蜀桐虛。","朱楼通水陌，沙暖一雙鱼。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7236d790-13a8-44f2-8770-9802bb525db4', '相和歌辭 江南曲', '相和歌辞 江南曲', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["郎船安兩槳，儂舸動雙橈。","埽黛開宮額，裁裙約楚腰。","乖期方積思，臨醉欲拚嬌。","莫以采菱唱，欲羨秦臺簫。"]', '["郎船安兩槳，儂舸动雙橈。","埽黛开宮額，裁裙約楚腰。","乖期方積思，臨醉欲拚嬌。","莫以采菱唱，欲羨秦台簫。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d10fdb5-9d0a-4c80-9e21-27f82b929c9f', '相和歌辭 江南曲', '相和歌辞 江南曲', '77895f9a-8a15-4992-974c-58d1b01c372b', '唐', '["長樂花枝雨點消，江城日暮好相邀。","春樓不閉葳蕤鎖，綠水回通宛轉橋。"]', '["长乐花枝雨点消，江城日暮好相邀。","春楼不閉葳蕤鎖，綠水回通宛轉橋。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 韓翃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('809c98e4-2997-4bfa-bb77-b5a64b696a26', '相和歌辭 江南曲', '相和歌辞 江南曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["妾家白蘋浦，日上芙蓉檝。","軋軋搖槳聲，移舟入茭葉。","溪長茭葉深，作底難相尋。","避郎郎不見，鸂鶒自浮沈。","拾萍萍無根，采蓮蓮有子。","不作浮萍生，寧作藕花死。","岸傍騎馬郎，烏帽紫游韁。","含愁復含笑，回首問橫塘。","妾住金陵步，門前朱雀航。","流蘇持作帳，芙蓉持作梁。","出入金犢幰，兄弟侍中郎。","前年學歌舞，定得郎相許。","連娟眉繞山，依約腰如杵。","鳳管悲若咽，鸞弦嬌欲語。","扇薄露紅鈆，羅輕壓金縷。","明月西南樓，珠簾玳瑁鉤。","橫波巧能笑，彎蛾不識愁。","花開子留樹，草長根依土。","早聞金溝遠，底事歸郎許。","不學楊白花，朝朝淚如雨。"]', '["妾家白蘋浦，日上芙蓉檝。","軋軋搖槳声，移舟入茭葉。","溪长茭葉深，作底难相尋。","避郎郎不见，鸂鶒自浮沈。","拾萍萍無根，采蓮蓮有子。","不作浮萍生，寧作藕花死。","岸傍騎马郎，烏帽紫游韁。","含愁复含笑，回首问橫塘。","妾住金陵步，门前朱雀航。","流蘇持作帳，芙蓉持作梁。","出入金犢幰，兄弟侍中郎。","前年学歌舞，定得郎相許。","連娟眉繞山，依約腰如杵。","鳳管悲若咽，鸾弦嬌欲語。","扇薄露紅鈆，羅轻壓金縷。","明月西南楼，珠簾玳瑁鉤。","橫波巧能笑，彎蛾不識愁。","花开子留樹，草长根依土。","早闻金溝远，底事归郎許。","不学楊白花，朝朝泪如雨。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0f731fe-706b-4e7e-a27c-db14c06686e9', '相和歌辭 江南曲', '相和歌辞 江南曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["江南人家多橘樹，吳姬舟上織白紵。","土地卑溼饒蟲蛇，連木爲牌入江住。","江村亥日長爲市，落帆渡橋來浦裏。","青莎覆城竹爲屋，無井家家飲潮水。","長江午日酤春酒，高高酒旗懸江口。","倡樓兩岸懸水柵，夜唱竹枝留北客。","江南風土歡樂多，悠悠處處盡經過。"]', '["江南人家多橘樹，吳姬舟上织白紵。","土地卑溼饒蟲蛇，連木爲牌入江住。","江村亥日长爲市，落帆渡橋来浦裏。","青莎覆城竹爲屋，無井家家饮潮水。","长江午日酤春酒，高高酒旗懸江口。","倡楼兩岸懸水柵，夜唱竹枝留北客。","江南风土歡乐多，悠悠处处尽經過。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('163e6b84-544c-426c-820f-0b6bac718a2d', '相和歌辭 江南曲', '相和歌辞 江南曲', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["江煙溼雨鮫綃輭，漠漠遠山眉黛淺。","水國多愁又有情，夜槽壓酒銀船滿。","綳絲採怨凝曉空，吳王臺榭春夢中。","鴛鴦鸂鶒喚不起，平鋪淥水眠東風。","西陵路邊月悄悄，油壁輕車嫁蘇小。"]', '["江煙溼雨鮫綃輭，漠漠远山眉黛淺。","水国多愁又有情，夜槽壓酒銀船满。","綳絲採怨凝晓空，吳王台榭春梦中。","鴛鴦鸂鶒喚不起，平鋪淥水眠东风。","西陵路邊月悄悄，油壁轻车嫁蘇小。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee8b870e-a2de-45e4-8fa6-a805e3ae1f7c', '相和歌辭 江南曲', '相和歌辞 江南曲', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["爲愛江南雪，涉江聊采蘋。","水深煙浩浩，空對雙車輪。","車輪明月團，車蓋浮雲盤。","雲月徒自好，水中行路難。","遙遙洛陽道，夾岸生春草。","寄語櫂船郎，莫誇風浪好。"]', '["爲愛江南雪，涉江聊采蘋。","水深煙浩浩，空对雙车輪。","车輪明月團，车蓋浮云盤。","云月徒自好，水中行路难。","遙遙洛陽道，夾岸生春草。","寄語櫂船郎，莫誇风浪好。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('490c972f-cb5e-4289-a26f-c65b2aff10b0', '相和歌辭 江南曲 一', '相和歌辞 江南曲 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魚戲蓮葉間，參差隱葉扇。","鵁鶄鸀鳿窺，瀲灩無因見。"]', '["鱼戲蓮葉间，參差隐葉扇。","鵁鶄鸀鳿窺，瀲灩無因见。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7420cc4b-1eb0-4532-9261-c1d70fbfe100', '相和歌辭 江南曲 二', '相和歌辞 江南曲 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魚戲蓮葉東，初霞射紅尾。","傍臨謝山側，恰值清風起。"]', '["鱼戲蓮葉东，初霞射紅尾。","傍臨謝山側，恰值清风起。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97b95df2-6c44-40aa-bd1c-f06aee6ceecf', '相和歌辭 江南曲 三', '相和歌辞 江南曲 三', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魚戲蓮葉西，盤盤舞波急。","潛依曲岸涼，正對斜光入。"]', '["鱼戲蓮葉西，盤盤舞波急。","潛依曲岸涼，正对斜光入。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 三 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49e10d3e-1925-4cb0-8fec-a96b79ed1ee8', '相和歌辭 江南曲 四', '相和歌辞 江南曲 四', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魚戲蓮葉南，欹危午煙疊。","光搖越鳥巢，影亂吳娃檝。"]', '["鱼戲蓮葉南，欹危午煙叠。","光搖越鸟巢，影亂吳娃檝。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 四 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee469591-8d2e-4541-8613-094aaf82d305', '相和歌辭 江南曲 五', '相和歌辞 江南曲 五', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["魚戲蓮葉北，澄陽動微漣。","回看帝子渚，稍背鄂君船。"]', '["鱼戲蓮葉北，澄陽动微漣。","回看帝子渚，稍背鄂君船。"]', '诗', 'shi', '', NULL, '相和歌辭 江南曲 五 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a39a22f1-14e7-4819-951f-9058b30590fa', '相和歌辭 度關山', '相和歌辞 度关山', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["雁塞日初晴，胡關雪復平。","危竿緣廣漠，古竇傍長城。","拔劒金星出，彎弧玉羽鳴。","誰知係虜者，賈誼是書生。"]', '["雁塞日初晴，胡关雪复平。","危竿緣廣漠，古竇傍长城。","拔劒金星出，彎弧玉羽鳴。","誰知係虜者，賈誼是书生。"]', '诗', 'shi', '', NULL, '相和歌辭 度關山 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af064f9d-ff81-401e-b209-e6c98d94d4f2', '相和歌辭 關山曲 一', '相和歌辞 关山曲 一', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["金鎖耀兜鍪，黃雲拂紫騮。","叛羌旗下戮，陷壁夜中收。","霜霰戎衣故，關河磧氣秋。","箭創殊未合，更遣擊蘭州。"]', '["金鎖耀兜鍪，黄云拂紫騮。","叛羌旗下戮，陷壁夜中收。","霜霰戎衣故，关河磧氣秋。","箭創殊未合，更遣擊蘭州。"]', '诗', 'shi', '', NULL, '相和歌辭 關山曲 一 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12981488-9d66-47cf-9c20-7c1efe64f199', '相和歌辭 關山曲 二', '相和歌辞 关山曲 二', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["火發龍山北，中宵易左賢。","勒兵臨漢水，驚雁散胡天。","木落防河急，軍孤受敵偏。","猶聞漢皇怒，按劒待開邊。"]', '["火發龙山北，中宵易左賢。","勒兵臨漢水，驚雁散胡天。","木落防河急，軍孤受敵偏。","猶闻漢皇怒，按劒待开邊。"]', '诗', 'shi', '', NULL, '相和歌辭 關山曲 二 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d7fc8a1-0d5c-4a78-924c-01b1889059f8', '相和歌辭 登高丘而望遠', '相和歌辞 登高丘而望远', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["登高丘而望遠海，六鼇骨已霜，三山流安在。","扶桑半摧折，白日沈光彩。","銀臺金闕如夢中，秦皇漢武空相待。","精衛費木石，黿鼉無所憑。","君不見驪山茂陵盡灰滅，牧羊之子來攀登。","盜賊劫寶玉，精靈竟何能。"]', '["登高丘而望远海，六鼇骨已霜，三山流安在。","扶桑半摧折，白日沈光彩。","銀台金闕如梦中，秦皇漢武空相待。","精衛費木石，黿鼉無所憑。","君不见驪山茂陵尽灰滅，牧羊之子来攀登。","盜賊劫寶玉，精靈竟何能。"]', '诗', 'shi', '', NULL, '相和歌辭 登高丘而望遠 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e457b1c-8c36-46fe-bca9-14cf644ec9ca', '相和歌辭 蒿里', '相和歌辞 蒿里', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["兔不遲，烏更急，但恐穆王八駿，著鞭不及。","所以蒿里，墳出蕺蕺，氣凌雲天，龍騰鳳集，盡爲風消土喫，狐掇蟻拾。","黃金不啼玉不泣，白楊騷屑。","亂風愁月，折碑石人。","莽穢榛沒，牛羊窸窣。","時見牧童兒，弄枯骨。"]', '["兔不遲，烏更急，但恐穆王八駿，著鞭不及。","所以蒿里，墳出蕺蕺，氣凌云天，龙腾鳳集，尽爲风消土喫，狐掇蟻拾。","黄金不啼玉不泣，白楊騷屑。","亂风愁月，折碑石人。","莽穢榛沒，牛羊窸窣。","时见牧童兒，弄枯骨。"]', '诗', 'shi', '', NULL, '相和歌辭 蒿里 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa7d3545-a694-4336-8852-5d491c106b50', '相和歌辭 輓歌', '相和歌辞 輓歌', '56c46543-e89e-4b9a-8fb8-6d9f0b651f77', '唐', '["寒日蒿上明，淒淒郭東路。","素車誰家子，丹旐引將去。","原下荆棘叢，叢邊有新墓。","人間痛傷別，此是長別處。","曠野何蕭條，青松白楊樹。"]', '["寒日蒿上明，淒淒郭东路。","素车誰家子，丹旐引將去。","原下荆棘叢，叢邊有新墓。","人间痛傷別，此是长別处。","曠野何蕭條，青松白楊樹。"]', '诗', 'shi', '', NULL, '相和歌辭 輓歌 趙微明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcd31207-66ec-44c9-9890-1c70b6e8ea69', '相和歌辭 輓歌二首 一', '相和歌辞 輓歌二首 一', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["陰風吹黃蒿，輓歌渡秋水。","車馬却歸城，孤墳月明裏。"]', '["陰风吹黄蒿，輓歌渡秋水。","车马却归城，孤墳月明裏。"]', '诗', 'shi', '', NULL, '相和歌辭 輓歌二首 一 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f4c3465-566a-4a92-886d-20155ea07a0e', '相和歌辭 輓歌二首 二', '相和歌辞 輓歌二首 二', 'ae390033-daab-4b86-b818-5f7dd8abc410', '唐', '["雙轍出郭門，緜緜東西道。","送死多於生，幾人得終老。","見人切肺肝，不如歸山好。","不聞哀哭聲，默默安懷抱。","時盡從物化，又免生憂擾。","世間壽者稀，盡爲悲傷惱。"]', '["雙轍出郭门，緜緜东西道。","送死多於生，幾人得終老。","见人切肺肝，不如归山好。","不闻哀哭声，默默安懷抱。","时尽從物化，又免生憂擾。","世间壽者稀，尽爲悲傷惱。"]', '诗', 'shi', '', NULL, '相和歌辭 輓歌二首 二 于鵠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('947e5189-4418-49fd-898a-9f7118777a2e', '相和歌辭 輓歌', '相和歌辞 輓歌', 'aafdb19f-05e9-4e14-911a-2b39ebf7f1af', '唐', '["草草門巷喧，塗車儼成位。","冥寞何所須，盡我生人意。","北邙路非遠，此別終天地。","臨穴頻撫棺，至哀反無淚。","爾形未衰老，爾息猶童穉。","骨肉不可離，皇天若容易。","房帷即虛張，庭宇爲哀次。","薤露歌若斯，人生盡如寄。"]', '["草草门巷喧，塗车儼成位。","冥寞何所須，尽我生人意。","北邙路非远，此別終天地。","臨穴頻撫棺，至哀反無泪。","爾形未衰老，爾息猶童穉。","骨肉不可離，皇天若容易。","房帷即虛張，庭宇爲哀次。","薤露歌若斯，人生尽如寄。"]', '诗', 'shi', '', NULL, '相和歌辭 輓歌 孟雲卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f3870ea-0cc1-4829-971c-b9f5fc7283a9', '相和歌辭 輓歌', '相和歌辞 輓歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["丹旐何飛揚，素驂亦悲鳴。","晨光照閭巷，輀車儼欲行。","蕭條九月天，哀輓出重城。","借問送者誰，妻子與弟兄。","蒼蒼上古原，峨峨開新塋。","含酸一慟哭，異口同哀聲。","舊壟轉蕪絕，新墳日羅列。","春風草綠北邙山，此地年年生死別。"]', '["丹旐何飞揚，素驂亦悲鳴。","晨光照閭巷，輀车儼欲行。","蕭條九月天，哀輓出重城。","借问送者誰，妻子與弟兄。","蒼蒼上古原，峨峨开新塋。","含酸一慟哭，異口同哀声。","旧壟轉蕪絕，新墳日羅列。","春风草綠北邙山，此地年年生死別。"]', '诗', 'shi', '', NULL, '相和歌辭 輓歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14617b67-715a-4a36-bd2d-49c12aade4f1', '相和歌辭 對酒', '相和歌辞 对酒', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["行行日將夕，荒村古冢無人跡。","朦朧荆棘一鳥飛，屢唱提壺酤酒喫。","古人不達酒不足，遺恨精靈傳此曲。","寄言當代諸少年，平生且盡杯中淥。"]', '["行行日將夕，荒村古冢無人跡。","朦朧荆棘一鸟飞，屢唱提壺酤酒喫。","古人不達酒不足，遺恨精靈傳此曲。","寄言當代諸少年，平生且尽杯中淥。"]', '诗', 'shi', '', NULL, '相和歌辭 對酒 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e959f72-69b2-4d3e-82b7-8a5a017c9a4d', '相和歌辭 對酒二首 一', '相和歌辞 对酒二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["松子棲金華，安期入蓬海。","此人古之仙，羽化竟何在？","浮生速流電，倏忽變光彩。","天地無凋換，容顏有遷改。","對酒不肯飲，含情欲誰待。"]', '["松子棲金华，安期入蓬海。","此人古之仙，羽化竟何在？","浮生速流電，倏忽变光彩。","天地無凋換，容顏有遷改。","对酒不肯饮，含情欲誰待。"]', '诗', 'shi', '', NULL, '相和歌辭 對酒二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e943ad5-c823-4036-935d-e5d20f3c6ab1', '相和歌辭 對酒二首 二', '相和歌辞 对酒二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["勸君莫拒杯，春風笑人來。","桃李如舊識，傾花向我開。","流鶯啼碧樹，明月窺金罍。","昨來朱顏子，今日白髮催。","棘生石虎殿，鹿走姑蘇臺。","自古帝王宅，城闕閉黃埃。","君若不飲酒，昔人安在哉。"]', '["勸君莫拒杯，春风笑人来。","桃李如旧識，傾花向我开。","流鶯啼碧樹，明月窺金罍。","昨来朱顏子，今日白髮催。","棘生石虎殿，鹿走姑蘇台。","自古帝王宅，城闕閉黄埃。","君若不饮酒，昔人安在哉。"]', '诗', 'shi', '', NULL, '相和歌辭 對酒二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7abc715-139b-4987-b57d-c7dacdd8fe6b', '相和歌辭 陌上桑', '相和歌辞 陌上桑', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["美女渭橋東，春還事蠶作。","五馬如飛龍，青絲結金絡。","不知誰家子，調笑來相謔。","妾本秦羅敷，玉顏豔名都。","綠條映素手，采桑向城隅。","使君且不顧，況復論秋胡。","寒螿愛碧草，鳴鳳棲青梧。","託心自有處，但怪傍人愚。","徒令白日暮，高駕空踟躕。"]', '["美女渭橋东，春還事蠶作。","五马如飞龙，青絲結金絡。","不知誰家子，調笑来相謔。","妾本秦羅敷，玉顏豔名都。","綠條映素手，采桑向城隅。","使君且不顧，況复論秋胡。","寒螿愛碧草，鳴鳳棲青梧。","託心自有处，但怪傍人愚。","徒令白日暮，高駕空踟躕。"]', '诗', 'shi', '', NULL, '相和歌辭 陌上桑 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d7db01d-48b4-4f83-8627-41b98b7321a9', '相和歌辭 陌上桑', '相和歌辞 陌上桑', '9c9beb6d-5d90-4816-949d-64b2f0d313d0', '唐', '["翳翳陌上桑，南枝交北堂。","美人金梯出，素手自提筐。","非但畏蠶飢，盈盈嬌路傍。"]', '["翳翳陌上桑，南枝交北堂。","美人金梯出，素手自提筐。","非但畏蠶飢，盈盈嬌路傍。"]', '诗', 'shi', '', NULL, '相和歌辭 陌上桑 常建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1372dba-e0d3-4c51-9d76-cb7809667d5f', '相和歌辭 陌上桑', '相和歌辞 陌上桑', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["皓齒還如貝色含，長眉亦似煙華貼。","鄰娃盡著繡襠襦，獨自提筐采蠶葉。"]', '["皓齒還如貝色含，长眉亦似煙华貼。","鄰娃尽著繡襠襦，独自提筐采蠶葉。"]', '诗', 'shi', '', NULL, '相和歌辭 陌上桑 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34008677-edfe-404c-92e8-547a08a9c815', '相和歌辭 采桑', '相和歌辞 采桑', 'aff13fc2-5a00-4377-82e1-6a8e636e4aaf', '唐', '["春來南雁歸，日去西蠶遠。","妾思紛何極，客遊殊未返。"]', '["春来南雁归，日去西蠶远。","妾思紛何極，客游殊未返。"]', '诗', 'shi', '', NULL, '相和歌辭 采桑 郎大家宋氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4e3c78d-a404-4910-8e0d-aca1f0a29f2b', '相和歌辭 采桑', '相和歌辞 采桑', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["楊柳送行人，青青西入秦。","秦家采桑女，樓上不勝春。","盈盈灞水曲，步步春芳綠。","紅臉耀明珠，絳脣含白玉。","回首渭橋東，遙憐樹色同。","青絲嬌落日，緗綺弄春風。","攜籠長歎息，逶迤戀春色。","看花若有情，倚樹疑無力。","薄暮思悠悠，使君南陌頭。","相逢不相識，歸去夢青樓。"]', '["楊柳送行人，青青西入秦。","秦家采桑女，楼上不勝春。","盈盈灞水曲，步步春芳綠。","紅臉耀明珠，絳脣含白玉。","回首渭橋东，遙怜樹色同。","青絲嬌落日，緗綺弄春风。","携籠长歎息，逶迤戀春色。","看花若有情，倚樹疑無力。","薄暮思悠悠，使君南陌头。","相逢不相識，归去梦青楼。"]', '诗', 'shi', '', NULL, '相和歌辭 采桑 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eb294ff-6032-4f91-afd7-f7b0260d1480', '相和歌辭 采桑', '相和歌辞 采桑', '4f68454a-d301-4ce9-9c71-9d4f8e5d7f66', '唐', '["采桑畏日高，不待春眠足。","攀條有餘愁，那矜貌如玉。","千金豈不贈，五馬空踟躅。","何以變真性，幽篁雪中綠。"]', '["采桑畏日高，不待春眠足。","攀條有餘愁，那矜貌如玉。","千金豈不贈，五马空踟躅。","何以变真性，幽篁雪中綠。"]', '诗', 'shi', '', NULL, '相和歌辭 采桑 李彥暐 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81d604a7-0eb8-4a36-9a8d-a9cb7a31f312', '相和歌辭 采桑', '相和歌辞 采桑', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["鳥鳴桑葉間，葉綠條復柔。","攀看去手近，放下長長鉤。","黃花蓋野田，白馬少年遊。","所念豈回顧，良人在高樓。"]', '["鸟鳴桑葉间，葉綠條复柔。","攀看去手近，放下长长鉤。","黄花蓋野田，白马少年游。","所念豈回顧，良人在高楼。"]', '诗', 'shi', '', NULL, '相和歌辭 采桑 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08cf0ce8-bd26-4bab-a4d2-5bc43acf8376', '相和歌辭 日出行', '相和歌辞 日出行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["日出東方隈，似從地底來。","歷天又入海，六龍所舍安在哉？","其始與終古不息，人非元氣安能與之久裴回。","草不謝榮於春風，木不怨落於秋天。","誰揮鞭策驅四運，萬物興歇皆自然。","羲和羲和，汝奚汩沒於荒淫之波。","魯陽何德？駐景揮戈。","逆道違天，矯誣實多。","吾將囊括大塊，浩然與溟涬同科。"]', '["日出东方隈，似從地底来。","歷天又入海，六龙所舍安在哉？","其始與終古不息，人非元氣安能與之久裴回。","草不謝榮於春风，木不怨落於秋天。","誰揮鞭策驱四運，万物兴歇皆自然。","羲和羲和，汝奚汩沒於荒淫之波。","魯陽何德？駐景揮戈。","逆道違天，矯誣實多。","吾將囊括大塊，浩然與溟涬同科。"]', '诗', 'shi', '', NULL, '相和歌辭 日出行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7af5f435-0357-4ff6-ab62-97417d87a31a', '相和歌辭 日出行', '相和歌辞 日出行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["白日下崐崘，發光如舒絲。","徒照葵藿心，不照遊子悲。","折折黃河曲，日從中央轉。","暘谷耳曾聞，若木眼不見。","奈何鑠石，胡爲銷人。","羿彎弓屬矢那不中，足令久不得奔，詎教晨光夕昏。"]', '["白日下崐崘，發光如舒絲。","徒照葵藿心，不照游子悲。","折折黄河曲，日從中央轉。","暘谷耳曾闻，若木眼不见。","奈何鑠石，胡爲銷人。","羿彎弓屬矢那不中，足令久不得奔，詎教晨光夕昏。"]', '诗', 'shi', '', NULL, '相和歌辭 日出行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6da7aaf4-ed2a-49b3-97d9-b33860fa6283', '相和歌辭 王昭君', '相和歌辞 王昭君', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["漢使南還盡，胡中妾獨存。","紫臺緜望絕，秋草不堪論。"]', '["漢使南還尽，胡中妾独存。","紫台緜望絕，秋草不堪論。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db7616cc-91ef-47be-92e6-66a0cf9d06bc', '相和歌辭 王昭君', '相和歌辞 王昭君', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["一回望月一回悲，望月月移人不移。","何時得見漢朝使？爲妾傳書斬畫師。"]', '["一回望月一回悲，望月月移人不移。","何时得见漢朝使？爲妾傳书斬畫師。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95039e34-843d-473f-a835-9355b2d766e8', '相和歌辭 王昭君', '相和歌辞 王昭君', '0287dd77-babe-4297-8d18-25097156b4ab', '唐', '["合殿恩中絕，交河使漸稀。","肝腸辭玉輦，形影向金微。","漢宮草應綠，胡庭沙正飛。","願逐三秋雁，年年一度歸。"]', '["合殿恩中絕，交河使漸稀。","肝腸辞玉輦，形影向金微。","漢宮草應綠，胡庭沙正飞。","願逐三秋雁，年年一度归。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 盧照鄰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ebb0f4eb-6bff-4311-8737-c7f82b8258f8', '相和歌辭 王昭君', '相和歌辞 王昭君', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["斂容辭豹尾，緘怨度龍鱗。","金鈿明漢月，玉箸染胡塵。","妝鏡菱花暗，愁眉柳葉嚬。","惟有清笳曲，時聞芳樹春。"]', '["斂容辞豹尾，緘怨度龙鱗。","金鈿明漢月，玉箸染胡塵。","妝镜菱花暗，愁眉柳葉嚬。","惟有清笳曲，时闻芳樹春。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7867962-cf6d-4ac7-b097-3c053429b6bc', '相和歌辭 王昭君', '相和歌辞 王昭君', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["非君惜鸞殿，非妾妬蛾眉。","薄命由驕虜，無情是畫師。","嫁來胡地惡，不竝漢宮時。","心苦無聊賴，何堪上馬辭。"]', '["非君惜鸾殿，非妾妬蛾眉。","薄命由驕虜，無情是畫師。","嫁来胡地惡，不竝漢宮时。","心苦無聊賴，何堪上马辞。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28961dad-9610-4863-97e5-ed7f94802432', '相和歌辭 王昭君', '相和歌辞 王昭君', '5d53dd79-ea92-4f70-8c91-ab719dffdd03', '唐', '["圖畫失天真，容華坐誤人。","君恩不可再，妾命在和親。","淚點關山月，衣銷邊塞塵。","一聞陽鳥至，思絕漢宮春。"]', '["圖畫失天真，容华坐誤人。","君恩不可再，妾命在和親。","泪点关山月，衣銷邊塞塵。","一闻陽鸟至，思絕漢宮春。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 梁獻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f43fea55-bab0-4d3a-bf40-f3664667f8e5', '相和歌辭 王昭君', '相和歌辞 王昭君', '48b636dd-bb3d-48e6-9f11-155dc7f45dfe', '唐', '["玉關春色晚，金河路幾千。","琴悲桂條上，笛怨柳花前。","霧掩臨妝月，風驚入鬢蟬。","緘書待還使，淚盡白雲天。"]', '["玉关春色晚，金河路幾千。","琴悲桂條上，笛怨柳花前。","霧掩臨妝月，风驚入鬢蟬。","緘书待還使，泪尽白云天。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 上官儀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('674553ed-a7c1-4287-9bf8-3fccf70db348', '相和歌辭 王昭君', '相和歌辞 王昭君', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["琵琶馬上彈，行路曲中難。","漢月正南遠，燕山直北寒。","髻鬟風拂散，眉黛雪霑殘。","斟酌紅顏盡，何勞鏡裏看。"]', '["琵琶马上彈，行路曲中难。","漢月正南远，燕山直北寒。","髻鬟风拂散，眉黛雪霑殘。","斟酌紅顏尽，何勞镜裏看。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e334ed8-698b-4297-ab7a-64cc5b4c45ef', '相和歌辭 王昭君', '相和歌辞 王昭君', 'e12c3791-f522-45b8-a5fb-d995f76cb846', '唐', '["莫將鉛粉匣，不用鏡花光。","一去邊城路，何情更畫妝。","影銷胡地月，衣盡漢宮香。","妾死非關命，祗緣怨斷腸。"]', '["莫將鉛粉匣，不用镜花光。","一去邊城路，何情更畫妝。","影銷胡地月，衣尽漢宮香。","妾死非关命，祗緣怨斷腸。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 顧朝陽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36597939-2dd3-4fd3-8bb9-cb4bdfd1c0f6', '相和歌辭 王昭君三首 一', '相和歌辞 王昭君三首 一', '19ab5456-dfc3-4387-9188-e44ca77aa8fb', '唐', '["漢道初全盛，朝廷足武臣。","何須薄命妾，辛苦事和親。"]', '["漢道初全盛，朝廷足武臣。","何須薄命妾，辛苦事和親。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君三首 一 東方虯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ceaf4b9-1baf-4fa1-ab59-a749cde469e2', '相和歌辭 王昭君三首 二', '相和歌辞 王昭君三首 二', '19ab5456-dfc3-4387-9188-e44ca77aa8fb', '唐', '["揜涕辭丹鳳，銜悲向白龍。","單于浪驚喜，無復舊時容。"]', '["揜涕辞丹鳳，銜悲向白龙。","單于浪驚喜，無复旧时容。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君三首 二 東方虯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbeea8e4-80b4-4dbf-801c-642990725c35', '相和歌辭 王昭君三首 三', '相和歌辞 王昭君三首 三', '19ab5456-dfc3-4387-9188-e44ca77aa8fb', '唐', '["胡地無花草，春來不似春。","自然衣帶緩，非是爲腰身。"]', '["胡地無花草，春来不似春。","自然衣带緩，非是爲腰身。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君三首 三 東方虯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94f427e0-5458-4671-b38e-4810ec5c200e', '相和歌辭 王昭君三首 一', '相和歌辞 王昭君三首 一', '21ff9f86-72e1-4ef1-9e34-944b1639b174', '唐', '["自嫁單于國，長銜漢掖悲。","容顏日顦顇，有甚畫圖時。"]', '["自嫁單于国，长銜漢掖悲。","容顏日顦顇，有甚畫圖时。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君三首 一 郭元振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73edcbbc-36f8-46da-ab45-87e127ca5b5b', '相和歌辭 王昭君三首 二', '相和歌辞 王昭君三首 二', '21ff9f86-72e1-4ef1-9e34-944b1639b174', '唐', '["厭踐冰霜域，嗟爲邊塞人。","思從漢南獵，一見漢家塵。"]', '["厭踐冰霜域，嗟爲邊塞人。","思從漢南獵，一见漢家塵。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君三首 二 郭元振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b263cbc5-dd18-48af-a7d2-694e836d8408', '相和歌辭 王昭君三首 三', '相和歌辞 王昭君三首 三', '21ff9f86-72e1-4ef1-9e34-944b1639b174', '唐', '["聞有南河信，傳聞殺畫師。","始知君惠重，更遣畫蛾眉。"]', '["闻有南河信，傳闻殺畫師。","始知君惠重，更遣畫蛾眉。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君三首 三 郭元振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('417dd972-fc55-4972-b698-e5e595453dbd', '相和歌辭 王昭君', '相和歌辞 王昭君', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["自矜妖豔色，不顧丹青人。","那知粉繢能相負，却使容華飜誤身。","上馬辭君嫁驕虜，玉顏對人啼不語。","北風雁急浮清秋，萬里獨見黃河流。","纖腰不復漢宮寵，雙蛾長向胡天愁。","琵琶弦中苦調多，蕭蕭羌笛聲相和。","可憐一曲傳樂府，能使千秋傷綺羅。"]', '["自矜妖豔色，不顧丹青人。","那知粉繢能相負，却使容华飜誤身。","上马辞君嫁驕虜，玉顏对人啼不語。","北风雁急浮清秋，万里独见黄河流。","纖腰不复漢宮寵，雙蛾长向胡天愁。","琵琶弦中苦調多，蕭蕭羌笛声相和。","可怜一曲傳乐府，能使千秋傷綺羅。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7351694b-3849-44b6-a7b6-8f46e00f8041', '相和歌辭 王昭君二首 一', '相和歌辞 王昭君二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢家秦地月，流影照明妃。","一上玉關道，天涯去不歸。","漢月還從東海出，明妃西嫁無來日。","燕支長寒雪作花，蛾眉顦顇沒胡沙。","生乏黃金枉圖畫，死留青冢使人嗟。"]', '["漢家秦地月，流影照明妃。","一上玉关道，天涯去不归。","漢月還從东海出，明妃西嫁無来日。","燕支长寒雪作花，蛾眉顦顇沒胡沙。","生乏黄金枉圖畫，死留青冢使人嗟。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d859edea-5188-4d7f-b4c2-f281d106bd59', '相和歌辭 王昭君二首 二', '相和歌辞 王昭君二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["昭君拂玉鞍，上馬啼紅頰。","今日漢宮人，明朝胡地妾。"]', '["昭君拂玉鞍，上马啼紅頰。","今日漢宮人，明朝胡地妾。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('232f0a0b-3dea-4f47-aaa5-d3b34de7f4a2', '相和歌辭 王昭君', '相和歌辞 王昭君', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["日暮驚沙亂雪飛，傍人相勸易羅衣。","強來前帳看歌舞，共待單于夜獵歸。"]', '["日暮驚沙亂雪飞，傍人相勸易羅衣。","強来前帳看歌舞，共待單于夜獵归。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baee79b5-b12e-4782-a0a6-33f6d2262a69', '相和歌辭 王昭君', '相和歌辞 王昭君', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["自倚嬋娟望主恩，誰知美惡忽相飜。","黃金不買漢宮貌，青冢空埋胡地魂。"]', '["自倚嬋娟望主恩，誰知美惡忽相飜。","黄金不買漢宮貌，青冢空埋胡地魂。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ea39dca-10f3-40f2-b644-29dc9bc71e40', '相和歌辭 王昭君二首 一', '相和歌辞 王昭君二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["滿面胡沙滿鬢風，眉銷殘黛臉銷紅。","愁苦辛勤顦顇盡，如今却似畫圖中。"]', '["满面胡沙满鬢风，眉銷殘黛臉銷紅。","愁苦辛勤顦顇尽，如今却似畫圖中。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd60e7b9-e73b-4145-b28c-10f144257800', '相和歌辭 王昭君二首 二', '相和歌辞 王昭君二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漢使却回憑寄語，黃金何日贖蛾眉？君王若問妾顏色，莫道不如宮裏時。"]', '["漢使却回憑寄語，黄金何日贖蛾眉？君王若问妾顏色，莫道不如宮裏时。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdb8856c-15c6-487f-8932-c2dd589aa833', '相和歌辭 王昭君', '相和歌辞 王昭君', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["錦車天外去，毳幕雲中開。","魏闕蒼龍遠，蕭關赤雁哀。"]', '["錦车天外去，毳幕云中开。","魏闕蒼龙远，蕭关赤雁哀。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd999d6e-1a59-43f9-845c-2805dc2977da', '相和歌辭 王昭君', '相和歌辞 王昭君', 'f841c0a4-cfe1-4d0b-a30c-6261191f82e2', '唐', '["仙娥今下嫁，驕子自同和。","劒戟歸田盡，牛羊繞塞多。"]', '["仙娥今下嫁，驕子自同和。","劒戟归田尽，牛羊繞塞多。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 張仲素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea2769d1-dfb2-4dc3-a86f-65a2f962a166', '相和歌辭 王昭君', '相和歌辞 王昭君', '17ddf6b9-7076-45cf-be31-cf743784bbe9', '唐', '["毛延壽畫欲通神，忍爲黃金不爲人。","馬上琵琶行萬里，漢宮長有隔生春。"]', '["毛延壽畫欲通神，忍爲黄金不爲人。","马上琵琶行万里，漢宮长有隔生春。"]', '诗', 'shi', '', NULL, '相和歌辭 王昭君 李商隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e4dd8bd-be62-478f-bd88-f6db89276125', '相和歌辭 明妃曲', '相和歌辞 明妃曲', 'ed7684c5-7336-496c-b177-980a1337b513', '唐', '["北望單于日半斜，明君馬上泣胡沙。","一雙淚滴黃河水，應得東流入漢家。"]', '["北望單于日半斜，明君马上泣胡沙。","一雙泪滴黄河水，應得东流入漢家。"]', '诗', 'shi', '', NULL, '相和歌辭 明妃曲 王偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f166c3ae-20ba-4c3c-98bc-86748fe65ec0', '相和歌辭 昭君詞', '相和歌辞 昭君词', '49ac4a83-cdcf-498b-9963-7c60457963b0', '唐', '["戒途飛萬里，回首望三秦。","忽見天山雪，還疑上苑春。","玉痕垂淚粉，羅袂拂胡塵。","爲得胡中曲，還悲遠嫁人。"]', '["戒途飞万里，回首望三秦。","忽见天山雪，還疑上苑春。","玉痕垂泪粉，羅袂拂胡塵。","爲得胡中曲，還悲远嫁人。"]', '诗', 'shi', '', NULL, '相和歌辭 昭君詞 張文琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dcbf1f9-1f83-4336-aa0a-3bfc9669eeff', '相和歌辭 昭君詞', '相和歌辞 昭君词', 'c83ab06d-3957-40b6-84ff-b86b0e97dc75', '唐', '["跨鞍今永訣，垂淚別親賓。","漢地行將遠，胡關逐望新。","交河擁塞路，隴首暗沙塵。","唯有孤明月，猶能遠送人。"]', '["跨鞍今永訣，垂泪別親賓。","漢地行將远，胡关逐望新。","交河擁塞路，隴首暗沙塵。","唯有孤明月，猶能远送人。"]', '诗', 'shi', '', NULL, '相和歌辭 昭君詞 陳昭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c21addf-505a-4646-ba87-7c04278d68ff', '相和歌辭 昭君詞', '相和歌辞 昭君词', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["漢宮若遠近，路在寒沙上。","到死不得歸，何人共南望。"]', '["漢宮若远近，路在寒沙上。","到死不得归，何人共南望。"]', '诗', 'shi', '', NULL, '相和歌辭 昭君詞 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('156ce7cd-387c-48ea-80c3-9263138ee066', '相和歌辭 昭君詞', '相和歌辞 昭君词', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["李陵初送子卿回，漢月明明照帳來。","憶著長安舊遊處，千門萬戶玉樓臺。"]', '["李陵初送子卿回，漢月明明照帳来。","憶著长安旧游处，千门万戶玉楼台。"]', '诗', 'shi', '', NULL, '相和歌辭 昭君詞 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8434304f-056e-45be-8558-b028cdcc4133', '相和歌辭 楚妃歎', '相和歌辞 楚妃歎', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["湘雲初起江沈沈，君王遙在雲夢林。","江南雨多旌旗暗，臺下朝朝春水深。","章華殿前朝萬國，君心獨自終無極。","楚兵滿地能逐禽，誰用一身繼筋力。","西江若飜雲夢中，麋鹿死盡應還宮。"]', '["湘云初起江沈沈，君王遙在云梦林。","江南雨多旌旗暗，台下朝朝春水深。","章华殿前朝万国，君心独自終無極。","楚兵满地能逐禽，誰用一身繼筋力。","西江若飜云梦中，麋鹿死尽應還宮。"]', '诗', 'shi', '', NULL, '相和歌辭 楚妃歎 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b7e4088-5605-41dc-8565-bcce73c7dfad', '相和歌辭 楚妃怨', '相和歌辞 楚妃怨', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["梧桐葉下黃金井，橫架轆轤牽素綆。","美人初起天未明，手拂銀缾秋水冷。"]', '["梧桐葉下黄金井，橫架轆轤牽素綆。","美人初起天未明，手拂銀缾秋水冷。"]', '诗', 'shi', '', NULL, '相和歌辭 楚妃怨 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9579b49c-f49e-4433-8010-4ce223233acc', '相和歌辭 王子喬', '相和歌辞 王子喬', 'b3b4eabb-dd08-430f-bfed-11893b7fdc76', '唐', '["王子喬，愛神仙，七月七日上賓天。","白虎搖瑟鳳吹笙，乘騎雲氣吸日精。","吸日精，長不歸，遺廟今在而人非。","空望山頭草，草露溼君衣。"]', '["王子喬，愛神仙，七月七日上賓天。","白虎搖瑟鳳吹笙，乘騎云氣吸日精。","吸日精，长不归，遺廟今在而人非。","空望山头草，草露溼君衣。"]', '诗', 'shi', '', NULL, '相和歌辭 王子喬 宋之問 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5502113-3846-45a2-8334-e91c0d1e22ee', '相和歌辭 蜀國弦', '相和歌辞 蜀国弦', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["楓香晚華靜，錦水南山影。","驚石墜猨哀，竹雲愁半嶺。","涼月生秋浦，玉沙鱗鱗光。","誰家紅淚客，不忍過瞿塘。"]', '["楓香晚华静，錦水南山影。","驚石墜猨哀，竹云愁半嶺。","涼月生秋浦，玉沙鱗鱗光。","誰家紅泪客，不忍過瞿塘。"]', '诗', 'shi', '', NULL, '相和歌辭 蜀國弦 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24eec460-2dda-41a7-8104-e590096f3e03', '相和歌辭 長歌行', '相和歌辞 长歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["桃李得日開，榮華照當年。","東風動百物，草木盡欲言。","枯枝無醜葉，涸水吐清泉。","大力運天地，羲和無停鞭。","功名不早著，竹帛將何宣？","桃李務青春，誰能貫白日。","富貴與神仙，蹉跎成兩失。","金石猶銷鑠，風霜無久質。","畏落日月後，強歡歌與酒。","秋霜不惜人，倏忽侵蒲柳。"]', '["桃李得日开，榮华照當年。","东风动百物，草木尽欲言。","枯枝無醜葉，涸水吐清泉。","大力運天地，羲和無停鞭。","功名不早著，竹帛將何宣？","桃李務青春，誰能貫白日。","富貴與神仙，蹉跎成兩失。","金石猶銷鑠，风霜無久質。","畏落日月後，強歡歌與酒。","秋霜不惜人，倏忽侵蒲柳。"]', '诗', 'shi', '', NULL, '相和歌辭 長歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ade97a3d-abfa-483d-914b-8969d5046dc2', '相和歌辭 長歌行', '相和歌辞 长歌行', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["曠野饒悲風，颼颼黃蒿草。","繫馬停白楊，誰知我懷抱。","所是同袍者，相逢盡衰老。","況登漢家陵，南望長安道。","下有枯樹根，上有鼷鼠窠。","高皇子孫盡，千古無人過。","寶玉頻發掘，精靈其奈何？","人生須達命，有酒且長歌。"]', '["曠野饒悲风，颼颼黄蒿草。","繫马停白楊，誰知我懷抱。","所是同袍者，相逢尽衰老。","況登漢家陵，南望长安道。","下有枯樹根，上有鼷鼠窠。","高皇子孫尽，千古無人過。","寶玉頻發掘，精靈其奈何？","人生須達命，有酒且长歌。"]', '诗', 'shi', '', NULL, '相和歌辭 長歌行 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48f70126-c9e2-4d4d-8a3f-e1e76539c15d', '相和歌辭 短歌行', '相和歌辞 短歌行', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["八月木蔭薄，十葉三墮枝。","人生過五十，亦已同此時。","朝出東郭門，嘉樹鬱參差。","暮出西郭門，原草已離披。","南鄰好臺榭，北鄰善歌吹。","榮華忽消歇，四顧令人悲。","生死與榮辱，四者乃常期。","古人恥其名，沒世無人知。","無言鬢似霜，勿謂髮如絲。"]', '["八月木蔭薄，十葉三墮枝。","人生過五十，亦已同此时。","朝出东郭门，嘉樹鬱參差。","暮出西郭门，原草已離披。","南鄰好台榭，北鄰善歌吹。","榮华忽消歇，四顧令人悲。","生死與榮辱，四者乃常期。","古人恥其名，沒世無人知。","無言鬢似霜，勿謂髮如絲。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308de8c1-a614-42e8-aff9-11cb4a5c08d2', '相和歌辭 短歌行', '相和歌辞 短歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["白日何短短，百年苦易滿。","蒼穹浩茫茫，萬劫太極長。","麻姑垂兩鬢，一半已成霜。","天公見玉女，大笑億千場。","吾欲攪六龍，回車挂扶桑。","北斗酌美酒，勸龍各一觴。","富貴非所願，爲人駐頹光。"]', '["白日何短短，百年苦易满。","蒼穹浩茫茫，万劫太極长。","麻姑垂兩鬢，一半已成霜。","天公见玉女，大笑億千場。","吾欲攪六龙，回车挂扶桑。","北斗酌美酒，勸龙各一觴。","富貴非所願，爲人駐頹光。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eb5e933-ca5a-40f4-975f-a33c670908d8', '相和歌辭 短歌行六首 一', '相和歌辞 短歌行六首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["城邊路，今人犂田昔人墓。","岸上沙，昔時江水今人家。","今人昔人共長歎，四氣相催節回換。","明月皎皎入華池，白雲離離度清漢。"]', '["城邊路，今人犂田昔人墓。","岸上沙，昔时江水今人家。","今人昔人共长歎，四氣相催節回換。","明月皎皎入华池，白云離離度清漢。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行六首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16dea403-c108-4546-89a5-18e8f1d3373c', '相和歌辭 短歌行六首 二', '相和歌辞 短歌行六首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["我欲升天天隔霄，我思渡水水無橋。","我欲上山山路險，我欲汲井井泉遙。","越人翠被今何夕，獨立沙邊江草碧。"]', '["我欲升天天隔霄，我思渡水水無橋。","我欲上山山路險，我欲汲井井泉遙。","越人翠被今何夕，独立沙邊江草碧。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行六首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39f54c2d-a0a9-4121-b7df-958ce2b4824e', '相和歌辭 短歌行六首 三', '相和歌辞 短歌行六首 三', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["新繫青絲百尺繩，心在君家轆轤上。","我心皎潔君不知，轆轤一轉一惆悵。"]', '["新繫青絲百尺繩，心在君家轆轤上。","我心皎潔君不知，轆轤一轉一惆悵。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行六首 三 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06bb6ddd-5f47-42f0-a020-b7671ad56bdf', '相和歌辭 短歌行六首 四', '相和歌辞 短歌行六首 四', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["何處春風吹曉幕？江南綠水通朱閣。","美人二八面如花，泣向東風畏花落。"]', '["何处春风吹晓幕？江南綠水通朱閣。","美人二八面如花，泣向东风畏花落。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行六首 四 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e62d0639-d93d-48ca-a865-de2531a4667d', '相和歌辭 短歌行六首 五', '相和歌辞 短歌行六首 五', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["臨春風，聽春鳥。","別時多，見時少。","愁人夜永不得眠，瑤井玉繩相向曉。"]', '["臨春风，听春鸟。","別时多，见时少。","愁人夜永不得眠，瑤井玉繩相向晓。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行六首 五 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('733338ce-0d59-4820-ab16-d779ef50018b', '相和歌辭 短歌行六首 六', '相和歌辞 短歌行六首 六', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["軒轅皇帝初得仙，鼎湖一去三千年。","周流三十六洞天，洞中日月星辰連。","騎龍駕景遊八極，軒轅弓劒無人識，東海青童寄消息。"]', '["軒轅皇帝初得仙，鼎湖一去三千年。","周流三十六洞天，洞中日月星辰連。","騎龙駕景游八極，軒轅弓劒無人識，东海青童寄消息。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行六首 六 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7c59c41-b87d-4c9f-8efd-f6189ebe72e8', '相和歌辭 短歌行', '相和歌辞 短歌行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["人初生，日初出。","上山遲，下山疾。","百年三萬六千朝，夜裏分將彊半日。","有歌有舞間早爲，昨日健於今日時。","人家見生男女好，不知男女催人老。","短歌行，無樂聲。"]', '["人初生，日初出。","上山遲，下山疾。","百年三万六千朝，夜裏分將彊半日。","有歌有舞间早爲，昨日健於今日时。","人家见生男女好，不知男女催人老。","短歌行，無乐声。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e475f6f8-5b6a-4387-834f-acd87e595561', '相和歌辭 短歌行', '相和歌辞 短歌行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["青天蕩蕩高且虛，上有白日無根株。","流光暫出還入地，催我少年不須臾。","與君相逢不寂寞，衰老不復如今樂。","玉卮盛酒置君前，再拜願君千萬年。"]', '["青天蕩蕩高且虛，上有白日無根株。","流光暫出還入地，催我少年不須臾。","與君相逢不寂寞，衰老不复如今乐。","玉卮盛酒置君前，再拜願君千万年。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8ec87e7-3074-40dd-8d87-a260dad83ae7', '相和歌辭 短歌行二首 一', '相和歌辞 短歌行二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曈曈太陽如火色，上行千里下一刻。","出爲白晝入爲夜，圜轉如珠住不得。","住不得，可奈何？爲君舉酒歌短歌。","歌聲苦，詞亦苦，四座少年君聽取。","今夕未竟明夕催，秋風纔往春風回。","人無根蔕時不駐，朱顏白日相隳頹。","勸君且強笑一面，勸君復強飲一杯。","人生不得長歡樂，年少須臾老到來。"]', '["曈曈太陽如火色，上行千里下一刻。","出爲白晝入爲夜，圜轉如珠住不得。","住不得，可奈何？爲君舉酒歌短歌。","歌声苦，词亦苦，四座少年君听取。","今夕未竟明夕催，秋风纔往春风回。","人無根蔕时不駐，朱顏白日相隳頹。","勸君且強笑一面，勸君复強饮一杯。","人生不得长歡乐，年少須臾老到来。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6358b620-0c4b-4bd3-ae41-b93271318a05', '相和歌辭 短歌行二首 二', '相和歌辞 短歌行二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世人求富貴，多爲身嗜欲。","盛衰不自由，得失常相逐。","問君少年日，苦學將干祿。","負笈塵中遊，抱書雪前宿。","布衾不周體，藜茄纔充腹。","三十登宦途，五十被朝服。","奴溫已挾纊，馬肥初食粟。","未敢議歡遊，尚爲名檢束。","耳目聾暗後，堂上調絲竹。","牙齒缺落時，盤中堆酒肉。","彼來此已去，外餘中不足。","少壯與榮華，相避如寒燠。","青雲去地遠，白日終天速。","從古無奈何，短歌聽一曲。"]', '["世人求富貴，多爲身嗜欲。","盛衰不自由，得失常相逐。","问君少年日，苦学將干祿。","負笈塵中游，抱书雪前宿。","布衾不周體，藜茄纔充腹。","三十登宦途，五十被朝服。","奴溫已挾纊，马肥初食粟。","未敢議歡游，尚爲名檢束。","耳目聾暗後，堂上調絲竹。","牙齒缺落时，盤中堆酒肉。","彼来此已去，外餘中不足。","少壯與榮华，相避如寒燠。","青云去地远，白日終天速。","從古無奈何，短歌听一曲。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9800b0e-760e-4437-b733-d9eed56aef6b', '相和歌辭 短歌行', '相和歌辞 短歌行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["爪牙在身上，陷穽猶可制。","爪牙在胷中，劒戟無所畏。","人言畏猛虎，誰是撩頭斃。","祗見古來心，姦雄暗相噬。"]', '["爪牙在身上，陷穽猶可制。","爪牙在胷中，劒戟無所畏。","人言畏猛虎，誰是撩头斃。","祗见古来心，姦雄暗相噬。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('344b8022-5073-4b18-a099-ee3e1f12412b', '相和歌辭 短歌行', '相和歌辞 短歌行', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["古人若不死，吾亦何所悲。","蕭蕭煙雨九原上，白楊青松葬者誰。","貴賤同一塵，死生同一指。","人生在世共如此，何異浮雲與流水。","短歌行，短歌無窮日已傾。","鄴宮梁苑徒有名，春草秋風傷我情。","何爲不學金仙侶？一悟空王無死生。"]', '["古人若不死，吾亦何所悲。","蕭蕭煙雨九原上，白楊青松葬者誰。","貴賤同一塵，死生同一指。","人生在世共如此，何異浮云與流水。","短歌行，短歌無窮日已傾。","鄴宮梁苑徒有名，春草秋风傷我情。","何爲不学金仙侶？一悟空王無死生。"]', '诗', 'shi', '', NULL, '相和歌辭 短歌行 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('863d795c-9a4b-4775-95f3-f7747b354a84', '相和歌辭 銅雀臺', '相和歌辞 銅雀台', 'efabfbd9-153d-4b78-9136-a6a5d4f9d9e9', '唐', '["北登銅雀上，西望青松郭。","繐帳空蒼蒼，陵田紛漠漠。","平生事已變，歌吹宛猶昨。","長袖拂玉麈，遺情結羅幕。","妾怨在朝露，君恩豈中薄。","高臺奏曲終，曲終淚橫落。"]', '["北登銅雀上，西望青松郭。","繐帳空蒼蒼，陵田紛漠漠。","平生事已变，歌吹宛猶昨。","长袖拂玉麈，遺情結羅幕。","妾怨在朝露，君恩豈中薄。","高台奏曲終，曲終泪橫落。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀臺 王無競 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b253a52-9aae-494e-8dea-269686ea97b2', '相和歌辭 銅雀臺', '相和歌辞 銅雀台', '86e135d6-5da2-49b1-afbf-81ea45ee411e', '唐', '["日斜漳浦望，風起鄴臺寒。","玉座平生晚，金尊妓吹闌。","舞餘依帳泣，歌罷向陵看。","蕭索松風暮，愁煙入井闌。"]', '["日斜漳浦望，风起鄴台寒。","玉座平生晚，金尊妓吹闌。","舞餘依帳泣，歌罷向陵看。","蕭索松风暮，愁煙入井闌。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀臺 鄭愔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c04a73af-b692-4a86-8817-878f0c2b39d6', '相和歌辭 銅雀臺', '相和歌辞 銅雀台', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["嬌愛更何日？高臺空數層。","含啼映雙袖，不忍看西陵。","漳河東流無復來，百花輦路爲蒼苔。","青樓月夜長寂寞，碧雲日暮空裴回。","君不見鄴中萬事非昔時，古人何在今人悲。","春風不逐君王去，草色年年舊宮路。","宮中歌舞已浮雲，空指行人往來處。"]', '["嬌愛更何日？高台空數層。","含啼映雙袖，不忍看西陵。","漳河东流無复来，百花輦路爲蒼苔。","青楼月夜长寂寞，碧云日暮空裴回。","君不见鄴中万事非昔时，古人何在今人悲。","春风不逐君王去，草色年年旧宮路。","宮中歌舞已浮云，空指行人往来处。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀臺 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('154e934d-23b0-4ea2-83e4-6a824032eace', '相和歌辭 銅雀臺', '相和歌辞 銅雀台', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["日暮銅雀靜，西陵鳥雀歸。","撫弦心斷絕，聽管淚霏霏。","靈几臨朝奠，空牀卷夜衣。","蒼蒼川上月，應照妾魂飛。"]', '["日暮銅雀静，西陵鸟雀归。","撫弦心斷絕，听管泪霏霏。","靈几臨朝奠，空牀卷夜衣。","蒼蒼川上月，應照妾魂飞。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀臺 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93ce9873-3063-43d5-ac58-1f2d65197e63', '相和歌辭 銅雀臺', '相和歌辞 銅雀台', '73a469dc-43f9-492b-9f3e-98e18b7e533e', '唐', '["強歌強舞竟難勝，花落花開淚滿繒。","祗合當年伴君死，免教顦顇望西陵。"]', '["強歌強舞竟难勝，花落花开泪满繒。","祗合當年伴君死，免教顦顇望西陵。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀臺 羅隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04231364-d4bf-46f7-b732-239b593e20a1', '相和歌辭 銅雀臺', '相和歌辞 銅雀台', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["魏帝當時銅雀臺，黃花深映棘叢開。","人生富貴須回首，此地豈無歌舞來。"]', '["魏帝當时銅雀台，黄花深映棘叢开。","人生富貴須回首，此地豈無歌舞来。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀臺 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8e2dbe6-d9a2-4fa0-a548-5d98d6e29ebc', '相和歌辭 銅雀臺', '相和歌辞 銅雀台', '628fd0c1-f90d-498d-8ce4-0f47c78d8321', '唐', '["君王冥寞不可見，銅雀歌舞空裴回。","西陵嘖嘖悲宿鳥，空殿沈沈閉青苔。","青苔無人跡，紅粉空相哀。"]', '["君王冥寞不可见，銅雀歌舞空裴回。","西陵嘖嘖悲宿鸟，空殿沈沈閉青苔。","青苔無人跡，紅粉空相哀。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀臺 張氏琰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57fc2199-fe36-4b4e-8ec5-9a4118206894', '相和歌辭 銅雀臺', '相和歌辞 銅雀台', '24b5378b-4560-4aca-88bb-ef672a1a5b11', '唐', '["歌扇向陵開，齊行奠玉杯。","舞時飛燕列，夢裏片雲來。","月色空餘恨，松聲暮更哀。","誰憐未死妾，掩袂下銅臺。"]', '["歌扇向陵开，齊行奠玉杯。","舞时飞燕列，梦裏片云来。","月色空餘恨，松声暮更哀。","誰怜未死妾，掩袂下銅台。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀臺 梁氏瓊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07350b9f-fa3c-4d1b-8f99-363c11f9873d', '相和歌辭 銅雀妓 一', '相和歌辞 銅雀妓 一', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["妾本深宮妓，曾城閉九重。","君王歡愛盡，歌舞爲誰容。","錦衾不復襞，羅衣誰再縫。","高臺西北望，流涕向青松。"]', '["妾本深宮妓，曾城閉九重。","君王歡愛尽，歌舞爲誰容。","錦衾不复襞，羅衣誰再縫。","高台西北望，流涕向青松。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 一 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c5f92d1-f239-4403-923b-c25bcb20b679', '相和歌辭 銅雀妓 二', '相和歌辞 銅雀妓 二', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["金鳳鄰銅雀，漳河望鄴城。","君王無處所，臺榭若平生。","舞筵紛可就，歌梁儼未傾。","西陵松檟冷，誰見綺羅情。"]', '["金鳳鄰銅雀，漳河望鄴城。","君王無处所，台榭若平生。","舞筵紛可就，歌梁儼未傾。","西陵松檟冷，誰见綺羅情。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 二 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e31f573-be01-432b-882c-d181c575dde7', '相和歌辭 銅雀妓', '相和歌辞 銅雀妓', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["昔年分鼎地，今日望陵臺。","一旦雄圖盡，千秋遺令開。","綺羅君不見，歌舞妾空來。","恩共漳河水，東流無重迴。"]', '["昔年分鼎地，今日望陵台。","一旦雄圖尽，千秋遺令开。","綺羅君不见，歌舞妾空来。","恩共漳河水，东流無重迴。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b5e6525-dd53-496d-9fb7-73e6a57257f4', '相和歌辭 銅雀妓', '相和歌辞 銅雀妓', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["金閣惜分香，鈆華不重妝。","空餘歌舞地，猶是爲君王。","哀弦調已絕，豔曲不須長。","共看西陵暮，秋煙生白楊。"]', '["金閣惜分香，鈆华不重妝。","空餘歌舞地，猶是爲君王。","哀弦調已絕，豔曲不須长。","共看西陵暮，秋煙生白楊。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11df6c7b-ed87-4560-a226-9f2bbf774712', '相和歌辭 銅雀妓', '相和歌辞 銅雀妓', '9769f322-5a6d-4289-9676-aa8c22fc0c0d', '唐', '["日暮銅雀迥，幽聲玉座清。","蕭森松柏望，委鬱綺羅情。","君恩不再重，妾舞爲誰輕。"]', '["日暮銅雀迥，幽声玉座清。","蕭森松柏望，委鬱綺羅情。","君恩不再重，妾舞爲誰轻。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 王適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08c567b5-dbee-4056-a1f4-712d2eca77c3', '相和歌辭 銅雀妓', '相和歌辞 銅雀妓', 'ba61adc8-828e-4852-acc8-51057d540c11', '唐', '["蕭條登古臺，回首黃金屋。","落葉不歸林，高陵永爲谷。","妝容徒自麗，舞態閱誰目。","惆悵繐帷前，歌聲苦於哭。"]', '["蕭條登古台，回首黄金屋。","落葉不归林，高陵永爲谷。","妝容徒自丽，舞態閱誰目。","惆悵繐帷前，歌声苦於哭。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 歐陽詹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7efb56b2-728f-4899-846f-4203c618194e', '相和歌辭 銅雀妓', '相和歌辞 銅雀妓', 'a401176c-92fa-4cbb-bfb6-3b739195901a', '唐', '["君愛本相饒，從來事舞腰。","那堪攀玉座，腸斷望陵朝。","怨著情無主，哀凝曲不調。","況臨松日暮，悲吹坐蕭蕭。"]', '["君愛本相饒，從来事舞腰。","那堪攀玉座，腸斷望陵朝。","怨著情無主，哀凝曲不調。","況臨松日暮，悲吹坐蕭蕭。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 袁暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7e721a1-9169-46c6-bbf3-970fef076539', '相和歌辭 銅雀妓', '相和歌辞 銅雀妓', 'cd73eab1-6f79-4151-b042-0068a43eef23', '唐', '["魏主矜蛾眉，美人美於玉。","高臺無晝夜，歌舞竟未足。","盛色如轉圜，夕陽落深谷。","仍令身歿後，尚足平生慾。","紅粉橫淚痕，調弦空向屋。","舉頭君不在，唯見西陵木。","玉輦豈再來，嬌鬟爲誰綠。","那堪秋風裏，更舞陽春曲。","曲終情不勝，闌干向西哭。","臺邊生野草，來去罥羅縠。","況復陵寢間，雙雙見麋鹿。"]', '["魏主矜蛾眉，美人美於玉。","高台無晝夜，歌舞竟未足。","盛色如轉圜，夕陽落深谷。","仍令身歿後，尚足平生慾。","紅粉橫泪痕，調弦空向屋。","舉头君不在，唯见西陵木。","玉輦豈再来，嬌鬟爲誰綠。","那堪秋风裏，更舞陽春曲。","曲終情不勝，闌干向西哭。","台邊生野草，来去罥羅縠。","況复陵寢间，雙雙见麋鹿。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 劉商 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f6e3b2d-dc26-4be1-bf64-0710c7eaa7cd', '相和歌辭 銅雀妓', '相和歌辞 銅雀妓', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["佳人一壺酒，秋容滿千里。","石馬臥新煙，憂來何所似？","歌聲且潛弄，陵樹風自起。","長裾壓高臺，淚眼看花机。"]', '["佳人一壺酒，秋容满千里。","石马臥新煙，憂来何所似？","歌声且潛弄，陵樹风自起。","长裾壓高台，泪眼看花机。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58f2aafa-f8bd-4f82-8931-61397b827a1c', '相和歌辭 銅雀妓', '相和歌辞 銅雀妓', '472d1c82-2f0d-4050-90fe-0dd951aeefa6', '唐', '["秋色西陵滿綠蕪，繁弦急管彊歡娛。","長舒羅袖不成舞，却向風前承淚珠。"]', '["秋色西陵满綠蕪，繁弦急管彊歡娛。","长舒羅袖不成舞，却向风前承泪珠。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 吳燭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46e5e3dd-ca66-42e2-bb91-6cac9bd4e71c', '相和歌辭 銅雀妓', '相和歌辞 銅雀妓', '60fd2c42-848e-47a7-9cf6-ff0a5b96ea6e', '唐', '["魏王銅雀妓，日暮管弦清。","一見西陵樹，悲心舞不成。"]', '["魏王銅雀妓，日暮管弦清。","一见西陵樹，悲心舞不成。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 朱光弼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0bd84c8-d587-4cf5-88b3-4b2450e3eae9', '相和歌辭 銅雀妓', '相和歌辞 銅雀妓', 'adc7bbd5-b14b-4a6f-95c2-7044766de6dc', '唐', '["恨唱歌聲咽，愁飜舞袖遲。","西陵日欲暮，是妾斷腸時。"]', '["恨唱歌声咽，愁飜舞袖遲。","西陵日欲暮，是妾斷腸时。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 朱放 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0c486a5-19d2-4475-869f-6dd767e348e7', '相和歌辭 銅雀妓', '相和歌辞 銅雀妓', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["彊開尊酒向陵看，憶得君王舊日歡。","不覺餘歌悲自斷，非關豔曲轉聲難。"]', '["彊开尊酒向陵看，憶得君王旧日歡。","不覺餘歌悲自斷，非关豔曲轉声难。"]', '诗', 'shi', '', NULL, '相和歌辭 銅雀妓 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4a2ae5f-6ea2-4e26-a6b2-a28bb38adc74', '相和歌辭 雀臺怨', '相和歌辞 雀台怨', '5233419b-71dc-4365-810c-516ecc58cb7a', '唐', '["魏宮歌舞地，蝶戲鳥還鳴。","玉座人難到，銅臺雨滴平。","西陵樹不見，漳浦草空生。","萬恨盡埋此，徒懸千載名。"]', '["魏宮歌舞地，蝶戲鸟還鳴。","玉座人难到，銅台雨滴平。","西陵樹不见，漳浦草空生。","万恨尽埋此，徒懸千載名。"]', '诗', 'shi', '', NULL, '相和歌辭 雀臺怨 馬戴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ed3d8a1-b456-4deb-a76d-5ebe314e3da4', '相和歌辭 雀臺怨', '相和歌辞 雀台怨', '902dfc1d-2158-4a7b-89cd-e3c82f3bd152', '唐', '["君王去後行人絕，蕭竽不響歌喉咽。","雄劒無威光彩沈，寶琴零落金星滅。","玉階寂寂墜秋露，月照當時歌舞處。","當時歌舞人不迴，化爲今日西陵灰。"]', '["君王去後行人絕，蕭竽不响歌喉咽。","雄劒無威光彩沈，寶琴零落金星滅。","玉階寂寂墜秋露，月照當时歌舞处。","當时歌舞人不迴，化爲今日西陵灰。"]', '诗', 'shi', '', NULL, '相和歌辭 雀臺怨 程氏長文 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a131e1c4-ee2b-484e-9a8e-90b39b5bb28d', '相和歌辭 置酒行', '相和歌辞 置酒行', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["置酒命所歡，憑觴遂爲戚。","日往不再來，茲辰坐成昔。","百齡非長久，五十將半百。","胡爲勞我形，已鬚還復白。","西山鸞鶴顧，矯矯煙霧翮。","明霞發金丹，陰洞潛水碧。","安得凌風羽，崦嵫駐靈魄。","兀然坐衰老，慙歎東陵柏。"]', '["置酒命所歡，憑觴遂爲戚。","日往不再来，茲辰坐成昔。","百齡非长久，五十將半百。","胡爲勞我形，已鬚還复白。","西山鸾鹤顧，矯矯煙霧翮。","明霞發金丹，陰洞潛水碧。","安得凌风羽，崦嵫駐靈魄。","兀然坐衰老，慙歎东陵柏。"]', '诗', 'shi', '', NULL, '相和歌辭 置酒行 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49b09ac0-497e-4ce2-8a06-0df3c449c8d5', '相和歌辭 置酒行', '相和歌辞 置酒行', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["落塵花片排香痕，闌珊醉露棲愁魂。","洞庭波色惜不得，東風領入黃金尊。","千筠擲毫春譜大，碧舞紅啼相唱和。","安知寂寞西海頭，青𥳇未垂孤鳳餓。"]', '["落塵花片排香痕，闌珊醉露棲愁魂。","洞庭波色惜不得，东风領入黄金尊。","千筠擲毫春譜大，碧舞紅啼相唱和。","安知寂寞西海头，青𥳇未垂孤鳳餓。"]', '诗', 'shi', '', NULL, '相和歌辭 置酒行 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caa5cc79-ac6f-4c2f-8579-0fd050c93ee8', '相和歌辭 長歌續短歌', '相和歌辞 长歌續短歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["長歌破衣襟，短歌斷白髮。","秦王不可見，旦夕成內熱。","渴飲壺中酒，飢拔隴頭粟。","淒淒四月蘭，千里一時綠。","夜峰何離離，月明落石底。","裴回沿石尋，照出高峰外。","不得與之遊，歌成鬢先改。"]', '["长歌破衣襟，短歌斷白髮。","秦王不可见，旦夕成內熱。","渴饮壺中酒，飢拔隴头粟。","淒淒四月蘭，千里一时綠。","夜峰何離離，月明落石底。","裴回沿石尋，照出高峰外。","不得與之游，歌成鬢先改。"]', '诗', 'shi', '', NULL, '相和歌辭 長歌續短歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a1591ac-b91b-4120-8b25-da3d40eb75a0', '相和歌辭 猛虎行', '相和歌辞 猛虎行', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["寒亦不憂雪，飢亦不食人。","人血豈不甘，所惡傷明神。","太室爲我宅，孟門爲我鄰。","百獸爲我膳，五龍爲我賓。","蒙馬一何威，浮江亦以仁。","綵章耀朝日，牙爪雄武臣。","高雲逐氣浮，厚地隨聲振。","君能賈餘勇，日夕長相親。"]', '["寒亦不憂雪，飢亦不食人。","人血豈不甘，所惡傷明神。","太室爲我宅，孟门爲我鄰。","百獸爲我膳，五龙爲我賓。","蒙马一何威，浮江亦以仁。","綵章耀朝日，牙爪雄武臣。","高云逐氣浮，厚地隨声振。","君能賈餘勇，日夕长相親。"]', '诗', 'shi', '', NULL, '相和歌辭 猛虎行 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6e5e21e-44a8-4e30-b824-ef6344e9d531', '相和歌辭 猛虎行', '相和歌辞 猛虎行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝作猛虎行，暮作猛虎吟。","腸斷非關隴頭水，淚下不爲雍門琴。","旌旗繽紛兩河道，戰鼓驚山欲傾倒。","秦人半作燕地囚，胡馬飜銜洛陽草。","一輸一失關下兵，朝降夕叛幽薊城。","巨鼇未斬海水動，魚龍奔走安得寧。","頗似楚漢時，飜覆無定止。","朝過博浪沙，暮入淮陰市。","張良未遇韓信貧，劉項存亡在兩臣。","暫到下邳受兵略，來投漂母作主人。","賢哲栖栖古如此，今時亦棄青雲士。","有策不敢犯龍鱗，竄身南國避胡塵。","寶書長劒挂高閣，金鞍駿馬散故人。","昨日方爲宣城客，掣鈴交通二千石。","有時六博快壯心，繞牀三帀呼一擲。","楚人每道張旭奇，心藏風雲世莫知。","三吳邦伯多顧盼，四海雄俠皆相推。","蕭曹曾作沛中吏，攀龍附鳳當有時。","溧陽酒樓三月春，楊花漠漠愁殺人。","胡人綠眼吹玉笛，吳歌白紵飛梁塵。","丈夫相見且爲樂，槌牛撾鼓會衆賓。","我從此去釣東海，得魚笑寄情相親。"]', '["朝作猛虎行，暮作猛虎吟。","腸斷非关隴头水，泪下不爲雍门琴。","旌旗繽紛兩河道，戰鼓驚山欲傾倒。","秦人半作燕地囚，胡马飜銜洛陽草。","一輸一失关下兵，朝降夕叛幽薊城。","巨鼇未斬海水动，鱼龙奔走安得寧。","頗似楚漢时，飜覆無定止。","朝過博浪沙，暮入淮陰市。","張良未遇韓信貧，劉項存亡在兩臣。","暫到下邳受兵略，来投漂母作主人。","賢哲栖栖古如此，今时亦棄青云士。","有策不敢犯龙鱗，竄身南国避胡塵。","寶书长劒挂高閣，金鞍駿马散故人。","昨日方爲宣城客，掣鈴交通二千石。","有时六博快壯心，繞牀三帀呼一擲。","楚人每道張旭奇，心藏风云世莫知。","三吳邦伯多顧盼，四海雄俠皆相推。","蕭曹曾作沛中吏，攀龙附鳳當有时。","溧陽酒楼三月春，楊花漠漠愁殺人。","胡人綠眼吹玉笛，吳歌白紵飞梁塵。","丈夫相见且爲乐，槌牛撾鼓會衆賓。","我從此去釣东海，得鱼笑寄情相親。"]', '诗', 'shi', '', NULL, '相和歌辭 猛虎行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be3b0c39-a142-4603-9e85-ef1d56587c5f', '相和歌辭 猛虎行', '相和歌辞 猛虎行', '78608b44-8c43-4962-8384-84bcb890396f', '唐', '["猛虎雖云惡，亦各有匹儕。","羣行深谷間，百獸望風低。","身食黃熊父，子食赤豹麛。","擇肉於熊羆，肎視兔與貍。","正晝當谷眠，眼有百步威。","自矜無當對，氣性縱以乖。","朝怒殺其子，暮還飧其妃。","匹儕四散走，猛虎還孤棲。","狐鳴門四旁，烏鵲從噪之。","出逐猴入居，虎不知所歸。","誰云猛虎惡，中路正悲啼。","豹來銜其尾，熊來攫其頤。","猛虎死不辭，但慙前所爲。","虎坐無助死，況如汝細微。","故當結以信，親當結以私。","親故且不保，人誰信汝爲。"]', '["猛虎雖云惡，亦各有匹儕。","羣行深谷间，百獸望风低。","身食黄熊父，子食赤豹麛。","擇肉於熊羆，肎視兔與貍。","正晝當谷眠，眼有百步威。","自矜無當对，氣性縱以乖。","朝怒殺其子，暮還飧其妃。","匹儕四散走，猛虎還孤棲。","狐鳴门四旁，烏鵲從噪之。","出逐猴入居，虎不知所归。","誰云猛虎惡，中路正悲啼。","豹来銜其尾，熊来攫其頤。","猛虎死不辞，但慙前所爲。","虎坐無助死，況如汝細微。","故當結以信，親當結以私。","親故且不保，人誰信汝爲。"]', '诗', 'shi', '', NULL, '相和歌辭 猛虎行 韩愈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64fb5abd-0cad-47a0-8b99-d94291fbc63f', '相和歌辭 猛虎行', '相和歌辞 猛虎行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["南山北山樹冥冥，猛虎白日繞林行。","向晚一身當道食，山中麋鹿盡無聲。","年年養子在深谷，雌雄上山不相逐。","谷中近窟有山村，長向村家取黃犢。","五陵年少不敢射，空來林下看行跡。"]', '["南山北山樹冥冥，猛虎白日繞林行。","向晚一身當道食，山中麋鹿尽無声。","年年養子在深谷，雌雄上山不相逐。","谷中近窟有山村，长向村家取黄犢。","五陵年少不敢射，空来林下看行跡。"]', '诗', 'shi', '', NULL, '相和歌辭 猛虎行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03ab8d68-3b2a-4180-8592-cd523ee54570', '相和歌辭 猛虎行', '相和歌辞 猛虎行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["長戈莫舂，彊弩莫烹。","乳孫哺子，教得生獰。","舉頭爲城，掉尾爲旌。","東海黃公，愁見夜行。","道逢騶虞，牛哀不平。","生何用尺刀，壁上雷鳴。","泰山之下，婦人哭聲。","官家有程，吏不敢聽。"]', '["长戈莫舂，彊弩莫烹。","乳孫哺子，教得生獰。","舉头爲城，掉尾爲旌。","东海黄公，愁见夜行。","道逢騶虞，牛哀不平。","生何用尺刀，壁上雷鳴。","泰山之下，婦人哭声。","官家有程，吏不敢听。"]', '诗', 'shi', '', NULL, '相和歌辭 猛虎行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01b862ce-196c-4e2b-beea-1a9cf63e0f84', '相和歌辭 猛虎行', '相和歌辞 猛虎行', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["磨爾牙，錯爾爪，狐莫威，兔莫狡，飲來吞噬取腸飽。","橫行不怕日月明，皇天產爾爲生獰。"]', '["磨爾牙，錯爾爪，狐莫威，兔莫狡，饮来吞噬取腸飽。","橫行不怕日月明，皇天產爾爲生獰。"]', '诗', 'shi', '', NULL, '相和歌辭 猛虎行 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('355093ed-7265-43e2-b1c6-32da0aaef1ee', '相和歌辭 君子行', '相和歌辞 君子行', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["聖人不生，麟龍何瑞？","梧桐不高，鳳皇何止？","吾聞古之有君子，行藏以時，進退求己。","榮必爲天下榮，恥必爲天下恥。"]', '["聖人不生，麟龙何瑞？","梧桐不高，鳳皇何止？","吾闻古之有君子，行藏以时，進退求己。","榮必爲天下榮，恥必爲天下恥。"]', '诗', 'shi', '', NULL, '相和歌辭 君子行 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09788f19-1e11-4394-a543-0edf2cfdcae9', '相和歌辭 燕歌行', '相和歌辞 燕歌行', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["漢家煙塵在東北，漢將辭家破殘賊。","男兒本自重橫行，天子非常賜顏色。","摐金伐鼓下榆關，旌旗逶迤碣石間。","校尉羽書飛瀚海，單于獵火照狼山。","山川蕭條極邊土，胡騎憑凌雜風雨。","戰士軍前半死生，美人帳下猶歌舞。","大漠窮秋塞草衰，孤城落日鬬兵稀。","身當恩遇常輕敵，力盡關山未解圍。","鐵衣遠戍辛勤久，玉箸應啼別離後。","少婦城南欲斷腸，征人薊北空回首。","邊風飄飄那可度，絕域蒼茫更何有。","殺氣三日作陣雲，寒聲一夜傳刁斗。","相看白刃血紛紛，死節從來豈顧勳。","君不見沙場征戰苦，至今猶憶李將軍。"]', '["漢家煙塵在东北，漢將辞家破殘賊。","男兒本自重橫行，天子非常賜顏色。","摐金伐鼓下榆关，旌旗逶迤碣石间。","校尉羽书飞瀚海，單于獵火照狼山。","山川蕭條極邊土，胡騎憑凌杂风雨。","戰士軍前半死生，美人帳下猶歌舞。","大漠窮秋塞草衰，孤城落日鬬兵稀。","身當恩遇常轻敵，力尽关山未解圍。","鐵衣远戍辛勤久，玉箸應啼別離後。","少婦城南欲斷腸，征人薊北空回首。","邊风飄飄那可度，絕域蒼茫更何有。","殺氣三日作陣云，寒声一夜傳刁斗。","相看白刃血紛紛，死節從来豈顧勳。","君不见沙場征戰苦，至今猶憶李將軍。"]', '诗', 'shi', '', NULL, '相和歌辭 燕歌行 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56c66dee-7bd0-403b-81a4-6b5d552e776d', '相和歌辭 燕歌行', '相和歌辞 燕歌行', 'c661347d-c063-4eea-b3a6-8506c7b7489d', '唐', '["國之重鎮惟幽都，東威九夷制北胡。","五軍精卒三十萬，百戰百勝擒單于。","前臨滹沲後沮水，崇山沃野亙千里。","昔時燕王重賢士，黃金築臺從隗始。","倏忽興王定薊丘，漢家又以封王侯。","蕭條魏晉爲橫流，鮮卑竊據朝五州。","我唐區夏餘十紀，軍容武備赫萬祀。","彤弓黃鉞授元帥，墾耕大漠爲內地。","季秋膠折邊草腓，治兵羽獵因出師。","千營萬隊連旌旗，望之如火忽雷馳。","匈奴懾竄窮髮北，大荒萬里無塵飛。","隋家昔爲天下宰，窮兵黷武征遼海。","南風不競多死聲，鼓臥旗折黃雲橫。","六軍將士皆死盡，戰馬空鞍歸故營。","時遷道革天下平，白環入貢滄海清。","自有農夫已高枕，無勞校尉重橫行。"]', '["国之重鎮惟幽都，东威九夷制北胡。","五軍精卒三十万，百戰百勝擒單于。","前臨滹沲後沮水，崇山沃野亙千里。","昔时燕王重賢士，黄金築台從隗始。","倏忽兴王定薊丘，漢家又以封王侯。","蕭條魏晉爲橫流，鲜卑竊據朝五州。","我唐區夏餘十紀，軍容武備赫万祀。","彤弓黄鉞授元帥，墾耕大漠爲內地。","季秋膠折邊草腓，治兵羽獵因出師。","千營万隊連旌旗，望之如火忽雷驰。","匈奴懾竄窮髮北，大荒万里無塵飞。","隋家昔爲天下宰，窮兵黷武征遼海。","南风不競多死声，鼓臥旗折黄云橫。","六軍將士皆死尽，戰马空鞍归故營。","时遷道革天下平，白环入貢滄海清。","自有農夫已高枕，無勞校尉重橫行。"]', '诗', 'shi', '', NULL, '相和歌辭 燕歌行 賈至 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c680a907-39d1-4968-b638-3bdb6c97eb9b', '相和歌辭 燕歌行', '相和歌辞 燕歌行', '933e8c83-c3fc-47cb-a48d-1811e605e0cc', '唐', '["請君留楚調，聽我吟燕歌。","家在遼水頭，邊風意氣多。","出身爲漢將，正值戎未和。","雪中凌天山，冰上渡交河。","大小百餘戰，封侯竟蹉跎。","歸來霸陵下，故舊無相過。","雄劒委塵匣，空門唯雀羅。","玉篸還趙女，寶瑟付齊娥。"]', '["請君留楚調，听我吟燕歌。","家在遼水头，邊风意氣多。","出身爲漢將，正值戎未和。","雪中凌天山，冰上渡交河。","大小百餘戰，封侯竟蹉跎。","归来霸陵下，故旧無相過。","雄劒委塵匣，空门唯雀羅。","玉篸還趙女，寶瑟付齊娥。"]', '诗', 'shi', '', NULL, '相和歌辭 燕歌行 陶翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38438036-586a-47f6-a4c0-d75bc30801c0', '相和歌辭 從軍行二首 一', '相和歌辞 從軍行二首 一', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["塗山烽候驚，弭節度龍城。","冀馬樓蘭將，燕犀上谷兵。","劒寒花不落，弓曉月逾明。","凜凜嚴霜節，冰壯黃河絕。","蔽日卷征蓬，浮天散飛雪。","全兵值月滿，精騎乘膠折。","結髮早驅馳，辛苦事旌麾。","馬凍重關冷，輪摧九折危。","獨有西山將，年年屬數奇。"]', '["塗山烽候驚，弭節度龙城。","冀马楼蘭將，燕犀上谷兵。","劒寒花不落，弓晓月逾明。","凜凜嚴霜節，冰壯黄河絕。","蔽日卷征蓬，浮天散飞雪。","全兵值月满，精騎乘膠折。","結髮早驱驰，辛苦事旌麾。","马凍重关冷，輪摧九折危。","独有西山將，年年屬數奇。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行二首 一 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bbafaa2-8360-49eb-85d1-3c2fc9259e1a', '相和歌辭 從軍行二首 二', '相和歌辞 從軍行二首 二', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["爟火發金微，連營出武威。","孤城寒雲起，絕陣虜塵飛。","俠客吸龍劒，惡少縵胡衣。","朝摩骨都壘，夜解谷蠡圍。","蕭關遠無極，蒲海廣難依。","沙磴離旌斷，晴川候馬歸。","交河梁已畢，燕山斾欲飛。","方知萬里相，侯服有光輝。"]', '["爟火發金微，連營出武威。","孤城寒云起，絕陣虜塵飞。","俠客吸龙劒，惡少縵胡衣。","朝摩骨都壘，夜解谷蠡圍。","蕭关远無極，蒲海廣难依。","沙磴離旌斷，晴川候马归。","交河梁已畢，燕山斾欲飞。","方知万里相，侯服有光輝。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行二首 二 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f9937c7-3bfe-44bd-b5f3-414f5679c8c6', '相和歌辭 從軍行', '相和歌辞 從軍行', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["平生一顧念，意氣溢三軍。","野日分戈影，天星合劒文。","弓弦抱漢月，馬足踐胡塵。","不求生入塞，唯當死報君。"]', '["平生一顧念，意氣溢三軍。","野日分戈影，天星合劒文。","弓弦抱漢月，马足踐胡塵。","不求生入塞，唯當死報君。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9bb3556-f0d9-4989-afdd-0163fb826a01', '相和歌辭 從軍行', '相和歌辞 從軍行', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["秋來風瑟瑟，羣馬胡行疾。","嚴城晝不開，伏兵暗相失。","天子廟堂拜，將軍玉門出。","紛紛伊洛間，戎馬數千匹。","軍門壓黃河，兵氣衝白日。","平生懷伏劒，忼慨既投筆。","南登漢月孤，北走燕雲密。","近取韓彭計，早知孫吳術。","丈夫清萬里，誰能埽一室。"]', '["秋来风瑟瑟，羣马胡行疾。","嚴城晝不开，伏兵暗相失。","天子廟堂拜，將軍玉门出。","紛紛伊洛间，戎马數千匹。","軍门壓黄河，兵氣衝白日。","平生懷伏劒，忼慨既投笔。","南登漢月孤，北走燕云密。","近取韓彭計，早知孫吳術。","丈夫清万里，誰能埽一室。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97aa4fd9-61d5-4a58-918b-e1f756547676', '相和歌辭 從軍行', '相和歌辞 從軍行', '5fbbb254-1f00-4d96-a79a-1a7d570b22ca', '唐', '["南庭結白露，北風埽黃葉。","此時鴻燕來，驚鳴催思妾。","曲房理鍼線，平碪擣文練。","鴛綺裁易成，龍鄉信難見。","窈窕九重閨，寂寞十年啼。","紗窗白雲宿，羅幌月光棲。","雲月曉微微，愁思流黃機。","玉霜凍珠履，金吹薄羅衣。","漢家已得地，君去將何事？","宛轉結蠶書，寂寞無雁使。","生平荷恩信，本爲容華進。","況復落紅顏，蟬聲催綠鬢。"]', '["南庭結白露，北风埽黄葉。","此时鴻燕来，驚鳴催思妾。","曲房理鍼線，平碪擣文練。","鴛綺裁易成，龙乡信难见。","窈窕九重閨，寂寞十年啼。","紗窗白云宿，羅幌月光棲。","云月晓微微，愁思流黄機。","玉霜凍珠履，金吹薄羅衣。","漢家已得地，君去將何事？","宛轉結蠶书，寂寞無雁使。","生平荷恩信，本爲容华進。","況复落紅顏，蟬声催綠鬢。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 喬知之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ed53ef4-30ca-41ac-a629-d778e5cc2bfa', '相和歌辭 從軍行', '相和歌辞 從軍行', 'e7091833-f8c1-44a0-ae16-cf52c39c60f1', '唐', '["白日登山望烽火，昏黃飲馬傍交河。","行人刁斗風砂暗，公主琵琶幽怨多。","野營萬里無城郭，雨雪紛紛連大漠。","胡雁哀鳴夜夜飛，胡兒眼淚雙雙落。","聞道玉門猶被遮，應將性命逐輕車。","年年戰骨埋荒外，空見蒲萄入漢家。"]', '["白日登山望烽火，昏黄饮马傍交河。","行人刁斗风砂暗，公主琵琶幽怨多。","野營万里無城郭，雨雪紛紛連大漠。","胡雁哀鳴夜夜飞，胡兒眼泪雙雙落。","闻道玉门猶被遮，應將性命逐轻车。","年年戰骨埋荒外，空见蒲萄入漢家。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 李頎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b830967d-95c5-499a-b17f-0a4c38f4b23f', '相和歌辭 從軍行三首 一', '相和歌辞 從軍行三首 一', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["看圖閑教陣，畫地靜論邊。","烏壘天西戍，鷹姿塞上川。","路長須算日，書遠每題年。","無復生還望，飜思未別前。"]', '["看圖闲教陣，畫地静論邊。","烏壘天西戍，鷹姿塞上川。","路长須算日，书远每題年。","無复生還望，飜思未別前。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行三首 一 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cd901c3-39ed-4565-9fa5-9be388f13f6d', '相和歌辭 從軍行三首 二', '相和歌辞 從軍行三首 二', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["柵高三面鬬，箭盡舉烽頻。","營柳和煙暮，關榆帶雪春。","邊城多老將，磧路少歸人。","點盡三河卒，年年添塞塵。"]', '["柵高三面鬬，箭尽舉烽頻。","營柳和煙暮，关榆带雪春。","邊城多老將，磧路少归人。","点尽三河卒，年年添塞塵。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行三首 二 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c79a705-fd5b-48b1-bc25-3d8658cd634c', '相和歌辭 從軍行三首 三', '相和歌辞 從軍行三首 三', '5482c330-a2bc-43e7-829b-2bdd17a56fdb', '唐', '["候火起雕城，塵砂擁戰聲。","遊軍藏漢幟，降騎說蕃情。","霜降滮池淺，秋深太白明。","嫖姚方虎視，不覺請添兵。"]', '["候火起雕城，塵砂擁戰声。","游軍藏漢幟，降騎说蕃情。","霜降滮池淺，秋深太白明。","嫖姚方虎視，不覺請添兵。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行三首 三 李約 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b41afb4-d737-43e1-9f79-1a8101eaa87e', '相和歌辭 從軍行', '相和歌辞 從軍行', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["昔從李都尉，雙鞬照馬蹄。","擒生黑山北，殺敵黃雲西。","太白沈虜地，邊草復萋萋。","歸來邯鄲市，百尺青樓梯。","感激然諾重，平生膽力齊。","芳筵暮歌發，豔粉輕鬟低。","半醉秋風起，鐵騎門前嘶。","遠戍報烽火，孤城嚴鼓鼙。","揮鞭望塵去，少婦莫含啼。"]', '["昔從李都尉，雙鞬照马蹄。","擒生黑山北，殺敵黄云西。","太白沈虜地，邊草复萋萋。","归来邯鄲市，百尺青楼梯。","感激然諾重，平生膽力齊。","芳筵暮歌發，豔粉轻鬟低。","半醉秋风起，鐵騎门前嘶。","远戍報烽火，孤城嚴鼓鼙。","揮鞭望塵去，少婦莫含啼。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dea3f4f6-88ed-4653-9d06-ba5fa73e14d9', '相和歌辭 從軍行', '相和歌辞 從軍行', '1bb99cff-8449-44c8-8297-1e5eb119b959', '唐', '["邊草早不春，劒花增濘塵。","廣場收驥尾，清瀚怯龍鱗。","帆色已歸越，松聲厭避秦。","幾時逢范蠡，處處是通津。"]', '["邊草早不春，劒花增濘塵。","廣場收驥尾，清瀚怯龙鱗。","帆色已归越，松声厭避秦。","幾时逢范蠡，处处是通津。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 厲玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ecea79a-d35e-443e-b67b-9af2a3da6933', '相和歌辭 從軍行二首 一', '相和歌辞 從軍行二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["從軍玉門道，逐虜金微山。","笛奏梅花曲，刀開明月環。","鼓聲鳴海上，兵氣擁雲間。","願斬單于首，長驅靜鐵關。"]', '["從軍玉门道，逐虜金微山。","笛奏梅花曲，刀开明月环。","鼓声鳴海上，兵氣擁云间。","願斬單于首，长驱静鐵关。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c480c5e2-1052-4bdc-9fca-44d38c5a2fda', '相和歌辭 從軍行二首 二', '相和歌辞 從軍行二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["百戰沙場碎鐵衣，城南已合數重圍。","突營射殺呼延將，獨領殘兵千騎歸。"]', '["百戰沙場碎鐵衣，城南已合數重圍。","突營射殺呼延將，独領殘兵千騎归。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b137850-33f6-4386-a282-c7ca62f00af6', '相和歌辭 從軍行', '相和歌辞 從軍行', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["吹角動行人，喧喧行人起。","笳鳴馬嘶亂，爭渡金河水。","日暮沙漠垂，戰聲煙塵裏。","盡繫名王頸，歸來報天子。"]', '["吹角动行人，喧喧行人起。","笳鳴马嘶亂，爭渡金河水。","日暮沙漠垂，戰声煙塵裏。","尽繫名王頸，归来報天子。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6382d668-2787-4a30-b0f2-c58a3b3b9f25', '相和歌辭 從軍行', '相和歌辞 從軍行', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["向夕臨大荒，朔風軫歸慮。","平沙萬里餘，飛鳥宿何處？","虜騎獵長原，翩翩傍河去。","邊聲搖白草，海氣生黃霧。","百戰苦風塵，十年履霜露。","雖投定遠筆，未坐將軍樹。","早知行路難，悔不理章句。"]', '["向夕臨大荒，朔风軫归慮。","平沙万里餘，飞鸟宿何处？","虜騎獵长原，翩翩傍河去。","邊声搖白草，海氣生黄霧。","百戰苦风塵，十年履霜露。","雖投定远笔，未坐將軍樹。","早知行路难，悔不理章句。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10936c86-53b1-4d8b-ac56-861934572d14', '相和歌辭 從軍行 二', '相和歌辞 從軍行 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["烽火城西百尺樓，黃昏獨上海風秋。","更吹橫笛關山月，誰解金閨萬里愁。"]', '["烽火城西百尺楼，黄昏独上海风秋。","更吹橫笛关山月，誰解金閨万里愁。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5a35d99-b904-4c04-a5a7-e57bc6b50f2c', '相和歌辭 從軍行 三', '相和歌辞 從軍行 三', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["琵琶起舞換新聲，總是關山舊別情。","撩亂邊愁彈不盡，高高秋月下長城。"]', '["琵琶起舞換新声，總是关山旧別情。","撩亂邊愁彈不尽，高高秋月下长城。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 三 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0edc1f37-50aa-48ac-9fb3-1def51c4319c', '相和歌辭 從軍行 四', '相和歌辞 從軍行 四', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["青海長雲暗雪山，孤城遙望雁門關。","黃沙百戰穿金甲，不破樓蘭終不還。"]', '["青海长云暗雪山，孤城遙望雁门关。","黄沙百戰穿金甲，不破楼蘭終不還。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 四 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dd705fa-a22f-4505-95f0-280927205b9a', '相和歌辭 從軍行', '相和歌辞 從軍行', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["二十在邊城，軍中得勇名。","卷旗收敗馬，斷磧擁殘兵。","覆陣烏鳶起，燒山草木明。","塞閑思遠獵，師老厭分營。","雪嶺無人跡，冰河足雁聲。","李陵甘此沒，惆悵漢公卿。"]', '["二十在邊城，軍中得勇名。","卷旗收敗马，斷磧擁殘兵。","覆陣烏鳶起，燒山草木明。","塞闲思远獵，師老厭分營。","雪嶺無人跡，冰河足雁声。","李陵甘此沒，惆悵漢公卿。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9bc6f8db-332d-417d-9ec9-75b882f77478', '相和歌辭 從軍行六首 一', '相和歌辞 從軍行六首 一', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["迴看虜騎合，城下漢兵稀。","白刃兩相向，黃雲愁不飛。","手中無尺鐵，徒欲突重圍。"]', '["迴看虜騎合，城下漢兵稀。","白刃兩相向，黄云愁不飞。","手中無尺鐵，徒欲突重圍。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行六首 一 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6013b1e-b78f-494b-8dac-26e2edd6dcda', '相和歌辭 從軍行六首 二', '相和歌辞 從軍行六首 二', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["落日更蕭條，北方動枯草。","將軍追虜騎，夜失陰山道。","戰敗仍樹勳，韓彭但空老。"]', '["落日更蕭條，北方动枯草。","將軍追虜騎，夜失陰山道。","戰敗仍樹勳，韓彭但空老。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行六首 二 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4dd63d6-00ff-4a02-92d5-c9b6e4f240af', '相和歌辭 從軍行六首 三', '相和歌辞 從軍行六首 三', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["草枯秋塞上，望見漁陽郭。","胡馬嘶一聲，漢兵淚雙落。","誰爲吮癰者，此事令人薄。"]', '["草枯秋塞上，望见漁陽郭。","胡马嘶一声，漢兵泪雙落。","誰爲吮癰者，此事令人薄。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行六首 三 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19bd94a6-543b-45a8-8ebb-d9c6d02aa122', '相和歌辭 從軍行六首 四', '相和歌辞 從軍行六首 四', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["目極雁門道，青青邊草春。","一身事征戰，匹馬同辛勤。","末路成白首，功歸天下人。"]', '["目極雁门道，青青邊草春。","一身事征戰，匹马同辛勤。","末路成白首，功归天下人。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行六首 四 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3148011f-5d66-4700-8f35-82ac811d9b65', '相和歌辭 從軍行六首 五', '相和歌辞 從軍行六首 五', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["倚劒白日暮，望鄉登戍樓。","北風吹羌笛，此夜關山愁。","迴首不無意，滹河空自流。"]', '["倚劒白日暮，望乡登戍楼。","北风吹羌笛，此夜关山愁。","迴首不無意，滹河空自流。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行六首 五 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3acf8eb-5401-4982-b1a9-a836e4abe5fb', '相和歌辭 從軍行六首 六', '相和歌辞 從軍行六首 六', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["黃沙一萬里，白首無人憐。","報國劒已折，歸鄉身幸全。","單于古臺下，邊色寒蒼然。"]', '["黄沙一万里，白首無人怜。","報国劒已折，归乡身幸全。","單于古台下，邊色寒蒼然。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行六首 六 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86a92819-b1bd-4d41-b5e1-05430f2f58d1', '相和歌辭 從軍行', '相和歌辞 從軍行', 'b0b1df55-b885-4329-abbd-f559bf77a4ec', '唐', '["秋草馬蹄輕，角弓持弦急。","去爲龍城候，正值胡兵襲。","軍氣橫大荒，戰酣日將入。","長風金鼓動，白霧鐵衣溼。","四起愁邊聲，南轅時佇立。","斷蓬孤自轉，寒雁飛相及。","萬里雲沙漲，路平冰霰澀。","夜聞漢使歸，獨向刀環泣。"]', '["秋草马蹄轻，角弓持弦急。","去爲龙城候，正值胡兵襲。","軍氣橫大荒，戰酣日將入。","长风金鼓动，白霧鐵衣溼。","四起愁邊声，南轅时佇立。","斷蓬孤自轉，寒雁飞相及。","万里云沙漲，路平冰霰澀。","夜闻漢使归，独向刀环泣。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 杜頠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79407adb-5787-406f-a068-c7755cb7fc82', '相和歌辭 從軍行 一', '相和歌辞 從軍行 一', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["候騎出紛紛，元戎霍冠軍。","漢鞞秋聒地，羌火晝燒雲。","萬里戍城合，三邊羽檄分。","烏孫驅未盡，肯顧遼陽勳。"]', '["候騎出紛紛，元戎霍冠軍。","漢鞞秋聒地，羌火晝燒云。","万里戍城合，三邊羽檄分。","烏孫驱未尽，肯顧遼陽勳。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 一 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd80bc2d-ea1e-45d0-85d1-be102ecc5715', '相和歌辭 從軍行 二', '相和歌辞 從軍行 二', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["漢斾拂丹霄，漢軍新破遼。","紅塵驅鹵簿，白羽擁嫖姚。","戰苦軍猶樂，功高將不驕。","至今丁令塞，朔吹空蕭蕭。"]', '["漢斾拂丹霄，漢軍新破遼。","紅塵驱鹵簿，白羽擁嫖姚。","戰苦軍猶乐，功高將不驕。","至今丁令塞，朔吹空蕭蕭。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 二 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('242e50b4-c693-43ec-a914-4ad30f48ba63', '相和歌辭 從軍行 三', '相和歌辞 從軍行 三', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["百萬逐呼韓，頻年不解鞍。","兵屯絕漠暗，馬飲濁河乾。","破虜功未錄，勞師力已殫。","須防肘腋下，飛禍出無端。"]', '["百万逐呼韓，頻年不解鞍。","兵屯絕漠暗，马饮濁河乾。","破虜功未錄，勞師力已殫。","須防肘腋下，飞禍出無端。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 三 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4323278f-f341-427b-bbb0-4b13d7cdb5f9', '相和歌辭 從軍行 四', '相和歌辞 從軍行 四', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["飛將下天來，奇謀閫外裁。","水心龍劒動，地肺雁山開。","望氣燕師銳，當鋒虜陣摧。","從今射鵰騎，不敢過雲堆。"]', '["飞將下天来，奇謀閫外裁。","水心龙劒动，地肺雁山开。","望氣燕師銳，當鋒虜陣摧。","從今射鵰騎，不敢過云堆。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 四 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d514174-194c-4606-afc1-d17e38e0c47f', '相和歌辭 從軍行 五', '相和歌辞 從軍行 五', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["黃紙君王詔，青泥校尉書。","誓師張虎落，選將擐犀渠。","霧暗津浦失，天寒塞柳疎。","橫行十萬騎，欲埽虜塵餘。"]', '["黄紙君王詔，青泥校尉书。","誓師張虎落，選將擐犀渠。","霧暗津浦失，天寒塞柳疎。","橫行十万騎，欲埽虜塵餘。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 五 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81d3df08-a37a-4b38-911c-8a91e95f4463', '相和歌辭 從軍行', '相和歌辞 從軍行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["漢軍逐單于，日沒處河曲。","浮雲道傍起，行子車下宿。","槍城圍鼓角，氊帳依山谷。","馬上懸壺漿，刀頭分頓肉。","來時高堂上，父母親結束。","回首不見家，風吹破衣服。","金創生肢節，相與拔箭鏃。","聞道西涼州，家家婦人哭。"]', '["漢軍逐單于，日沒处河曲。","浮云道傍起，行子车下宿。","槍城圍鼓角，氊帳依山谷。","马上懸壺漿，刀头分頓肉。","来时高堂上，父母親結束。","回首不见家，风吹破衣服。","金創生肢節，相與拔箭鏃。","闻道西涼州，家家婦人哭。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('895c3a39-3388-42e9-94f7-386fa16edcec', '相和歌辭 從軍行', '相和歌辞 從軍行', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["少年金紫就光輝，直指邊城虎翼飛。","一卷旌收千騎虜，萬全身出百重圍。","黃雲斷塞尋鷹去，白草連天射雁歸。","白首漢廷刀筆吏，丈夫功業本相依。"]', '["少年金紫就光輝，直指邊城虎翼飞。","一卷旌收千騎虜，万全身出百重圍。","黄云斷塞尋鷹去，白草連天射雁归。","白首漢廷刀笔吏，丈夫功業本相依。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62613bbc-4f00-412c-84eb-e2a8bd1a8a9d', '相和歌辭 從軍行五首 一', '相和歌辞 從軍行五首 一', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["荒雞隔水啼，汗馬逐風嘶。","終日隨征斾，何時罷鼓鼙。"]', '["荒雞隔水啼，汗马逐风嘶。","終日隨征斾，何时罷鼓鼙。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行五首 一 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fb4ee37-2d51-4a40-ad76-f14154635378', '相和歌辭 從軍行五首 二', '相和歌辞 從軍行五首 二', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["孤心眠夜雪，滿眼是秋沙。","萬里猶防塞，三年不見家。"]', '["孤心眠夜雪，满眼是秋沙。","万里猶防塞，三年不见家。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行五首 二 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('473a6b6f-4060-4a94-b8df-ee99062fe291', '相和歌辭 從軍行五首 三', '相和歌辞 從軍行五首 三', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["却望冰河闊，前登雪嶺高。","征人幾多在，又擬戰臨洮。"]', '["却望冰河闊，前登雪嶺高。","征人幾多在，又擬戰臨洮。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行五首 三 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2624f908-0651-480b-9132-d3b258a20c7e', '相和歌辭 從軍行五首 四', '相和歌辞 從軍行五首 四', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["胡風千里驚，漢月五更明。","縱有還家夢，猶聞出塞聲。"]', '["胡风千里驚，漢月五更明。","縱有還家梦，猶闻出塞声。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行五首 四 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea5be606-2fc0-44cf-bd0b-a4dc72afdae8', '相和歌辭 從軍行五首 五', '相和歌辞 從軍行五首 五', '81448fb7-ba3f-41ac-9485-7cfb16be9d39', '唐', '["暮雪連青海，陰雲覆白山。","可憐班定遠，出入玉門關。"]', '["暮雪連青海，陰云覆白山。","可怜班定远，出入玉门关。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行五首 五 令狐楚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6e31a8e-4d7f-4e78-a9d5-88aaf1499945', '相和歌辭 從軍行三首 一', '相和歌辞 從軍行三首 一', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["旌甲從軍久，風雲識陣難。","今朝韓信計，日下斬成安。"]', '["旌甲從軍久，风云識陣难。","今朝韓信計，日下斬成安。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行三首 一 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('843c9ce2-7636-4312-8b92-10a943e45ae4', '相和歌辭 從軍行三首 二', '相和歌辞 從軍行三首 二', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["燕頷多奇相，狼頭敢犯邊。","寄言班定遠，正是立功年。"]', '["燕頷多奇相，狼头敢犯邊。","寄言班定远，正是立功年。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行三首 二 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7380cd0a-fc58-4f0a-83a6-2e88fe68a24a', '相和歌辭 從軍行三首 三', '相和歌辞 從軍行三首 三', '76ac0589-e4ad-488e-bdb3-e3aa76967a89', '唐', '["旄頭夜落捷書飛，來奏金門著賜衣。","白馬將軍頻破敵，黃龍戍卒幾時歸。"]', '["旄头夜落捷书飞，来奏金门著賜衣。","白马將軍頻破敵，黄龙戍卒幾时归。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍行三首 三 王涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cac30d1-12da-43d9-8773-ec5a4648c782', '相和歌辭 從軍有苦樂行', '相和歌辞 從軍有苦乐行', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["勞者且勿歌，我欲送君觴。","從軍有苦樂，此曲樂未央。","僕本居隴上，隴水斷人腸。","東過秦宮路，宮路入咸陽。","時逢漢帝出，諫獵至長楊。","詎馳游俠窟，非結少年場。","一旦承嘉惠，輕命重恩光。","秉筆參帷帟，從軍至朔方。","邊地多陰風，草木自淒涼。","斷絕海雲去，出沒胡沙長。","參差引雁翼，隱轔騰軍裝。","劒文夜如水，馬汗凍成霜。","俠氣五都少，矜功六郡良。","山河起目前，睚眦死路傍。","北逐驅獯虜，西臨復舊疆。","昔還賦餘資，今出乃贏糧。","一矢弢夏服，我弓不再張。","寄言丈夫雄，苦樂身自當。"]', '["勞者且勿歌，我欲送君觴。","從軍有苦乐，此曲乐未央。","僕本居隴上，隴水斷人腸。","东過秦宮路，宮路入咸陽。","时逢漢帝出，諫獵至长楊。","詎驰游俠窟，非結少年場。","一旦承嘉惠，轻命重恩光。","秉笔參帷帟，從軍至朔方。","邊地多陰风，草木自淒涼。","斷絕海云去，出沒胡沙长。","參差引雁翼，隐轔腾軍裝。","劒文夜如水，马汗凍成霜。","俠氣五都少，矜功六郡良。","山河起目前，睚眦死路傍。","北逐驱獯虜，西臨复旧疆。","昔還賦餘資，今出乃贏糧。","一矢弢夏服，我弓不再張。","寄言丈夫雄，苦乐身自當。"]', '诗', 'shi', '', NULL, '相和歌辭 從軍有苦樂行 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f1d62a1-a288-4626-9f12-c25f766a9748', '相和歌辭 苦戰遠征人', '相和歌辞 苦戰远征人', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["征人歌古曲，攜手上河梁。","李陵死別處，杳杳玄冥鄉。","憶昔從此路，連年征鬼方。","久行迷漢曆，三洗氊衣裳。","百戰身且在，微功信難忘。","遠承雲臺議，非勢孰敢當。","落日弔李廣，白身過河陽。","閑弓失月影，勞劒無龍光。","去日始束髮，今來髮成霜。","虛名乃閑事，生見父母鄉。","掩抑大風歌，裴回少年場。","誠哉古人言，鳥盡良弓藏。"]', '["征人歌古曲，携手上河梁。","李陵死別处，杳杳玄冥乡。","憶昔從此路，連年征鬼方。","久行迷漢曆，三洗氊衣裳。","百戰身且在，微功信难忘。","远承云台議，非勢孰敢當。","落日弔李廣，白身過河陽。","闲弓失月影，勞劒無龙光。","去日始束髮，今来髮成霜。","虛名乃闲事，生见父母乡。","掩抑大风歌，裴回少年場。","誠哉古人言，鸟尽良弓藏。"]', '诗', 'shi', '', NULL, '相和歌辭 苦戰遠征人 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('60d2e463-c18a-4b48-b68c-517e2b27810c', '相和歌辭 苦哉行五首 一', '相和歌辞 苦哉行五首 一', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["彼鼠侵我廚，縱貍授梁肉。","鼠雖爲君却，貍食自須足。","冀雪大國恥，飜是大國辱。","羶腥逼綺羅，甎瓦雜珠玉。","登樓非騁望，目笑是心哭。","何意天樂中，至今奏胡曲。"]', '["彼鼠侵我廚，縱貍授梁肉。","鼠雖爲君却，貍食自須足。","冀雪大国恥，飜是大国辱。","羶腥逼綺羅，甎瓦杂珠玉。","登楼非騁望，目笑是心哭。","何意天乐中，至今奏胡曲。"]', '诗', 'shi', '', NULL, '相和歌辭 苦哉行五首 一 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e17a17a8-d1a9-4168-bfed-e09cb2e7a6c0', '相和歌辭 苦哉行五首 二', '相和歌辞 苦哉行五首 二', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["官軍收洛陽，家住洛陽里。","夫壻與兄弟，目前見傷死。","吞聲不許哭，還譴衣羅綺。","上馬隨匈奴，數秋黃塵裏。","生爲名家女，死作塞垣鬼。","鄉國無還期，天津哭流水。"]', '["官軍收洛陽，家住洛陽里。","夫壻與兄弟，目前见傷死。","吞声不許哭，還譴衣羅綺。","上马隨匈奴，數秋黄塵裏。","生爲名家女，死作塞垣鬼。","乡国無還期，天津哭流水。"]', '诗', 'shi', '', NULL, '相和歌辭 苦哉行五首 二 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7c2cc3f-1d9b-4b80-8c9a-b6271ba0efcd', '相和歌辭 苦哉行五首 三', '相和歌辞 苦哉行五首 三', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["登樓望天衢，目極淚盈睫。","彊笑無笑容，須妝舊花靨。","昔年買奴僕，奴僕來碎葉。","豈意未死間，自爲匈奴妾。","一生忽至此，萬事痛苦業。","得出塞垣飛，不如彼蜂蝶。"]', '["登楼望天衢，目極泪盈睫。","彊笑無笑容，須妝旧花靨。","昔年買奴僕，奴僕来碎葉。","豈意未死间，自爲匈奴妾。","一生忽至此，万事痛苦業。","得出塞垣飞，不如彼蜂蝶。"]', '诗', 'shi', '', NULL, '相和歌辭 苦哉行五首 三 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e821821e-67cc-4b11-a399-7a0b5ad83b80', '相和歌辭 苦哉行五首 四', '相和歌辞 苦哉行五首 四', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["妾家青河邊，七葉承貂蟬。","身爲最小女，偏得渾家憐。","親戚不相識，幽閨十五年。","有時最遠出，祗到中門前。","前年狂胡來，懼死飜生全。","今秋官軍至，豈意遭戈鋋。","匈奴爲先鋒，長鼻黃髮拳。","彎弓獵生人，百步牛羊羶。","脫身落虎口，不及歸黃泉。","苦哉難重陳，暗哭蒼蒼天。"]', '["妾家青河邊，七葉承貂蟬。","身爲最小女，偏得渾家怜。","親戚不相識，幽閨十五年。","有时最远出，祗到中门前。","前年狂胡来，懼死飜生全。","今秋官軍至，豈意遭戈鋋。","匈奴爲先鋒，长鼻黄髮拳。","彎弓獵生人，百步牛羊羶。","脫身落虎口，不及归黄泉。","苦哉难重陳，暗哭蒼蒼天。"]', '诗', 'shi', '', NULL, '相和歌辭 苦哉行五首 四 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab297624-e30f-41ea-b3ca-f1ef347dd26a', '相和歌辭 苦哉行五首 五', '相和歌辞 苦哉行五首 五', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["可汗奉親詔，今月歸燕山。","忽如亂刀劒，[攪]妾心腸間。","出戶望北荒，迢迢玉門關。","生人爲死別，有去無時還。","漢月割妾心，胡風凋妾顏。","去去斷絕魂，叫天天不聞。"]', '["可汗奉親詔，今月归燕山。","忽如亂刀劒，[攪]妾心腸间。","出戶望北荒，迢迢玉门关。","生人爲死別，有去無时還。","漢月割妾心，胡风凋妾顏。","去去斷絕魂，叫天天不闻。"]', '诗', 'shi', '', NULL, '相和歌辭 苦哉行五首 五 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91b3edc5-ea9c-427c-ba79-38e56cb42142', '相和歌辭 鞠歌行', '相和歌辞 鞠歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉不自言如桃李，魚目笑之卞和恥。","楚國青蠅何太多？連城白璧遭讒毀。","荆山長號泣血人，忠臣死爲刖足鬼。","聽曲知甯戚，[夷]吾因小妻。","秦穆五羊皮，買死百里奚。","洗拂青雲上，當時賤如泥。","朝歌鼓刀叟，虎變蟠溪中。","一舉釣六合，逐荒營丘東。","平生渭水曲，誰識此老翁。","奈何今之人，雙目送征鴻。"]', '["玉不自言如桃李，鱼目笑之卞和恥。","楚国青蠅何太多？連城白璧遭讒毀。","荆山长號泣血人，忠臣死爲刖足鬼。","听曲知甯戚，[夷]吾因小妻。","秦穆五羊皮，買死百里奚。","洗拂青云上，當时賤如泥。","朝歌鼓刀叟，虎变蟠溪中。","一舉釣六合，逐荒營丘东。","平生渭水曲，誰識此老翁。","奈何今之人，雙目送征鴻。"]', '诗', 'shi', '', NULL, '相和歌辭 鞠歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2eff0a0-8283-40e5-95ed-81bf510f2f06', '相和歌辭 前苦寒行二首 一', '相和歌辞 前苦寒行二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["漢時長安雪一丈，牛馬毛寒縮如蝟。","楚江巫峽冰入懷，虎豹哀號又堪記。","秦城老翁荆揚客，慣習炎蒸歲絺綌。","玄冥祝融氣或交，手持白羽未敢釋。"]', '["漢时长安雪一丈，牛马毛寒縮如蝟。","楚江巫峽冰入懷，虎豹哀號又堪記。","秦城老翁荆揚客，慣習炎蒸歲絺綌。","玄冥祝融氣或交，手持白羽未敢釋。"]', '诗', 'shi', '', NULL, '相和歌辭 前苦寒行二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('631a60e3-994f-4e3f-a3e9-6cf6e9325840', '相和歌辭 前苦寒行二首 二', '相和歌辞 前苦寒行二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["去年白帝雪在山，今年白帝雪在地。","凍埋蛟龍南浦縮，寒刮肌膚北風利。","楚人四時皆麻衣，楚天萬里無晶輝。","三足之烏足恐斷，羲和送將安所歸。"]', '["去年白帝雪在山，今年白帝雪在地。","凍埋蛟龙南浦縮，寒刮肌膚北风利。","楚人四时皆麻衣，楚天万里無晶輝。","三足之烏足恐斷，羲和送將安所归。"]', '诗', 'shi', '', NULL, '相和歌辭 前苦寒行二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8cffb647-6edb-4da1-be1b-806e1b3dfe42', '相和歌辭 後苦寒行二首 一', '相和歌辞 後苦寒行二首 一', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["南紀巫廬瘴不絕，太古以來無尺雪。","蠻夷長老怨苦寒，崐崘天關凍應折。"]', '["南紀巫廬瘴不絕，太古以来無尺雪。","蠻夷长老怨苦寒，崐崘天关凍應折。"]', '诗', 'shi', '', NULL, '相和歌辭 後苦寒行二首 一 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90891e87-5130-4437-8fb2-6223e1f04d3f', '相和歌辭 後苦寒行二首 二', '相和歌辞 後苦寒行二首 二', '23379253-f84b-4c79-a76c-ba53836f1a14', '唐', '["晚來江門失大木，猛風中夜吹白屋。","天兵斷斬青海戎，殺氣南行動坤軸，不爾苦寒何太酷？","巴東之峽生凌凘，彼蒼迴軒人得知。"]', '["晚来江门失大木，猛风中夜吹白屋。","天兵斷斬青海戎，殺氣南行动坤軸，不爾苦寒何太酷？","巴东之峽生凌凘，彼蒼迴軒人得知。"]', '诗', 'shi', '', NULL, '相和歌辭 後苦寒行二首 二 杜甫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('051a325b-0ad3-42b1-89dc-8c9d09cf45d5', '相和歌辭 苦寒行', '相和歌辞 苦寒行', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["嚴寒動八荒，莿莿無休時。","陽烏不自暖，雪壓扶桑枝。","歲暮寒益壯，青春安得歸。","朔雁到南海，越禽何處飛？","誰言貧士歎，不爲身無衣。"]', '["嚴寒动八荒，莿莿無休时。","陽烏不自暖，雪壓扶桑枝。","歲暮寒益壯，青春安得归。","朔雁到南海，越禽何处飞？","誰言貧士歎，不爲身無衣。"]', '诗', 'shi', '', NULL, '相和歌辭 苦寒行 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51c2f843-6831-4226-acf5-93a92e4981a1', '相和歌辭  苦寒行', '相和歌辞  苦寒行', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["北風北風，職何嚴毒。","摧壯士心，縮金烏足。","凍雲囂囂礙雪，一片下不得。","聲繞枯桑，根在沙塞。","黃河徹底，頑直到海。","一氣搏束，萬物無態。","唯有吾庭前杉松樹枝，枝枝健在。"]', '["北风北风，職何嚴毒。","摧壯士心，縮金烏足。","凍云囂囂礙雪，一片下不得。","声繞枯桑，根在沙塞。","黄河徹底，頑直到海。","一氣搏束，万物無態。","唯有吾庭前杉松樹枝，枝枝健在。"]', '诗', 'shi', '', NULL, '相和歌辭  苦寒行 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d74898fe-e94d-452c-a8c8-3b878f110d0f', '相和歌辭  苦寒行', '相和歌辞  苦寒行', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["冰峰撐空寒矗矗，雪凝水凍埋海陸。","殺物之性，傷人之慾。","既不能斷絕蒺藜荆棘之根株，又不能展鳳皇麒麟之拳跼。","如此則何如爲和煦，爲膏雨。","自然天下之榮枯，融融於萬戶。"]', '["冰峰撐空寒矗矗，雪凝水凍埋海陸。","殺物之性，傷人之慾。","既不能斷絕蒺藜荆棘之根株，又不能展鳳皇麒麟之拳跼。","如此則何如爲和煦，爲膏雨。","自然天下之榮枯，融融於万戶。"]', '诗', 'shi', '', NULL, '相和歌辭  苦寒行 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ac203a8-6e70-4b78-ad75-9acacae9b04a', '相和歌辭  北上行', '相和歌辞  北上行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["北上何所苦，北上緣太行。","磴道盤且峻，巉巖凌穹蒼。","馬足蹶側石，車輪摧高岡。","沙塵接幽州，烽火連朔方。","殺氣毒劒戟，嚴風裂衣裳。","奔鯨夾黃河，鑿齒屯洛陽。","前行無歸日，返顧思舊鄉。","慘戚冰雪裏，悲號絕中腸。","尺布不掩體，皮膚劇枯桑。","汲水澗谷阻，采薪隴坂長。","猛虎又掉尾，磨牙皓秋霜。","草木不可湌，飢飲零露漿。","歎此北上苦，停驂爲之傷。","何日王道平？開顏覩天光。"]', '["北上何所苦，北上緣太行。","磴道盤且峻，巉巖凌穹蒼。","马足蹶側石，车輪摧高岡。","沙塵接幽州，烽火連朔方。","殺氣毒劒戟，嚴风裂衣裳。","奔鯨夾黄河，鑿齒屯洛陽。","前行無归日，返顧思旧乡。","慘戚冰雪裏，悲號絕中腸。","尺布不掩體，皮膚劇枯桑。","汲水澗谷阻，采薪隴坂长。","猛虎又掉尾，磨牙皓秋霜。","草木不可湌，飢饮零露漿。","歎此北上苦，停驂爲之傷。","何日王道平？开顏覩天光。"]', '诗', 'shi', '', NULL, '相和歌辭  北上行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee380cd0-fea2-4baa-92b7-c82c834265e6', '相和歌辭  豫章行', '相和歌辞  豫章行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["胡風吹代馬，北擁魯陽關。","吳兵照海雪，西討何時還？","半渡上遼津，黃雲慘無顏。","老母與子別，呼天野草間。","白馬繞旌旗，悲鳴相追攀。","白楊秋月苦，早落豫章山。","本爲休明人，斬虜素不閑。","豈惜戰鬬死，爲君埽兇頑。","精感石沒羽，豈忘憚險艱。","樓船若鯨飛，波蕩落星灣。","此曲不可奏，三軍鬢成斑。"]', '["胡风吹代马，北擁魯陽关。","吳兵照海雪，西討何时還？","半渡上遼津，黄云慘無顏。","老母與子別，呼天野草间。","白马繞旌旗，悲鳴相追攀。","白楊秋月苦，早落豫章山。","本爲休明人，斬虜素不闲。","豈惜戰鬬死，爲君埽兇頑。","精感石沒羽，豈忘憚險艱。","楼船若鯨飞，波蕩落星灣。","此曲不可奏，三軍鬢成斑。"]', '诗', 'shi', '', NULL, '相和歌辭  豫章行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d87134d-4841-48b3-bb14-cdefa15cfe99', '相和歌辭  董逃行', '相和歌辞  董逃行', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["董逃董逃董卓逃，揩鏗戈甲聲勞嘈。","剜剜深臍脂燄燄，人皆數歎曰。","爾獨不憶年年取我身上膏，膏銷骨盡煙火死。","長安城中賊毛起，城門四走公卿士。","走勸劉虞作天子，劉虞不敢作天子。","曹瞞纂亂從此始，董逃董逃人莫喜。","勝負飜環相枕倚，縫綴難成裁破易。","何況曲針不能伸巧指，欲學裁縫須準擬。"]', '["董逃董逃董卓逃，揩鏗戈甲声勞嘈。","剜剜深臍脂燄燄，人皆數歎曰。","爾独不憶年年取我身上膏，膏銷骨尽煙火死。","长安城中賊毛起，城门四走公卿士。","走勸劉虞作天子，劉虞不敢作天子。","曹瞞纂亂從此始，董逃董逃人莫喜。","勝負飜环相枕倚，縫綴难成裁破易。","何況曲針不能伸巧指，欲学裁縫須準擬。"]', '诗', 'shi', '', NULL, '相和歌辭  董逃行 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99e999f8-b07a-4142-be3d-c61182662afe', '相和歌辭  董逃行', '相和歌辞  董逃行', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["洛陽城頭火曈曈，亂兵燒我天子宮。","宮城南面有深山，盡將老幼藏其間。","重巖爲屋橡爲食，丁男夜行候消息。","聞道官軍猶掠人，舊里如今歸未得。","董逃行，漢家幾時重太平。"]', '["洛陽城头火曈曈，亂兵燒我天子宮。","宮城南面有深山，尽將老幼藏其间。","重巖爲屋橡爲食，丁男夜行候消息。","闻道官軍猶掠人，旧里如今归未得。","董逃行，漢家幾时重太平。"]', '诗', 'shi', '', NULL, '相和歌辭  董逃行 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea4f954e-f947-4ea6-a7ce-24425dcf7fea', '相和歌辭  相逢行', '相和歌辞  相逢行', 'c91ae931-2891-49b6-9175-74c9bc65e201', '唐', '["妾年初二八，家住洛橋頭。","玉戶臨馳道，朱門近御溝。","使君何假問，夫壻大長秋。","女弟新承寵，諸兄近拜侯。","春生百子殿，花發五城樓。","出入千門裏，年年樂未休。"]', '["妾年初二八，家住洛橋头。","玉戶臨驰道，朱门近御溝。","使君何假问，夫壻大长秋。","女弟新承寵，諸兄近拜侯。","春生百子殿，花發五城楼。","出入千门裏，年年乐未休。"]', '诗', 'shi', '', NULL, '相和歌辭  相逢行 崔顥 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82ed411b-a2e4-4e0b-94fb-b73c350e7f6f', '相和歌辭 相逢行二首 一', '相和歌辞 相逢行二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["朝騎五花馬，謁帝出銀臺。","秀色誰家子，雲車珠箔開。","金鞭遙指點，玉勒近遲回。","夾轂相借問，疑從天上來。","憐腸愁欲斷，斜日復相催。","下車何輕盈，飄然似落梅。","邀入青綺門，當歌共銜杯。","銜杯映歌扇，似月雲中見。","相見不相親，不如不相見。","相見情已深，未語可知心。","胡爲守空閨，孤眠愁錦衾。","錦衾與羅幃，纏緜會有時。","春風正澹蕩，暮雨來何遲？","願因三青鳥，更報長相思。","光景不待人，須臾髮成絲。","當年失行樂，老去徒傷悲。","持此道密意，無令曠佳期。"]', '["朝騎五花马，謁帝出銀台。","秀色誰家子，云车珠箔开。","金鞭遙指点，玉勒近遲回。","夾轂相借问，疑從天上来。","怜腸愁欲斷，斜日复相催。","下车何轻盈，飄然似落梅。","邀入青綺门，當歌共銜杯。","銜杯映歌扇，似月云中见。","相见不相親，不如不相见。","相见情已深，未語可知心。","胡爲守空閨，孤眠愁錦衾。","錦衾與羅幃，纏緜會有时。","春风正澹蕩，暮雨来何遲？","願因三青鸟，更報长相思。","光景不待人，須臾髮成絲。","當年失行乐，老去徒傷悲。","持此道密意，無令曠佳期。"]', '诗', 'shi', '', NULL, '相和歌辭 相逢行二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b26b1959-9880-4d5c-9c8a-baef9a5ea015', '相和歌辭 相逢行二首 二', '相和歌辞 相逢行二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["相逢紅塵內，高揖黃金鞭。","萬戶垂楊裏，君家阿那邊。"]', '["相逢紅塵內，高揖黄金鞭。","万戶垂楊裏，君家阿那邊。"]', '诗', 'shi', '', NULL, '相和歌辭 相逢行二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d6973c8-af8f-4d6f-a5a1-b118bfe79d1e', '相和歌辭 相逢行', '相和歌辞 相逢行', '291d83cc-0172-4769-9eb9-93186f0b0bb9', '唐', '["二十登漢朝，英聲邁今古。","適從東方來，又欲謁明主。","猶酣新豐酒，尚帶霸陵雨。","邂逅兩相逢，別來間寒暑。","寧知白日晚，暫向花間語。","忽聞長樂鐘，走馬東西去。"]', '["二十登漢朝，英声邁今古。","適從东方来，又欲謁明主。","猶酣新豐酒，尚带霸陵雨。","邂逅兩相逢，別来间寒暑。","寧知白日晚，暫向花间語。","忽闻长乐鐘，走马东西去。"]', '诗', 'shi', '', NULL, '相和歌辭 相逢行 韋應物 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61f1af4-8a39-4edf-b40d-b60a64e37522', '相和歌辭 三婦豔詩', '相和歌辞 三婦豔诗', 'ccecc1bb-eb6f-4fb5-be66-3bade24af40f', '唐', '["大婦裁紈素，中婦弄明璫。","小婦多姿態，登樓紅粉妝。","丈人且安坐，初日漸流光。"]', '["大婦裁紈素，中婦弄明璫。","小婦多姿態，登楼紅粉妝。","丈人且安坐，初日漸流光。"]', '诗', 'shi', '', NULL, '相和歌辭 三婦豔詩 董思恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1489e5d3-0e01-4f6e-9c33-515bbff5fd6e', '相和歌辭 中婦織流黃', '相和歌辞 中婦织流黄', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["寒閨織素錦，含怨斂雙蛾。","綜新交縷澀，經脆斷絲多。","衣香逐舉袖，釧動應鳴梭。","還恐裁縫罷，無信達交河。"]', '["寒閨织素錦，含怨斂雙蛾。","綜新交縷澀，經脆斷絲多。","衣香逐舉袖，釧动應鳴梭。","還恐裁縫罷，無信達交河。"]', '诗', 'shi', '', NULL, '相和歌辭 中婦織流黃 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c63ca3bc-5291-4de9-871f-ed28329cb645', '相和歌辭 難忘曲', '相和歌辞 难忘曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["夾道開洞門，弱楊低畫戟。","簾影竹葉起，簫聲吹日色。","蠭語繞妝鏡，拂蛾學春碧。","亂繫丁香梢，滿闌花向夕。"]', '["夾道开洞门，弱楊低畫戟。","簾影竹葉起，簫声吹日色。","蠭語繞妝镜，拂蛾学春碧。","亂繫丁香梢，满闌花向夕。"]', '诗', 'shi', '', NULL, '相和歌辭 難忘曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f34d119-60d9-4762-87c7-7d84d0baa8ff', '相和歌辭 塘上行', '相和歌辞 塘上行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["藕花涼露溼，花缺藕根澀。","飛下雌鴛鴦，塘水聲溢溢。"]', '["藕花涼露溼，花缺藕根澀。","飞下雌鴛鴦，塘水声溢溢。"]', '诗', 'shi', '', NULL, '相和歌辭 塘上行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5043109d-30c1-4c03-a6b5-c04c46051954', '相和歌辭 苦辛行', '相和歌辞 苦辛行', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["且莫奏短歌，聽余苦辛詞。","如今刀筆士，不及屠酤兒。","少年無事學詩賦，豈意文章復相誤。","東西南北少知音，終年竟歲悲行路。","仰面訴天天不聞，低頭告地地不言。","天地生我尚如此，陌上他人何足論。","誰謂西江深，涉之固無憂。","誰謂南山高，可以登之遊。","險巇惟有世間路，一嚮令人堪白頭。","貴人立意不可測，等閑桃李成荆棘。","風塵之士深可親，心如雞犬能依人。","悲來卻憶漢天子，不棄相如家舊貧。","飲酒酒能散羇愁，誰家有酒判一醉，萬事從他江水流。"]', '["且莫奏短歌，听余苦辛词。","如今刀笔士，不及屠酤兒。","少年無事学诗賦，豈意文章复相誤。","东西南北少知音，終年竟歲悲行路。","仰面訴天天不闻，低头告地地不言。","天地生我尚如此，陌上他人何足論。","誰謂西江深，涉之固無憂。","誰謂南山高，可以登之游。","險巇惟有世间路，一嚮令人堪白头。","貴人立意不可測，等闲桃李成荆棘。","风塵之士深可親，心如雞犬能依人。","悲来卻憶漢天子，不棄相如家旧貧。","饮酒酒能散羇愁，誰家有酒判一醉，万事從他江水流。"]', '诗', 'shi', '', NULL, '相和歌辭 苦辛行 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('809cc96a-74a8-4569-a88d-c218523e0d3c', '相和歌辭 秋胡行', '相和歌辞 秋胡行', '776aa2d1-2611-44eb-88cd-f71e110255b4', '唐', '["妾本邯鄲未嫁時，容華倚翠人未知。","一朝結髮從君子，將妾迢迢東路陲。","時逢大道無難阻，君方遊宦從陳汝。","蕙樓獨臥頻度春，彩落辭君幾徂暑。","三月垂楊蠶未眠，攜籠結侶南陌邊。","道逢行子不相識，贈妾黃金買少年。","妾家夫壻輕離久，寸心誓與長相守。","願言行路莫多情，送妾貞心在人口。","日暮蠶飢相命歸，攜籠端飾來庭闈。","勞心苦力終無恨，所冀君恩那可依。","聞說行人已歸止，乃是向來贈金子。","相看顏色不復言，相顧懷慙有何已。","從來自隱無疑背，直爲君情也相會。","如何咫尺仍有情，況復迢迢千里外。","此時顧恩不顧身，念君此日赴河津。","莫道向來不得意，故欲留規誡後人。"]', '["妾本邯鄲未嫁时，容华倚翠人未知。","一朝結髮從君子，將妾迢迢东路陲。","时逢大道無难阻，君方游宦從陳汝。","蕙楼独臥頻度春，彩落辞君幾徂暑。","三月垂楊蠶未眠，携籠結侶南陌邊。","道逢行子不相識，贈妾黄金買少年。","妾家夫壻轻離久，寸心誓與长相守。","願言行路莫多情，送妾貞心在人口。","日暮蠶飢相命归，携籠端飾来庭闈。","勞心苦力終無恨，所冀君恩那可依。","闻说行人已归止，乃是向来贈金子。","相看顏色不复言，相顧懷慙有何已。","從来自隐無疑背，直爲君情也相會。","如何咫尺仍有情，況复迢迢千里外。","此时顧恩不顧身，念君此日赴河津。","莫道向来不得意，故欲留規誡後人。"]', '诗', 'shi', '', NULL, '相和歌辭 秋胡行 高適 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adce5e88-590f-4588-b15b-177368149d8b', '相和歌辭 善哉行', '相和歌辞 善哉行', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["有美一人兮婉如清揚，識曲別音兮令姿煌煌。","繡袂捧琴兮登君子堂，如彼萱草兮使我憂忘。","欲贈之以紫玉尺，白銀璫，久不見之兮湘水茫茫。"]', '["有美一人兮婉如清揚，識曲別音兮令姿煌煌。","繡袂捧琴兮登君子堂，如彼萱草兮使我憂忘。","欲贈之以紫玉尺，白銀璫，久不见之兮湘水茫茫。"]', '诗', 'shi', '', NULL, '相和歌辭 善哉行 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ac1fb39-17d3-4dae-b046-94dfd282aa77', '相和歌辭 善哉行', '相和歌辞 善哉行', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["大鵬刷翮謝溟渤，青雲萬層高突出。","下視秋濤空渺瀰，舊處魚龍皆細物。","人生在世何容易，眼濁心昏信生死。","願除嗜慾待身輕，攜手同尋列仙事。"]', '["大鵬刷翮謝溟渤，青云万層高突出。","下視秋濤空渺瀰，旧处鱼龙皆細物。","人生在世何容易，眼濁心昏信生死。","願除嗜慾待身轻，携手同尋列仙事。"]', '诗', 'shi', '', NULL, '相和歌辭 善哉行 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('397d3ca6-87eb-49f5-ac12-65687c07ce8c', '相和歌辭 來日大難', '相和歌辞 来日大难', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["來日一身，攜糧負薪。","道長食盡，苦口焦脣。","今日醉飽，樂過千春。","仙人相存，誘我遠學。","海陵三山，陸憩五嶽。","乘龍上三天，飛目瞻兩角。","授以神藥，金丹滿握。","蟪蛄蒙恩，深媿短促。","思填東海，彊銜一木。","道重天地，軒師廣成。","蟬翼九五，以求長生。","下士大笑，如蒼蠅聲。"]', '["来日一身，携糧負薪。","道长食尽，苦口焦脣。","今日醉飽，乐過千春。","仙人相存，誘我远学。","海陵三山，陸憩五嶽。","乘龙上三天，飞目瞻兩角。","授以神藥，金丹满握。","蟪蛄蒙恩，深媿短促。","思填东海，彊銜一木。","道重天地，軒師廣成。","蟬翼九五，以求长生。","下士大笑，如蒼蠅声。"]', '诗', 'shi', '', NULL, '相和歌辭 來日大難 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('652f32ba-492d-4b39-9216-aca92a6e9370', '相和歌辭 當來日大難', '相和歌辞 當来日大难', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["當來日大難行，前有坂，後有坑，大梁側，小梁傾，兩軸相絞，兩輪相撐，大牛豎，小牛橫，烏啄牛背，足跌力獰。","當來日大難行，太行雖險，險可使平。","輪軸自撓，牽制不停。","泥潦漸久，荆棘旋生。","行必不得，不如不行。"]', '["當来日大难行，前有坂，後有坑，大梁側，小梁傾，兩軸相絞，兩輪相撐，大牛豎，小牛橫，烏啄牛背，足跌力獰。","當来日大难行，太行雖險，險可使平。","輪軸自撓，牽制不停。","泥潦漸久，荆棘旋生。","行必不得，不如不行。"]', '诗', 'shi', '', NULL, '相和歌辭 當來日大難 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c00d63a-b248-45a7-ad8b-d40f0c52b857', '相和歌辭 隴西行', '相和歌辞 隴西行', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["十里一走馬，五里一揚鞭。","都護軍書至，匈奴圍酒泉。","關山正飛雪，烽戍斷無煙。"]', '["十里一走马，五里一揚鞭。","都護軍书至，匈奴圍酒泉。","关山正飞雪，烽戍斷無煙。"]', '诗', 'shi', '', NULL, '相和歌辭 隴西行 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfb724d3-b6ef-4c81-a5c7-ef90595445ad', '相和歌辭 隴西行', '相和歌辞 隴西行', '7c891598-5c2d-4135-b2cd-60fcb5f29523', '唐', '["雪下陽關路，人稀隴戍頭。","封狐猶未翦，邊將豈無羞。","白草三冬色，黃雲萬里愁。","因思李都尉，畢竟不封侯。"]', '["雪下陽关路，人稀隴戍头。","封狐猶未翦，邊將豈無羞。","白草三冬色，黄云万里愁。","因思李都尉，畢竟不封侯。"]', '诗', 'shi', '', NULL, '相和歌辭 隴西行 耿[湋] shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dad3755e-883c-4022-83a4-4a47583c8112', '相和歌辭 隴西行', '相和歌辞 隴西行', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["陰雲凝朔氣，隴上正飛雪。","四月草不生，北風勁如切。","朝來羽書急，夜救長城窟。","道隘行不前，相呼抱鞍歇。","人寒指欲墮，馬凍蹄亦裂。","射雁旋充飢，斧冰還止渴。","寧辭解圍鬬，但恐乘疲沒。","早晚邊候空，歸來養羸卒。"]', '["陰云凝朔氣，隴上正飞雪。","四月草不生，北风勁如切。","朝来羽书急，夜救长城窟。","道隘行不前，相呼抱鞍歇。","人寒指欲墮，马凍蹄亦裂。","射雁旋充飢，斧冰還止渴。","寧辞解圍鬬，但恐乘疲沒。","早晚邊候空，归来養羸卒。"]', '诗', 'shi', '', NULL, '相和歌辭 隴西行 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c30e1abf-008b-4c36-8359-3793eb92ba45', '相和歌辭 東門行', '相和歌辞 东门行', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["漢家三十六將軍，東方雷動橫陣雲。","雞鳴函谷客如霧，貌同心異不可數。","赤丸夜語飛電光，徼巡司隸眠如羊。","當街一叱百吏走，馮敬胷中函匕首。","兇徒側耳潛愜心，悍臣破膽皆杜口。","魏王臥內藏兵符，子西掩袂真無辜。","羌胡轂下一朝起，敵國舟中非所擬。","安陵誰辨削礪功，韓國詎明深井里。","絕咽斷骨那下補，萬金寵贈不如土。"]', '["漢家三十六將軍，东方雷动橫陣云。","雞鳴函谷客如霧，貌同心異不可數。","赤丸夜語飞電光，徼巡司隸眠如羊。","當街一叱百吏走，馮敬胷中函匕首。","兇徒側耳潛愜心，悍臣破膽皆杜口。","魏王臥內藏兵符，子西掩袂真無辜。","羌胡轂下一朝起，敵国舟中非所擬。","安陵誰辨削礪功，韓国詎明深井里。","絕咽斷骨那下補，万金寵贈不如土。"]', '诗', 'shi', '', NULL, '相和歌辭 東門行 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f91423-ebde-4604-84a1-fef1bff26ba7', '相和歌辭 飲馬長城窟行', '相和歌辞 饮马长城窟行', 'f78aa699-e012-4059-9e29-5d30e16cc1d8', '唐', '["塞外悲風切，交河冰已結。","瀚海百重波，陰山千里雪。","迥戍危烽火，層巒引高節。","悠悠卷斾旌，飲馬出長城。","寒沙連騎迹，朔吹斷邊聲。","胡塵清玉塞，羌笛韻金鉦。","絕寞干戈戢，車徒振原隰。","都尉反龍堆，將軍旋馬邑。","揚麾氛霧靜，紀石功名立。","荒裔一戎衣，雲臺凱歌入。"]', '["塞外悲风切，交河冰已結。","瀚海百重波，陰山千里雪。","迥戍危烽火，層巒引高節。","悠悠卷斾旌，饮马出长城。","寒沙連騎迹，朔吹斷邊声。","胡塵清玉塞，羌笛韻金鉦。","絕寞干戈戢，车徒振原隰。","都尉反龙堆，將軍旋马邑。","揚麾氛霧静，紀石功名立。","荒裔一戎衣，云台凱歌入。"]', '诗', 'shi', '', NULL, '相和歌辭 飲馬長城窟行 太宗皇帝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8944162e-0986-4d0b-b9f9-ce0b899c0298', '相和歌辭 飲馬長城窟行', '相和歌辞 饮马长城窟行', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["馳馬渡河干，流深馬渡難。","前逢錦車使，都護在樓蘭。","輕騎猶銜勒，疑兵尚解鞍。","溫池下絕澗，棧道接危巒。","拓地勳未賞，亡城律詎寬。","有月關猶暗，經春隴尚寒。","雲昏無復影，冰合不聞湍。","懷君不可遇，聊持報一餐。"]', '["驰马渡河干，流深马渡难。","前逢錦车使，都護在楼蘭。","轻騎猶銜勒，疑兵尚解鞍。","溫池下絕澗，棧道接危巒。","拓地勳未賞，亡城律詎寬。","有月关猶暗，經春隴尚寒。","云昏無复影，冰合不闻湍。","懷君不可遇，聊持報一餐。"]', '诗', 'shi', '', NULL, '相和歌辭 飲馬長城窟行 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b20b87c-18e6-4769-b07e-72665771fd11', '相和歌辭 飲馬長城窟行', '相和歌辞 饮马长城窟行', '7f5b8321-3a66-4a98-8eae-a72d67d79920', '唐', '["朔風動秋草，清蹕長安道。","長城連不窮，所以隔華戎。","規模惟聖作，荷負曉成功。","鳥庭已向內，龍荒更鑿空。","玉關塵卷靜，金微路已通。","湯征隨北怨，舜詠起南風。","畫野功初立，綏邊事云集。","朝服踐狼居，凱歌旋馬邑。","山響傳鳳吹，霜華藻瓊鈒。","屬國擁節歸，單于款關入。","日落寒雲起，驚沙被原隰。","零落葉已寒，河流清且急。","四時徭役盡，千載干戈戢。","太平今若斯，汗馬竟無施。","惟當事筆研，歸去草封禪。"]', '["朔风动秋草，清蹕长安道。","长城連不窮，所以隔华戎。","規模惟聖作，荷負晓成功。","鸟庭已向內，龙荒更鑿空。","玉关塵卷静，金微路已通。","湯征隨北怨，舜詠起南风。","畫野功初立，綏邊事云集。","朝服踐狼居，凱歌旋马邑。","山响傳鳳吹，霜华藻瓊鈒。","屬国擁節归，單于款关入。","日落寒云起，驚沙被原隰。","零落葉已寒，河流清且急。","四时徭役尽，千載干戈戢。","太平今若斯，汗马竟無施。","惟當事笔研，归去草封禪。"]', '诗', 'shi', '', NULL, '相和歌辭 飲馬長城窟行 袁朗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84b8b0b-9447-467f-819f-0ddf0f00a03a', '相和歌辭 飲馬長城窟行', '相和歌辞 饮马长城窟行', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["長安少年無遠圖，一生惟羨執金吾。","騏驎前殿拜天子，走馬爲君西擊胡。","胡沙獵獵吹人面，漢虜相逢不相見。","遙聞鼙鼓動地來，傳道單于夜猶戰。","此時顧恩寧顧身，爲君一行摧萬人。","壯士揮戈回白日，單于濺血染朱輪。","回來飲馬長城窟，長安道傍多白骨。","問之耆老何代人，云是秦王築城卒。","黃昏塞北無人煙，鬼哭啾啾聲沸天。","無罪見誅功不賞，孤魂流落此城邊。","當昔秦王按劒起，諸侯膝行不敢視。","富國彊兵二十年，築怨興徭九千里。","秦王築城何太愚，天實亡秦非北胡。","一朝禍起蕭牆內，渭水咸陽不復都。"]', '["长安少年無远圖，一生惟羨執金吾。","騏驎前殿拜天子，走马爲君西擊胡。","胡沙獵獵吹人面，漢虜相逢不相见。","遙闻鼙鼓动地来，傳道單于夜猶戰。","此时顧恩寧顧身，爲君一行摧万人。","壯士揮戈回白日，單于濺血染朱輪。","回来饮马长城窟，长安道傍多白骨。","问之耆老何代人，云是秦王築城卒。","黄昏塞北無人煙，鬼哭啾啾声沸天。","無罪见誅功不賞，孤魂流落此城邊。","當昔秦王按劒起，諸侯膝行不敢視。","富国彊兵二十年，築怨兴徭九千里。","秦王築城何太愚，天實亡秦非北胡。","一朝禍起蕭牆內，渭水咸陽不复都。"]', '诗', 'shi', '', NULL, '相和歌辭 飲馬長城窟行 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06bd32a2-f9f5-4bfe-a55e-fadd67afc789', '相和歌辭 飲馬長城窟行', '相和歌辞 饮马长城窟行', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["長城窟，長城窟邊多馬骨。","古來此地無井泉，賴得秦家築城卒。","征人飲馬愁不回，長城變作望鄉堆。","蹄跡未乾人去近，續後馬來泥汙盡。","枕弓睡著待水生，不見陰山在前陣。","馬蹄足脫裝馬頭，健兒戰死誰封侯。"]', '["长城窟，长城窟邊多马骨。","古来此地無井泉，賴得秦家築城卒。","征人饮马愁不回，长城变作望乡堆。","蹄跡未乾人去近，續後马来泥汙尽。","枕弓睡著待水生，不见陰山在前陣。","马蹄足脫裝马头，健兒戰死誰封侯。"]', '诗', 'shi', '', NULL, '相和歌辭 飲馬長城窟行 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13f88c40-f660-4910-8d8c-7c29cfcd416e', '相和歌辭 飲馬長城窟行', '相和歌辞 饮马长城窟行', 'e951fd69-0e95-4b75-93f6-e4f6aff1c750', '唐', '["游客長城下，飲馬長城窟。","馬嘶聞水腥，爲浸征人骨。","豈不是流泉，終不成潺湲。","洗盡骨上土，不洗骨中冤。","骨若比流水，四海有還魂。","空流嗚咽聲，聲中疑是言。"]', '["游客长城下，饮马长城窟。","马嘶闻水腥，爲浸征人骨。","豈不是流泉，終不成潺湲。","洗尽骨上土，不洗骨中冤。","骨若比流水，四海有還魂。","空流嗚咽声，声中疑是言。"]', '诗', 'shi', '', NULL, '相和歌辭 飲馬長城窟行 僧子蘭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8b006af-ed1c-4206-8647-24e8623ca5b2', '相和歌辭 上留田', '相和歌辞 上留田', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["行至上留田，孤墳何崢嶸。","積此萬古恨，春草不復生。","悲風四邊來，腸斷白楊聲。","借問誰家地，埋沒蒿里塋。","古老向余言，言是上留田。","蓬科馬鬣今已平，昔之弟死兄不葬。","他人於此舉銘旌，一鳥死，百鳥鳴，一獸死，百獸驚。","桓山之禽別離苦，欲去迴翔不能征。","田氏倉卒骨肉分，青天白日摧紫荆。","交柯之木本同形，東枝顦顇西枝榮。","無心之物尚如此，參商胡乃尋天兵。","孤竹延陵，讓國揚名。","高風緬邈，頹波激清。","尺布之謠，塞耳不能聽。"]', '["行至上留田，孤墳何崢嶸。","積此万古恨，春草不复生。","悲风四邊来，腸斷白楊声。","借问誰家地，埋沒蒿里塋。","古老向余言，言是上留田。","蓬科马鬣今已平，昔之弟死兄不葬。","他人於此舉銘旌，一鸟死，百鸟鳴，一獸死，百獸驚。","桓山之禽別離苦，欲去迴翔不能征。","田氏倉卒骨肉分，青天白日摧紫荆。","交柯之木本同形，东枝顦顇西枝榮。","無心之物尚如此，參商胡乃尋天兵。","孤竹延陵，讓国揚名。","高风緬邈，頹波激清。","尺布之謠，塞耳不能听。"]', '诗', 'shi', '', NULL, '相和歌辭 上留田 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11b61b50-be30-4816-ac5a-5345e9a5fba6', '相和歌辭 上留田', '相和歌辞 上留田', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["父不父，兄不兄，上留田，蝥賊生。","徒陟岡，淚崢嶸，我欲使諸凡鳥雀，盡變爲鶺鴒。","我欲使諸凡草木，盡變爲田荆。","鄰人歌，鄰人歌，古風清，清風生。"]', '["父不父，兄不兄，上留田，蝥賊生。","徒陟岡，泪崢嶸，我欲使諸凡鸟雀，尽变爲鶺鴒。","我欲使諸凡草木，尽变爲田荆。","鄰人歌，鄰人歌，古风清，清风生。"]', '诗', 'shi', '', NULL, '相和歌辭 上留田 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f4ff5d9-6454-4e9a-94e9-9baca2276713', '相和歌辭 安樂宮', '相和歌辞 安乐宮', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["深井桐烏起，尚復牽清水。","未盥邵陵王，瓶中弄長翠。","新城安樂宮，宮如鳳皇翅。","歌迴蠟版鳴，大綰提壺使。","綠繁悲水曲，茱萸別秋子。"]', '["深井桐烏起，尚复牽清水。","未盥邵陵王，瓶中弄长翠。","新城安乐宮，宮如鳳皇翅。","歌迴蠟版鳴，大綰提壺使。","綠繁悲水曲，茱萸別秋子。"]', '诗', 'shi', '', NULL, '相和歌辭 安樂宮 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('308d0334-e166-4f5c-b33d-230b799e99bf', '相和歌辭 放歌行', '相和歌辞 放歌行', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["南渡洛陽津，西望十二樓。","明堂坐天子，月朔朝諸侯。","清樂動千門，皇風被九州。","慶雲從東來，泱漭抱日流。","升平貴論道，文墨將何求。","有詔徵草澤，微臣獻謀猷。","冠冕如星羅，拜揖曹與周。","望塵非吾事，入賦且遲留。","幸蒙國士識，因脫負薪裘。","今者放歌行，以慰梁父愁。","但營數斗祿，奉養毋豐羞。","若得金膏遂，飛雲亦可儔。"]', '["南渡洛陽津，西望十二楼。","明堂坐天子，月朔朝諸侯。","清乐动千门，皇风被九州。","慶云從东来，泱漭抱日流。","升平貴論道，文墨將何求。","有詔徵草澤，微臣獻謀猷。","冠冕如星羅，拜揖曹與周。","望塵非吾事，入賦且遲留。","幸蒙国士識，因脫負薪裘。","今者放歌行，以慰梁父愁。","但營數斗祿，奉養毋豐羞。","若得金膏遂，飞云亦可儔。"]', '诗', 'shi', '', NULL, '相和歌辭 放歌行 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af9e3b23-756d-4567-8ca2-fb91d9cd6e91', '相和歌辭 野田黃雀行', '相和歌辞 野田黄雀行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["遊莫逐炎洲翠，棲莫近吳宮燕。","吳宮火起焚爾窠，炎洲逐翠遭網羅。"]', '["游莫逐炎洲翠，棲莫近吳宮燕。","吳宮火起焚爾窠，炎洲逐翠遭網羅。"]', '诗', 'shi', '', NULL, '相和歌辭 野田黃雀行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73d28ad8-e8fe-402a-8597-df3c3c6c539d', '相和歌辭 野田黃雀行', '相和歌辞 野田黄雀行', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["嘖嘖野田雀，不知軀體微。","閑穿深蒿裏，爭食復爭飛。","窮老一頹舍，棗多桑樹稀。","無棗猶可食，無桑何以衣。","蕭條空倉暮，相引時來歸。","邪路豈不捷，渚田豈不肥。","水長路且壞，惻惻與心違。"]', '["嘖嘖野田雀，不知軀體微。","闲穿深蒿裏，爭食复爭飞。","窮老一頹舍，棗多桑樹稀。","無棗猶可食，無桑何以衣。","蕭條空倉暮，相引时来归。","邪路豈不捷，渚田豈不肥。","水长路且壞，惻惻與心違。"]', '诗', 'shi', '', NULL, '相和歌辭 野田黃雀行 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4721e5f-67be-44b3-8895-f604912c470b', '相和歌辭 野田黃雀行', '相和歌辞 野田黄雀行', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["高樹風多，吹爾巢落。","深蒿葉暖，宜爾依薄。","莫近鴞類，珠網亦惡。","飲野田之清水，食野田之黃粟。","深花中睡，𡋯土裏浴。","如此即全勝啄太倉之穀，而更穿人屋。"]', '["高樹风多，吹爾巢落。","深蒿葉暖，宜爾依薄。","莫近鴞類，珠網亦惡。","饮野田之清水，食野田之黄粟。","深花中睡，𡋯土裏浴。","如此即全勝啄太倉之穀，而更穿人屋。"]', '诗', 'shi', '', NULL, '相和歌辭 野田黃雀行 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('508776ed-7243-4d07-b409-8e02a9eea87b', '相和歌辭 野田黃雀行', '相和歌辞 野田黄雀行', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["雙雙野田雀，上下同飲啄。","暖去棲蓬蒿，寒歸傍籬落。","殷勤避羅網，乍可遇鵰鶚。","鵰鶚雖不仁，分明在寥廓。"]', '["雙雙野田雀，上下同饮啄。","暖去棲蓬蒿，寒归傍籬落。","殷勤避羅網，乍可遇鵰鶚。","鵰鶚雖不仁，分明在寥廓。"]', '诗', 'shi', '', NULL, '相和歌辭 野田黃雀行 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8ff176a-ba69-4277-a54e-9e515bc19304', '相和歌辭 雁門太守行', '相和歌辞 雁门太守行', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["黑雲壓城城欲摧，甲光向月金鱗開。","角聲滿天秋色裏，塞上燕支凝夜紫。","半卷紅旗臨易水，霜重鼓寒聲不起。","報君黃金臺上意，提攜玉龍爲君死。"]', '["黑云壓城城欲摧，甲光向月金鱗开。","角声满天秋色裏，塞上燕支凝夜紫。","半卷紅旗臨易水，霜重鼓寒声不起。","報君黄金台上意，提携玉龙爲君死。"]', '诗', 'shi', '', NULL, '相和歌辭 雁門太守行 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5901d95d-baf0-46dd-9a29-fd3c020c0a70', '相和歌辭 雁門太守行', '相和歌辞 雁门太守行', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["城頭月沒霜如水，趚趚蹋沙人似鬼。","燈前拭淚試香裘，長引一聲殘漏子。","駝囊瀉酒酒一杯，前頭啑血心不回。","寄語年少妻莫哀，魚金虎竹天上來，雁門山邊骨成灰。"]', '["城头月沒霜如水，趚趚蹋沙人似鬼。","灯前拭泪試香裘，长引一声殘漏子。","駝囊瀉酒酒一杯，前头啑血心不回。","寄語年少妻莫哀，鱼金虎竹天上来，雁门山邊骨成灰。"]', '诗', 'shi', '', NULL, '相和歌辭 雁門太守行 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c067a87-d475-491d-8786-b811118cfce2', '相和歌辭 雁門太守行', '相和歌辞 雁门太守行', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["旌旗閃閃搖天末，長笛橫吹虜塵闊。","跨下嘶風白練獰，腰間切玉青蛇活。","擊革摐金燧牛尾，犬羊兵敗如山死。","九泉寂寞葬秋蟲，溼雲荒草啼秋思。"]', '["旌旗閃閃搖天末，长笛橫吹虜塵闊。","跨下嘶风白練獰，腰间切玉青蛇活。","擊革摐金燧牛尾，犬羊兵敗如山死。","九泉寂寞葬秋蟲，溼云荒草啼秋思。"]', '诗', 'shi', '', NULL, '相和歌辭 雁門太守行 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b39a2f1c-b07b-43c6-8f88-fa8ef3b06e4b', '相和歌辭 飛來雙白鶴', '相和歌辞 飞来雙白鹤', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["飛來雙白鶴，奮翼遠凌煙。","雙棲集紫蓋，一舉背青田。","颺影過伊洛，流聲入管弦。","鳴羣倒景外，刷羽閬風前。","映海疑浮雪，拂澗瀉飛泉。","燕雀寧知去，蜉蝣不識還。","何言別儔侶，從此間山川。","顧步已相失，裴回反自憐。","危心猶警露，哀響詎聞天。","無因振六翮，輕舉復隨仙。"]', '["飞来雙白鹤，奮翼远凌煙。","雙棲集紫蓋，一舉背青田。","颺影過伊洛，流声入管弦。","鳴羣倒景外，刷羽閬风前。","映海疑浮雪，拂澗瀉飞泉。","燕雀寧知去，蜉蝣不識還。","何言別儔侶，從此间山川。","顧步已相失，裴回反自怜。","危心猶警露，哀响詎闻天。","無因振六翮，轻舉复隨仙。"]', '诗', 'shi', '', NULL, '相和歌辭 飛來雙白鶴 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eeafa160-a9d9-484d-9cbe-01a796260aa2', '相和歌辭 門有車馬客行', '相和歌辞 门有车马客行', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["財雄重交結，戚里擅豪華。","曲臺臨上路，高門抵狹斜。","赭汗千金馬，繡轂五香車。","白鶴隨飛蓋，朱鷺入鳴笳。","夏蓮開劒水，春桃發露花。","輕裙染回雪，浮蟻泛流霞。","高談辨飛兔，摛藻握靈蛇。","逢恩借羽翼，失路委泥沙。","曖曖風煙晚，路長歸騎遠。","日斜青瑣第，塵飛金谷苑。","危弦促柱奏巴渝，遺簪墮珥解羅襦。","如何守直道，飜使谷名愚。"]', '["財雄重交結，戚里擅豪华。","曲台臨上路，高门抵狹斜。","赭汗千金马，繡轂五香车。","白鹤隨飞蓋，朱鷺入鳴笳。","夏蓮开劒水，春桃發露花。","轻裙染回雪，浮蟻泛流霞。","高談辨飞兔，摛藻握靈蛇。","逢恩借羽翼，失路委泥沙。","曖曖风煙晚，路长归騎远。","日斜青瑣第，塵飞金谷苑。","危弦促柱奏巴渝，遺簪墮珥解羅襦。","如何守直道，飜使谷名愚。"]', '诗', 'shi', '', NULL, '相和歌辭 門有車馬客行 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78f8699c-a199-4dde-8be3-79fb887a596d', '相和歌辭 門有車馬客行', '相和歌辞 门有车马客行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["門有車馬客，金鞍曜朱輪。","謂從丹霄落，乃是故鄉親。","呼兒埽中堂，坐客論悲辛。","對酒兩不飲，停觴淚盈巾。","歎我萬里遊，飄颻三十春。","空談霸王略，紫綬不挂身。","雄劒藏玉匣，陰符生素塵。","廓落無所合，流離湘水濱。","借問宗黨間，多爲泉下人。","生苦百戰役，死託萬鬼鄰。","北風揚胡沙，埋翳周與秦。","大運且如此，蒼穹寧匪仁。","惻愴竟何道？存亡任大鈞。"]', '["门有车马客，金鞍曜朱輪。","謂從丹霄落，乃是故乡親。","呼兒埽中堂，坐客論悲辛。","对酒兩不饮，停觴泪盈巾。","歎我万里游，飄颻三十春。","空談霸王略，紫綬不挂身。","雄劒藏玉匣，陰符生素塵。","廓落無所合，流離湘水濱。","借问宗黨间，多爲泉下人。","生苦百戰役，死託万鬼鄰。","北风揚胡沙，埋翳周與秦。","大運且如此，蒼穹寧匪仁。","惻愴竟何道？存亡任大鈞。"]', '诗', 'shi', '', NULL, '相和歌辭 門有車馬客行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7503243-ce66-4f2b-a874-19edc104aa67', '相和歌辭 蜀道難', '相和歌辞 蜀道难', '49ac4a83-cdcf-498b-9963-7c60457963b0', '唐', '["梁山鎮地險，積石阻雲端。","深谷下寥廓，層巖上鬱盤。","飛梁架絕嶺，棧道接危巒。","攬轡獨長息，方知斯路難。"]', '["梁山鎮地險，積石阻云端。","深谷下寥廓，層巖上鬱盤。","飞梁架絕嶺，棧道接危巒。","攬轡独长息，方知斯路难。"]', '诗', 'shi', '', NULL, '相和歌辭 蜀道難 張文琮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e117d224-39ca-4eba-a047-0d36ce8b8c26', '相和歌辭 蜀道難', '相和歌辞 蜀道难', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["噫吁嚱！危乎高哉！蜀道之難難於上青天！蠶叢及魚鳧，開國何茫然。","爾來四萬八千歲，乃與秦塞通人煙。","西當太白有鳥道，可以橫絕峨眉巔。","地崩山摧壯士死，然後天梯石棧方鉤連。","上有六龍迴日之高標，下有衝波逆折之迴川。","黃鶴之飛尚不得，猨猱欲度愁攀緣。","青泥何盤盤，百步九折縈巖巒。","捫參歷井仰脅息，以手撫膺坐長歎。","問君西遊何時還？畏途巉巖不可攀。","但見悲鳥號枯木，雄飛呼雌繞林間。","又聞子規啼夜月，愁空山，蜀道之難難於上青天！使人聽此彫朱顏。","連峰去天不盈尺，枯松倒挂倚絕壁。","飛湍瀑流相喧豗，砅崖轉石萬壑雷。","其嶮也若此，嗟爾遠道之人胡爲乎來哉？","劒閣崢嶸而崔嵬，一夫當關，萬夫莫開。","所守或匪親，化爲狼與豺。","朝避猛虎，夕避長蛇。","磨牙吮血，殺人如麻。","錦城雖云樂，不如早還家。","蜀道之難難於上青天，側身西望長咨嗟。"]', '["噫吁嚱！危乎高哉！蜀道之难难於上青天！蠶叢及鱼鳧，开国何茫然。","爾来四万八千歲，乃與秦塞通人煙。","西當太白有鸟道，可以橫絕峨眉巔。","地崩山摧壯士死，然後天梯石棧方鉤連。","上有六龙迴日之高標，下有衝波逆折之迴川。","黄鹤之飞尚不得，猨猱欲度愁攀緣。","青泥何盤盤，百步九折縈巖巒。","捫參歷井仰脅息，以手撫膺坐长歎。","问君西游何时還？畏途巉巖不可攀。","但见悲鸟號枯木，雄飞呼雌繞林间。","又闻子規啼夜月，愁空山，蜀道之难难於上青天！使人听此彫朱顏。","連峰去天不盈尺，枯松倒挂倚絕壁。","飞湍瀑流相喧豗，砅崖轉石万壑雷。","其嶮也若此，嗟爾远道之人胡爲乎来哉？","劒閣崢嶸而崔嵬，一夫當关，万夫莫开。","所守或匪親，化爲狼與豺。","朝避猛虎，夕避长蛇。","磨牙吮血，殺人如麻。","錦城雖云乐，不如早還家。","蜀道之难难於上青天，側身西望长咨嗟。"]', '诗', 'shi', '', NULL, '相和歌辭 蜀道難 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73727332-47c2-459f-b186-fef59872a906', '相和歌辭 櫂歌行', '相和歌辞 櫂歌行', '8273f36f-2e1d-4891-b19b-5ea766fc9ee1', '唐', '["寫月圖黃罷，凌波拾翠通。","鏡花搖芰日，衣麝入荷風。","葉密舟難蕩，蓮疎浦易空。","鳳媒羞自託，鴛翼恨難窮。","秋帳燈花翠，倡樓粉色紅。","相思無別曲，幷在櫂歌中。"]', '["寫月圖黄罷，凌波拾翠通。","镜花搖芰日，衣麝入荷风。","葉密舟难蕩，蓮疎浦易空。","鳳媒羞自託，鴛翼恨难窮。","秋帳灯花翠，倡楼粉色紅。","相思無別曲，幷在櫂歌中。"]', '诗', 'shi', '', NULL, '相和歌辭 櫂歌行 駱賓王 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b213f7-21b6-47a8-936c-39dde6ca7969', '相和歌辭 櫂歌行', '相和歌辞 櫂歌行', 'ec72e864-2de4-43d6-bcca-d90c758c4325', '唐', '["櫂女飾銀鉤，新妝下翠樓。","霜絲青桂檝，蘭栧紫霞舟。","水落金陵曙，風起洞庭秋。","扣船過曲浦，飛帆越回流。","影入桃花浪，香飄杜若洲。","洲長殊未返，蕭散雲霞晚。","日下大江平，煙生歸岸遠。","岸遠聞潮波，爭途遊戲多。","因聲趙津女，來聽采菱歌。"]', '["櫂女飾銀鉤，新妝下翠楼。","霜絲青桂檝，蘭栧紫霞舟。","水落金陵曙，风起洞庭秋。","扣船過曲浦，飞帆越回流。","影入桃花浪，香飄杜若洲。","洲长殊未返，蕭散云霞晚。","日下大江平，煙生归岸远。","岸远闻潮波，爭途游戲多。","因声趙津女，来听采菱歌。"]', '诗', 'shi', '', NULL, '相和歌辭 櫂歌行 徐堅 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('108740be-423c-4371-a03e-b47c329323db', '相和歌辭 胡無人行', '相和歌辞 胡無人行', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["十月繁霜下，征人遠鑿空。","雲搖錦更節，海照角端弓。","暗磧埋砂樹，衝飆卷塞蓬。","方隨膜拜入，歌舞玉門中。"]', '["十月繁霜下，征人远鑿空。","云搖錦更節，海照角端弓。","暗磧埋砂樹，衝飆卷塞蓬。","方隨膜拜入，歌舞玉门中。"]', '诗', 'shi', '', NULL, '相和歌辭 胡無人行 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bf0ee92-7f9a-4a6a-842c-82c7903e8b77', '相和歌辭 胡無人行', '相和歌辞 胡無人行', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["男兒徇大義，立節不沽名。","腰間懸陸離，大歌胡無行。","不讀戰國書，不覽黃石經。","醉臥咸陽樓，夢入受降城。","更願生羽翼，飛身入青冥。","請攜天子劒，斫下旄頭星。","自然胡無人，雖有無戰爭。","悠哉典屬國，驅羊老一生。"]', '["男兒徇大義，立節不沽名。","腰间懸陸離，大歌胡無行。","不读戰国书，不覽黄石經。","醉臥咸陽楼，梦入受降城。","更願生羽翼，飞身入青冥。","請携天子劒，斫下旄头星。","自然胡無人，雖有無戰爭。","悠哉典屬国，驱羊老一生。"]', '诗', 'shi', '', NULL, '相和歌辭 胡無人行 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44a1f752-1141-4011-8fee-be45b5100d07', '相和歌辭 胡無人行', '相和歌辞 胡無人行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嚴風吹霜海草彫，筋幹精堅胡馬驕。","漢家戰士三十萬，將軍兼領霍嫖姚。","流星白羽腰間插，劒花秋蓮光出匣。","天兵照雪下玉關，虜箭如沙射金甲。","雲龍風虎盡交迴，太白入月敵可摧。","敵可摧，旄頭滅，履胡之腸涉胡血。","懸胡青天上，埋胡紫[塞]旁。","胡無人，漢道昌，陛下之壽三千霜。","但歌大風雲飛揚，安得猛士兮守四方。","胡無人，漢道昌。"]', '["嚴风吹霜海草彫，筋幹精堅胡马驕。","漢家戰士三十万，將軍兼領霍嫖姚。","流星白羽腰间插，劒花秋蓮光出匣。","天兵照雪下玉关，虜箭如沙射金甲。","云龙风虎尽交迴，太白入月敵可摧。","敵可摧，旄头滅，履胡之腸涉胡血。","懸胡青天上，埋胡紫[塞]旁。","胡無人，漢道昌，陛下之壽三千霜。","但歌大风云飞揚，安得猛士兮守四方。","胡無人，漢道昌。"]', '诗', 'shi', '', NULL, '相和歌辭 胡無人行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45cf3f1a-85b6-4fbe-ad2d-9ccb544dc070', '相和歌辭 胡無人行', '相和歌辞 胡無人行', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["霍嫖姚，趙充國，天子將之平朔漠。","肉胡之肉，燼胡帳幄。","千里萬里，惟留胡之空殼。","邊風蕭蕭，榆葉初落。","殺氣晝赤，枯骨夜哭。","將軍既立殊勳，遂有胡無人曲。","我聞之，天子富有四海，德被無垠。"]', '["霍嫖姚，趙充国，天子將之平朔漠。","肉胡之肉，燼胡帳幄。","千里万里，惟留胡之空殼。","邊风蕭蕭，榆葉初落。","殺氣晝赤，枯骨夜哭。","將軍既立殊勳，遂有胡無人曲。","我闻之，天子富有四海，德被無垠。"]', '诗', 'shi', '', NULL, '相和歌辭 胡無人行 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85a83aa1-746f-4baa-bc0f-deaf8de5fdcd', '相和歌辭 白頭吟', '相和歌辞 白头吟', '29383517-9b77-4d2c-a7ed-3543c8b79cfd', '唐', '["洛陽城東桃李花，飛來飛去落誰家。","洛陽女兒惜顏色，行逢落花長歎息。","今年花落顏色改，明年花開復誰在。","已見松柏摧爲薪，更聞桑田變成海。","古人無復洛城東，今人還對落花風。","年年歲歲花相似，歲歲年年人不同。","寄言全盛紅顏子，須憐半死白頭翁。","此翁白頭真可憐，伊昔紅顏美少年。","公子王孫芳樹下，清歌妙舞落花前。","光祿池臺文錦繡，將軍樓閣畫神仙。","一朝臥病無人識，三春行樂在誰邊。","宛轉蛾眉能幾時，須臾白髮亂如絲。","但看舊來歌舞地，惟有黃昏鳥雀悲。"]', '["洛陽城东桃李花，飞来飞去落誰家。","洛陽女兒惜顏色，行逢落花长歎息。","今年花落顏色改，明年花开复誰在。","已见松柏摧爲薪，更闻桑田变成海。","古人無复洛城东，今人還对落花风。","年年歲歲花相似，歲歲年年人不同。","寄言全盛紅顏子，須怜半死白头翁。","此翁白头真可怜，伊昔紅顏美少年。","公子王孫芳樹下，清歌妙舞落花前。","光祿池台文錦繡，將軍楼閣畫神仙。","一朝臥病無人識，三春行乐在誰邊。","宛轉蛾眉能幾时，須臾白髮亂如絲。","但看旧来歌舞地，惟有黄昏鸟雀悲。"]', '诗', 'shi', '', NULL, '相和歌辭 白頭吟 劉希夷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1592dabe-c91f-48c0-b409-768223174833', '相和歌辭 白頭吟二首 一', '相和歌辞 白头吟二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["錦水東北流，波蕩雙鴛鴦。","雄巢漢宮樹，雌弄秦草芳。","寧同萬死碎綺翼，不忍雲間兩分張。","此時阿嬌正嬌妬，獨坐長門愁日暮。","但願君恩顧妾深，豈惜黃金將買賦。","相如作賦得黃金，丈夫好新多異心。","一朝將聘茂陵女，文君因贈白頭吟。","東流不作西歸水，落花辭條歸故林。","兔絲固無情，隨風任顛倒。","誰使女蘿枝，而來彊縈抱。","兩草猶一心，人心不如草。","莫卷龍須席，從他生網絲。","且留琥珀枕，或有夢來時。","覆水再收豈滿杯，棄妾已去難重回。","古時得意不相負，祗今惟見青陵臺。"]', '["錦水东北流，波蕩雙鴛鴦。","雄巢漢宮樹，雌弄秦草芳。","寧同万死碎綺翼，不忍云间兩分張。","此时阿嬌正嬌妬，独坐长门愁日暮。","但願君恩顧妾深，豈惜黄金將買賦。","相如作賦得黄金，丈夫好新多異心。","一朝將聘茂陵女，文君因贈白头吟。","东流不作西归水，落花辞條归故林。","兔絲固無情，隨风任顛倒。","誰使女蘿枝，而来彊縈抱。","兩草猶一心，人心不如草。","莫卷龙須席，從他生網絲。","且留琥珀枕，或有梦来时。","覆水再收豈满杯，棄妾已去难重回。","古时得意不相負，祗今惟见青陵台。"]', '诗', 'shi', '', NULL, '相和歌辭 白頭吟二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f85b405-4320-4281-aba7-61db92674d02', '相和歌辭 白頭吟二首 二', '相和歌辞 白头吟二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["錦水東流碧，波蕩雙鴛鴦。","雄巢漢宮樹，雌弄秦草芳。","相如去蜀謁武帝，赤車駟馬生輝光。","一朝再覽大人作，萬乘忽欲凌雲翔。","聞道阿嬌失恩寵，千金買賦要君王。","相如不憶貧賤日，官高金多聘私室。","茂陵姝子皆見求，文君歡愛徒此畢。","淚如雙泉水，行墮紫羅襟。","五起雞三唱，清晨白頭吟。","長吁不整綠雲鬢，仰訴青天哀怨深。","城崩杞梁妻，誰道土無心。","東流不作西歸水，落花辭枝羞故林。","頭上玉燕釵，是妾嫁時物。","贈君表相思，羅袖幸時拂。","莫卷龍須席，從他生網絲。","且留琥珀枕，還有夢來時。","鷫鸘裘在錦屏上，自君一挂無由披。","妾有秦樓鏡，照心勝照井。","願持照新人，雙對可憐影。","覆水却收不滿杯，相如還謝文君回。","古來得意不相負，祗今惟有青陵臺。"]', '["錦水东流碧，波蕩雙鴛鴦。","雄巢漢宮樹，雌弄秦草芳。","相如去蜀謁武帝，赤车駟马生輝光。","一朝再覽大人作，万乘忽欲凌云翔。","闻道阿嬌失恩寵，千金買賦要君王。","相如不憶貧賤日，官高金多聘私室。","茂陵姝子皆见求，文君歡愛徒此畢。","泪如雙泉水，行墮紫羅襟。","五起雞三唱，清晨白头吟。","长吁不整綠云鬢，仰訴青天哀怨深。","城崩杞梁妻，誰道土無心。","东流不作西归水，落花辞枝羞故林。","头上玉燕釵，是妾嫁时物。","贈君表相思，羅袖幸时拂。","莫卷龙須席，從他生網絲。","且留琥珀枕，還有梦来时。","鷫鸘裘在錦屏上，自君一挂無由披。","妾有秦楼镜，照心勝照井。","願持照新人，雙对可怜影。","覆水却收不满杯，相如還謝文君回。","古来得意不相負，祗今惟有青陵台。"]', '诗', 'shi', '', NULL, '相和歌辭 白頭吟二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3be2078f-0534-4264-89fb-244a8da74e34', '相和歌辭 白頭吟', '相和歌辞 白头吟', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["請君膝上琴，彈我白頭吟。","憶昔君前嬌笑語，兩情宛轉如縈素。","宮中爲我起高樓，更開華池種芳樹。","春天百草秋始衰，棄我不待白頭時。","羅襦玉珥色未暗，今朝已道不相宜。","揚州青銅作明鏡，暗中持照不見影。","人心回互自無窮，眼前好惡那能定。","君恩已去若再返，菖蒲花生月長滿。"]', '["請君膝上琴，彈我白头吟。","憶昔君前嬌笑語，兩情宛轉如縈素。","宮中爲我起高楼，更开华池種芳樹。","春天百草秋始衰，棄我不待白头时。","羅襦玉珥色未暗，今朝已道不相宜。","揚州青銅作明镜，暗中持照不见影。","人心回互自無窮，眼前好惡那能定。","君恩已去若再返，菖蒲花生月长满。"]', '诗', 'shi', '', NULL, '相和歌辭 白頭吟 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78a9e1c4-c843-4e03-88cc-b440584c700a', '相和歌辭 反白頭吟', '相和歌辞 反白头吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["炎炎者烈火，營營者小蠅。","火不熱真玉，蠅不點清冰。","此苟無所受，彼莫能相仍。","乃知物性中，各有能不能。","古稱怨報死，則人有所懲。","懲淫或應可，在道未爲弘。","譬如蜩鷃徒，啾啾啅龍鵬。","宜當委之去，寥廓高飛騰。","豈能泥塵下，區區酬怨憎。","胡爲作自苦，吞悲仍撫膺。"]', '["炎炎者烈火，營營者小蠅。","火不熱真玉，蠅不点清冰。","此苟無所受，彼莫能相仍。","乃知物性中，各有能不能。","古稱怨報死，則人有所懲。","懲淫或應可，在道未爲弘。","譬如蜩鷃徒，啾啾啅龙鵬。","宜當委之去，寥廓高飞腾。","豈能泥塵下，區區酬怨憎。","胡爲作自苦，吞悲仍撫膺。"]', '诗', 'shi', '', NULL, '相和歌辭 反白頭吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e627ebd-0fd3-4669-a32c-5d108d5d4ce6', '相和歌辭 決絕[詞]三首 一', '相和歌辞 決絕[词]三首 一', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["乍可爲天上牽牛織女星，不願爲庭前紅槿枝。","七月七日一相見，故心終不移。","那能朝開暮飛去，一任東西南北吹。","分不兩相守，恨不兩相思。","對面且如此，背面當何知。","春風撩亂伯勞語，此時拋去時。","握手苦相問，竟不言後期。","君情既決絕，妾意已參差。","借如死生別，安得長苦悲。"]', '["乍可爲天上牽牛织女星，不願爲庭前紅槿枝。","七月七日一相见，故心終不移。","那能朝开暮飞去，一任东西南北吹。","分不兩相守，恨不兩相思。","对面且如此，背面當何知。","春风撩亂伯勞語，此时拋去时。","握手苦相问，竟不言後期。","君情既決絕，妾意已參差。","借如死生別，安得长苦悲。"]', '诗', 'shi', '', NULL, '相和歌辭 決絕[詞]三首 一 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fcf1381-8137-43b2-8863-bc92e00f50c8', '相和歌辭 決絕[詞]三首 二', '相和歌辞 決絕[词]三首 二', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["噫春冰之將泮，何余懷之獨結。","有美一人，於焉曠絕。","一日不見，比一日於三年，況三年之曠別。","水得風兮小而已波，筍在苞兮高不見節。","矧桃李之當春，競衆人之攀折。","我自顧悠悠而若雲，又安能保君皓皓之如雪。","感破鏡之分明，覩淚痕之餘血。","幸他人之既不我先，又安能使他人之終不我奪。","已焉哉！織女別黃姑，一年一度暫相見，彼此隔河何事無。"]', '["噫春冰之將泮，何余懷之独結。","有美一人，於焉曠絕。","一日不见，比一日於三年，況三年之曠別。","水得风兮小而已波，筍在苞兮高不见節。","矧桃李之當春，競衆人之攀折。","我自顧悠悠而若云，又安能保君皓皓之如雪。","感破镜之分明，覩泪痕之餘血。","幸他人之既不我先，又安能使他人之終不我奪。","已焉哉！织女別黄姑，一年一度暫相见，彼此隔河何事無。"]', '诗', 'shi', '', NULL, '相和歌辭 決絕[詞]三首 二 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dbf0b9d-bdb3-4ee1-9bbf-005087cefe54', '相和歌辭 決絕[詞]三首 三', '相和歌辞 決絕[词]三首 三', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["夜夜相抱眠，幽懷尚沈結。","那堪一年事，長遣一宵說。","但感久相思，何暇暫相悅。","虹橋薄夜成，龍駕侵晨列。","生憎野鵲往遲回，死恨天雞識時節。","曙色漸曈曨，華星次明滅。","一去又一年，一年何時徹。","有此迢遰期，不如生死別。"]', '["夜夜相抱眠，幽懷尚沈結。","那堪一年事，长遣一宵说。","但感久相思，何暇暫相悅。","虹橋薄夜成，龙駕侵晨列。","生憎野鵲往遲回，死恨天雞識时節。","曙色漸曈曨，华星次明滅。","一去又一年，一年何时徹。","有此迢遰期，不如生死別。"]', '诗', 'shi', '', NULL, '相和歌辭 決絕[詞]三首 三 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('990af3fd-2638-434e-aaaf-9eeffa6554c0', '相和歌辭 梁甫吟', '相和歌辞 梁甫吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長嘯梁甫吟，何時見陽春？","君不見朝歌屠叟辭棘津，八十西來釣渭濱。","寧羞白髮照淥水，逢時吐氣思經綸。","廣張三千六百鈞，風雅暗與文王親。","大賢虎變愚不測，當年頗似尋常人。","君不見高陽酒徒起草中，長揖山東隆準公。","入門不拜騁雄辨，兩女輟洗來趨風。","東下齊城七十二，指麾楚漢如旋蓬。","狂生落拓尚如此，何況壯士當羣雄。","我欲攀龍見明主，雷公砰訇震天鼓。","帝旁投壺多玉女，三時大笑開電光。","倏爍晦冥起風雨，閶闔九門不可通。","以額叩關閽者怒，白日不照吾精誠。","杞國無事憂天傾，䝟貐磨牙競人肉。","騶虞不折生草莖，手接飛猱搏彫虎。","側足焦原未言苦，智者可卷愚者豪。","世人見我輕鴻毛，力排南山三壯士，齊相殺之費二桃。","吳楚弄兵無劇孟，亞夫咍爾爲徒勞。","梁父吟，梁父吟，聲正悲。","張公兩龍劒，神物合有時。","風雲感會起屠釣，大人𡸣屼當安之。"]', '["长嘯梁甫吟，何时见陽春？","君不见朝歌屠叟辞棘津，八十西来釣渭濱。","寧羞白髮照淥水，逢时吐氣思經綸。","廣張三千六百鈞，风雅暗與文王親。","大賢虎变愚不測，當年頗似尋常人。","君不见高陽酒徒起草中，长揖山东隆準公。","入门不拜騁雄辨，兩女輟洗来趨风。","东下齊城七十二，指麾楚漢如旋蓬。","狂生落拓尚如此，何況壯士當羣雄。","我欲攀龙见明主，雷公砰訇震天鼓。","帝旁投壺多玉女，三时大笑开電光。","倏爍晦冥起风雨，閶闔九门不可通。","以額叩关閽者怒，白日不照吾精誠。","杞国無事憂天傾，䝟貐磨牙競人肉。","騶虞不折生草莖，手接飞猱搏彫虎。","側足焦原未言苦，智者可卷愚者豪。","世人见我轻鴻毛，力排南山三壯士，齊相殺之費二桃。","吳楚弄兵無劇孟，亞夫咍爾爲徒勞。","梁父吟，梁父吟，声正悲。","張公兩龙劒，神物合有时。","风云感會起屠釣，大人𡸣屼當安之。"]', '诗', 'shi', '', NULL, '相和歌辭 梁甫吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b028d90-1546-4874-9888-1c57a3f3cb2d', '相和歌辭 東武吟', '相和歌辞 东武吟', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["好古笑流俗，素聞賢達風。","方希佐明主，長揖辭成功。","白日在高天，回光燭微躬。","恭承鳳皇詔，歘起雲蘿中。","清切紫霄迥，優游丹禁通。","君王賜顏色，聲價凌煙虹。","乘輿擁翠蓋，扈從金城東。","寶馬麗絕景，錦衣入新豐。","倚巖望松雪，對酒鳴絲桐。","因學揚子雲，獻賦甘泉宮。","天書美片善，清芬播無窮。","歸來入咸陽，談笑皆王公。","一朝去金馬，飄落成飛蓬。","賓友日疎散，玉尊亦已空。","才力猶可倚，不慙世上雄。","閑作東武吟，曲盡情未終。","書此謝知己，吾尋黃綺翁。"]', '["好古笑流俗，素闻賢達风。","方希佐明主，长揖辞成功。","白日在高天，回光燭微躬。","恭承鳳皇詔，歘起云蘿中。","清切紫霄迥，優游丹禁通。","君王賜顏色，声價凌煙虹。","乘輿擁翠蓋，扈從金城东。","寶马丽絕景，錦衣入新豐。","倚巖望松雪，对酒鳴絲桐。","因学揚子云，獻賦甘泉宮。","天书美片善，清芬播無窮。","归来入咸陽，談笑皆王公。","一朝去金马，飄落成飞蓬。","賓友日疎散，玉尊亦已空。","才力猶可倚，不慙世上雄。","闲作东武吟，曲尽情未終。","书此謝知己，吾尋黄綺翁。"]', '诗', 'shi', '', NULL, '相和歌辭 東武吟 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4de9d2cb-62f8-49b2-9914-17c1060ec6ba', '相和歌辭 怨詩二首 一', '相和歌辞 怨诗二首 一', 'af2ae106-22ea-433d-b512-655de7861770', '唐', '["日晚梧桐落，微寒入禁垣。","月懸三雀觀，霜度萬秋門。","豔舞矜新寵，愁容泣舊恩。","不堪深殿裏，簾外欲黃昏。"]', '["日晚梧桐落，微寒入禁垣。","月懸三雀观，霜度万秋门。","豔舞矜新寵，愁容泣旧恩。","不堪深殿裏，簾外欲黄昏。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩二首 一 薛奇童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8dc78e8-eca3-43fe-8957-c9c634f4b747', '相和歌辭 怨詩二首 二', '相和歌辞 怨诗二首 二', 'af2ae106-22ea-433d-b512-655de7861770', '唐', '["禁苑春風起，流鶯繞合歡。","玉窗通日氣，珠箔卷輕寒。","楊葉垂金砌，梨花入井闌。","君王好長袖，新作舞衣寬。"]', '["禁苑春风起，流鶯繞合歡。","玉窗通日氣，珠箔卷轻寒。","楊葉垂金砌，梨花入井闌。","君王好长袖，新作舞衣寬。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩二首 二 薛奇童 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be665b74-bf5e-484d-b86b-85764fe4ee85', '相和歌辭 怨詩', '相和歌辞 怨诗', '843d004a-9515-4100-97cb-22de96430ccf', '唐', '["去年離別雁初歸，今夜裁縫螢已飛。","征客近來音信斷，不知何處寄寒衣。"]', '["去年離別雁初归，今夜裁縫螢已飞。","征客近来音信斷，不知何处寄寒衣。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩 張汯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('093f8db9-b5a9-40b5-86ee-703ac046b675', '相和歌辭 怨詩', '相和歌辞 怨诗', 'b8f89ac8-d458-465d-bb53-b181ddf7a078', '唐', '["玉關芳信斷，蘭閨錦字新。","愁來好自抑，念切已含嚬。","虛牖風驚夢，空牀月厭人。","歸期儻可促，勿度柳園春。"]', '["玉关芳信斷，蘭閨錦字新。","愁来好自抑，念切已含嚬。","虛牖风驚梦，空牀月厭人。","归期儻可促，勿度柳园春。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩 劉元濟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9709148e-d077-4032-90b4-f561a7e27ea1', '相和歌辭 怨詩三首 一', '相和歌辞 怨诗三首 一', 'bc3ce6dd-5bcf-4826-a95e-9852e09fc0a6', '唐', '["羅敷初總髻，蕙芳正嬌小。","月落始歸船，春眠恆著曉。"]', '["羅敷初總髻，蕙芳正嬌小。","月落始归船，春眠恆著晓。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩三首 一 李暇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d5a1080-bad4-49d8-b2cf-d9e2f6a3308c', '相和歌辭 怨詩三首 二', '相和歌辞 怨诗三首 二', 'bc3ce6dd-5bcf-4826-a95e-9852e09fc0a6', '唐', '["何處期郎遊？小苑花臺間。","相憶不可見，且復乘月還。"]', '["何处期郎游？小苑花台间。","相憶不可见，且复乘月還。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩三首 二 李暇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f9a61da1-8c80-4698-b345-391cff7b3ac4', '相和歌辭 怨詩三首 三', '相和歌辞 怨诗三首 三', 'bc3ce6dd-5bcf-4826-a95e-9852e09fc0a6', '唐', '["別來花照路，別後露垂葉。","歌舞須及時，如何坐悲妾。"]', '["別来花照路，別後露垂葉。","歌舞須及时，如何坐悲妾。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩三首 三 李暇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('162cbb9f-bbde-41a4-95b0-0be89ecabc99', '相和歌辭 怨詩二首 一', '相和歌辞 怨诗二首 一', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["樓前桃李疎，池上芙蓉落。","織錦猶未成，蟲聲入羅幕。"]', '["楼前桃李疎，池上芙蓉落。","织錦猶未成，蟲声入羅幕。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩二首 一 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b52a6b7c-7890-4224-aa1a-cc9cab9b2e34', '相和歌辭 怨詩二首 二', '相和歌辞 怨诗二首 二', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["妾有羅衣裳，秦王在時作。","爲舞春風多，秋來不堪著。"]', '["妾有羅衣裳，秦王在时作。","爲舞春风多，秋来不堪著。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩二首 二 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('474eec78-7561-4f35-b428-1a437bb4adc6', '相和歌辭 怨詩', '相和歌辞 怨诗', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["試妾與君淚，兩處滴池水。","看取芙蓉花，今年爲誰死。"]', '["試妾與君泪，兩处滴池水。","看取芙蓉花，今年爲誰死。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ecae1f7-266b-4e80-878c-8b3d51618347', '相和歌辭 怨詩', '相和歌辞 怨诗', '498e925c-6e0a-4c76-aa89-3769e8e4d719', '唐', '["君莫嫌醜婦，醜婦死守貞。","山頭一怪石，長作望夫名。","鳥有竝翼飛，獸有比肩行。","丈夫不立義，豈如鳥獸情。"]', '["君莫嫌醜婦，醜婦死守貞。","山头一怪石，长作望夫名。","鸟有竝翼飞，獸有比肩行。","丈夫不立義，豈如鸟獸情。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩 劉义 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('863f8e58-3a82-40a7-927d-f1679f50c1ab', '相和歌辭 怨詩', '相和歌辞 怨诗', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["女蘿寄松柏，綠蔓花緜緜。","三五定君婚，結髮早移天。","肅肅羊雁禮，泠泠琴瑟篇。","恭承采蘩祀，敢效同居賢。","皎日不留景，良時如逝川。","秋心還遺愛，春貌無歸妍。","翠袖洗朱粉，碧階對綺錢。","新人易如玉，廢瑟難爲弦。","寄羨蕣華木，榮名香閣前。","豈無搖落苦，貴與根蒂連。","希君舊光景，照妾薄暮年。"]', '["女蘿寄松柏，綠蔓花緜緜。","三五定君婚，結髮早移天。","肅肅羊雁禮，泠泠琴瑟篇。","恭承采蘩祀，敢效同居賢。","皎日不留景，良时如逝川。","秋心還遺愛，春貌無归妍。","翠袖洗朱粉，碧階对綺錢。","新人易如玉，廢瑟难爲弦。","寄羨蕣华木，榮名香閣前。","豈無搖落苦，貴與根蒂連。","希君旧光景，照妾薄暮年。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01188e4a-475f-42c3-b021-80e71dec225e', '相和歌辭 怨詩', '相和歌辞 怨诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["奪寵心那慣，尋思倚殿門。","不知移舊愛，何處作新恩。"]', '["奪寵心那慣，尋思倚殿门。","不知移旧愛，何处作新恩。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30ae2659-78b4-43d7-abfe-a64810398af9', '相和歌辭 怨詩二首 一', '相和歌辞 怨诗二首 一', 'dca489cf-255b-4489-9ae1-813e601abd78', '唐', '["春水悠悠春水綠，對此思君淚相續。","羞將離恨向東風，理盡秦箏不成曲。"]', '["春水悠悠春水綠，对此思君泪相續。","羞將離恨向东风，理尽秦箏不成曲。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩二首 一 姚氏月華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf95c800-adcc-4719-9d39-efffa1c48448', '相和歌辭 怨詩二首 二', '相和歌辞 怨诗二首 二', 'dca489cf-255b-4489-9ae1-813e601abd78', '唐', '["與君形影分胡越，玉枕終年對離別。","登臺北望煙雨深，回身泣向寥天月。"]', '["與君形影分胡越，玉枕終年对離別。","登台北望煙雨深，回身泣向寥天月。"]', '诗', 'shi', '', NULL, '相和歌辭 怨詩二首 二 姚氏月華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4721fda8-9013-4d52-98c0-47d848cf2596', '相和歌辭 怨歌行', '相和歌辞 怨歌行', 'd49f99f5-9103-47f4-9679-5afe351ebd51', '唐', '["紫殿秋風冷，彫甍白日沈。","裁紈悽斷曲，織素別離心。","掖庭羞改畫，長門不惜金。","寵移恩稍薄，情疎恨轉深。","香銷翠羽帳，弦斷鳳皇琴。","鏡前紅粉歇，階上綠苔侵。","誰言掩歌扇，飜作白頭吟。"]', '["紫殿秋风冷，彫甍白日沈。","裁紈悽斷曲，织素別離心。","掖庭羞改畫，长门不惜金。","寵移恩稍薄，情疎恨轉深。","香銷翠羽帳，弦斷鳳皇琴。","镜前紅粉歇，階上綠苔侵。","誰言掩歌扇，飜作白头吟。"]', '诗', 'shi', '', NULL, '相和歌辭 怨歌行 虞世南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f0612fa-9e28-431f-8a02-b511a6d6cc47', '相和歌辭 怨歌行', '相和歌辞 怨歌行', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["十五入漢宮，花顏笑春紅。","君王選玉色，侍寢金屏中。","薦枕嬌夕月，卷衣戀春風。","寧知趙飛燕，奪寵恨無窮。","沈憂能傷人，綠鬢成霜蓬。","一朝不得意，世事徒爲空。","鷫鸘換美酒，舞衣罷雕籠。","寒苦不忍言，爲君奏絲桐。","腸斷弦亦絕，悲心夜忡忡。"]', '["十五入漢宮，花顏笑春紅。","君王選玉色，侍寢金屏中。","薦枕嬌夕月，卷衣戀春风。","寧知趙飞燕，奪寵恨無窮。","沈憂能傷人，綠鬢成霜蓬。","一朝不得意，世事徒爲空。","鷫鸘換美酒，舞衣罷雕籠。","寒苦不忍言，爲君奏絲桐。","腸斷弦亦絕，悲心夜忡忡。"]', '诗', 'shi', '', NULL, '相和歌辭 怨歌行 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0f319bd-70b8-4e2b-ad82-9ed3d84ed7b0', '相和歌辭 怨歌行', '相和歌辞 怨歌行', '01725bde-ecd3-4409-a7a8-172412f7fd7c', '唐', '["城南有怨婦，含怨倚蘭叢。","自謂二八時，歌舞入漢宮。","皇恩弄幸玉堂中，綠陌黃花催夜酒。","錦衣羅袂逐春風，建章西宮煥若神。","燕趙美女二千人，君王厭德不忘新。","況羣豔冶紛來陳，是時別君不再見。","三十三春長信殿，長信重門晝掩關。","清房曉帳幽且閑，綺窗蟲網氛塵色。","文軒鶯對桃李顏，天王貴宮不貯老。","浩然淚隕今來還，自憐轉晚暮。","試逐佳遊芳草路，小腰麗女奪人奇。","金鞍少年曾不顧，歸來誰爲夫。","請謝西家婦，莫辭先醉解羅襦。"]', '["城南有怨婦，含怨倚蘭叢。","自謂二八时，歌舞入漢宮。","皇恩弄幸玉堂中，綠陌黄花催夜酒。","錦衣羅袂逐春风，建章西宮煥若神。","燕趙美女二千人，君王厭德不忘新。","況羣豔冶紛来陳，是时別君不再见。","三十三春长信殿，长信重门晝掩关。","清房晓帳幽且闲，綺窗蟲網氛塵色。","文軒鶯对桃李顏，天王貴宮不貯老。","浩然泪隕今来還，自怜轉晚暮。","試逐佳游芳草路，小腰丽女奪人奇。","金鞍少年曾不顧，归来誰爲夫。","請謝西家婦，莫辞先醉解羅襦。"]', '诗', 'shi', '', NULL, '相和歌辭 怨歌行 吳少微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50558d78-9650-4a09-8f68-44beb2b2ede9', '相和歌辭 明月照高樓', '相和歌辞 明月照高楼', '599809db-834b-4917-8831-3b919c8a1737', '唐', '["朗月何高高，樓中簾影寒。","一婦獨含歎，四坐誰成歡。","時節屢已移，遊旅杳不還。","滄溟倘未涸，妾淚終不乾。","君若無定雲，妾若不動山。","雲行出山易，山逐雲去難。","願爲邊塞塵，因風委君顏。","君顏良洗多，盪妾濁水間。"]', '["朗月何高高，楼中簾影寒。","一婦独含歎，四坐誰成歡。","时節屢已移，游旅杳不還。","滄溟倘未涸，妾泪終不乾。","君若無定云，妾若不动山。","云行出山易，山逐云去难。","願爲邊塞塵，因风委君顏。","君顏良洗多，盪妾濁水间。"]', '诗', 'shi', '', NULL, '相和歌辭 明月照高樓 雍陶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf091288-2149-4e06-8619-261985ad8fca', '相和歌辭 長門怨', '相和歌辞 长门怨', 'f4b485ca-1544-40be-a2bd-c0c4f6e9c93b', '唐', '["舊愛柏梁臺，新寵昭陽殿。","守分辭方輦，含情泣團扇。","一朝歌舞榮，夙昔詩書賤。","頹恩誠已矣，覆水難重薦。"]', '["旧愛柏梁台，新寵昭陽殿。","守分辞方輦，含情泣團扇。","一朝歌舞榮，夙昔诗书賤。","頹恩誠已矣，覆水难重薦。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 徐賢妃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('899aec8f-0f35-4125-8580-13171f22bca6', '相和歌辭 長門怨', '相和歌辞 长门怨', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["月皎風泠泠，長門次掖庭。","玉階聞墜葉，羅幌見飛螢。","清露凝珠綴，流塵下翠屏。","妾心君未察，秋歎劇繁星。"]', '["月皎风泠泠，长门次掖庭。","玉階闻墜葉，羅幌见飞螢。","清露凝珠綴，流塵下翠屏。","妾心君未察，秋歎劇繁星。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af7bc37f-eb0a-400a-872c-d30dbe966713', '相和歌辭 長門怨', '相和歌辞 长门怨', '01725bde-ecd3-4409-a7a8-172412f7fd7c', '唐', '["月出映曾城，孤圜上太清。","君王春愛歇，枕席涼風生。","怨咽不能寢，踟躕步前楹。","空階白露色，百草寒蟲鳴。","念昔金房裏，猶嫌玉座輕。","如何嬌所誤，長夜泣恩情。"]', '["月出映曾城，孤圜上太清。","君王春愛歇，枕席涼风生。","怨咽不能寢，踟躕步前楹。","空階白露色，百草寒蟲鳴。","念昔金房裏，猶嫌玉座轻。","如何嬌所誤，长夜泣恩情。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 吳少微 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7df4c1ad-5232-4df5-98c1-05f46dfc7d87', '相和歌辭 長門怨', '相和歌辞 长门怨', 'b4b34d02-1fae-4079-8d22-e6d7babfc19c', '唐', '["長門落景盡，洞房秋月明。","玉階草路積，金屋網塵生。","妾妬今應改，君恩昔未平。"]', '["长门落景尽，洞房秋月明。","玉階草路積，金屋網塵生。","妾妬今應改，君恩昔未平。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 張脩之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6670b5c-674e-499d-ac03-6e90a067ed88', '相和歌辭 長門怨', '相和歌辞 长门怨', 'aae75949-588d-4fb8-8a52-286732c05f63', '唐', '["自閉長門經幾秋，羅衣溼盡淚還流。","一種蛾眉明月夜，南宮歌管北宮愁。"]', '["自閉长门經幾秋，羅衣溼尽泪還流。","一種蛾眉明月夜，南宮歌管北宮愁。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 裴交泰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('edc3b878-d8ef-4855-9d99-0d6b787d5c02', '相和歌辭 長門怨', '相和歌辞 长门怨', '358ca4f3-fd77-4991-b503-2fbe345f3c4f', '唐', '["宮殿沈沈月欲分，昭陽更漏不堪聞。","珊瑚枕上千行淚，不是思君是恨君。"]', '["宮殿沈沈月欲分，昭陽更漏不堪闻。","珊瑚枕上千行泪，不是思君是恨君。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 劉皁 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('061171ce-6d25-4e81-9d19-89a2b916416a', '相和歌辭 長門怨', '相和歌辞 长门怨', 'a401176c-92fa-4cbb-bfb6-3b739195901a', '唐', '["早知君愛歇，本自無縈妬。","誰使恩情深，今來反相誤。","愁眠羅帳曉，泣坐金閨暮。","獨有夢中魂，猶言意如故。"]', '["早知君愛歇，本自無縈妬。","誰使恩情深，今来反相誤。","愁眠羅帳晓，泣坐金閨暮。","独有梦中魂，猶言意如故。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 袁暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccbc1933-eaa7-45ab-a8b9-92c5d745aacc', '相和歌辭 長門怨', '相和歌辞 长门怨', 'ea8f669d-f0ff-4fd9-9568-f9f6c1d05e46', '唐', '["獨坐爐邊結夜愁，暫時恩去亦難留。","手持金箸垂紅淚，亂撥寒灰不舉頭。"]', '["独坐爐邊結夜愁，暫时恩去亦难留。","手持金箸垂紅泪，亂撥寒灰不舉头。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 劉言史 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4adbd576-58b6-4d4a-9242-475231293909', '相和歌辭 長門怨二首 一', '相和歌辞 长门怨二首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["天回北斗挂西樓，金屋無人螢火流。","月光欲到長門殿，別作深宮一段愁。"]', '["天回北斗挂西楼，金屋無人螢火流。","月光欲到长门殿，別作深宮一段愁。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨二首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('533fc8a0-b5f9-422b-9267-ecab0ad01140', '相和歌辭 長門怨二首 二', '相和歌辞 长门怨二首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["桂殿長愁不記春，黃金四屋起秋塵。","夜懸明鏡青天上，獨照長門宮裏人。"]', '["桂殿长愁不記春，黄金四屋起秋塵。","夜懸明镜青天上，独照长门宮裏人。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨二首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('841631b4-7f64-439a-9f9d-487086aa2c12', '相和歌辭 長門怨', '相和歌辞 长门怨', 'a83506b5-9dc2-4e8a-8c90-bd1ee1ede8ac', '唐', '["弱體鴛鴦薦，啼妝翡翠衾。","鴉鳴秋殿曉，人靜禁門深。","每憶椒房寵，那堪永巷陰。","日驚羅帶緩，非復舊來心。"]', '["弱體鴛鴦薦，啼妝翡翠衾。","鴉鳴秋殿晓，人静禁门深。","每憶椒房寵，那堪永巷陰。","日驚羅带緩，非复旧来心。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 李華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd5b1644-b2ea-4d34-9a5a-26c07dc2f260', '相和歌辭 長門怨', '相和歌辞 长门怨', '8f550fa6-3a7e-4616-9d9b-980185c85ef7', '唐', '["君王嫌妾妬，閉妾在長門。","舞袖垂新寵，愁眉結舊恩。","綠錢生履跡，紅粉溼啼痕。","羞被桃花笑，看春獨不言。"]', '["君王嫌妾妬，閉妾在长门。","舞袖垂新寵，愁眉結旧恩。","綠錢生履跡，紅粉溼啼痕。","羞被桃花笑，看春独不言。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 岑參 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8f3462b-2c7d-42da-af77-e35b4464099d', '相和歌辭 長門怨', '相和歌辞 长门怨', '31bf2bf2-d924-4786-a1d0-29b816e34c36', '唐', '["煢煢孤思逼，寂寂長門夕。","妾妬亦非深，君恩那不惜。","攜琴就玉階，調悲聲未諧。","將心託明月，流影入君懷。"]', '["煢煢孤思逼，寂寂长门夕。","妾妬亦非深，君恩那不惜。","携琴就玉階，調悲声未諧。","將心託明月，流影入君懷。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 齊澣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fb02922-4117-43c0-9ef1-e71f845228cf', '相和歌辭 長門怨', '相和歌辞 长门怨', '396ab354-2295-408d-a8fe-b577e163956f', '唐', '["何事長門閉，珠簾只自垂。","月移深殿早，春向後宮遲。","蕙草生閑地，梨花發舊枝。","芳菲自恩幸，看却被風吹。"]', '["何事长门閉，珠簾只自垂。","月移深殿早，春向後宮遲。","蕙草生闲地，梨花發旧枝。","芳菲自恩幸，看却被风吹。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 劉長卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c5bf4fe-7668-44af-b43a-e4e43d84ac6e', '相和歌辭 長門怨', '相和歌辞 长门怨', 'd031d511-00fb-47fd-8345-864309b121e2', '唐', '["春風日日閉長門，搖蕩春心自夢魂。","若遣花開只笑妾，不如桃李正無言。"]', '["春风日日閉长门，搖蕩春心自梦魂。","若遣花开只笑妾，不如桃李正無言。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 僧皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d25f355-cbc3-4f18-ab8f-f605472ba32d', '相和歌辭 長門怨', '相和歌辞 长门怨', '770ff328-161f-4754-ba6c-9875b0ca8f45', '唐', '["空宮古廊殿，寒月照斜暉。","臥聽未央曲，滿箱歌舞衣。"]', '["空宮古廊殿，寒月照斜暉。","臥听未央曲，满箱歌舞衣。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 盧綸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2a631cf-0c02-46f1-9bfb-8cce798979c8', '相和歌辭 長門怨', '相和歌辞 长门怨', '0163e7a0-df79-4e69-bfe9-2f3aee0f68cc', '唐', '["自憶專房寵，曾居第一流。","移恩向何處？暫妬不容收。","夜久絲管絕，月明宮殿秋。","空將舊時意，長望鳳皇樓。"]', '["自憶專房寵，曾居第一流。","移恩向何处？暫妬不容收。","夜久絲管絕，月明宮殿秋。","空將旧时意，长望鳳皇楼。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 戴叔倫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d400f2fa-d0ca-4817-9216-6d3c606b7430', '相和歌辭 長門怨', '相和歌辞 长门怨', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["御泉長繞鳳皇樓，只是恩波別處流。","閑揲舞衣歸未得，夜來砧杵六宮秋。"]', '["御泉长繞鳳皇楼，只是恩波別处流。","闲揲舞衣归未得，夜来砧杵六宮秋。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef189d28-9750-49f2-8813-f70bee5e45b2', '相和歌辭 長門怨 一', '相和歌辞 长门怨 一', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["天上何勞萬古春，君前誰是百年人。","魂銷尚媿金爐燼，思起猶慙玉輦塵。","煙翠薄情攀不得，星芒浮豔采無因。","可憐明鏡來相向，何似恩光朝夕新。"]', '["天上何勞万古春，君前誰是百年人。","魂銷尚媿金爐燼，思起猶慙玉輦塵。","煙翠薄情攀不得，星芒浮豔采無因。","可怜明镜来相向，何似恩光朝夕新。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 一 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bcef096-9150-4d38-8a92-d2443de404d3', '相和歌辭 長門怨 二', '相和歌辞 长门怨 二', '9ef44ab6-ad91-45a6-8d7d-a648210bc609', '唐', '["天上鳳皇休寄夢，人間鸚鵡舊堪悲。","平生心緒無人識，一隻金梭萬丈絲。"]', '["天上鳳皇休寄梦，人间鸚鵡旧堪悲。","平生心緒無人識，一隻金梭万丈絲。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 二 高蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8da65d04-e82f-479d-9759-0b445caeff1b', '相和歌辭 長門怨', '相和歌辞 长门怨', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["日映宮牆柳色寒，笙歌遙指碧雲端。","珠鉛滴盡無心語，彊把花枝冷笑看。"]', '["日映宮牆柳色寒，笙歌遙指碧云端。","珠鉛滴尽無心語，彊把花枝冷笑看。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79160aff-5f8e-4949-b3cd-269b8a43f8fd', '相和歌辭 長門怨二首 一', '相和歌辞 长门怨二首 一', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["閑把羅衣泣鳳皇，先朝曾教舞霓裳。","春來却羨庭花落，得逐晴風出禁牆。"]', '["闲把羅衣泣鳳皇，先朝曾教舞霓裳。","春来却羨庭花落，得逐晴风出禁牆。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨二首 一 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28f8b6e2-2c56-4a12-8195-07e83798fc80', '相和歌辭 長門怨二首 二', '相和歌辞 长门怨二首 二', 'fc4490cb-c1d4-431f-b018-2ebbceabf3c3', '唐', '["流水君恩共不回，杏花爭忍埽成堆。","殘春未必多煙雨，淚滴閑階長綠苔。"]', '["流水君恩共不回，杏花爭忍埽成堆。","殘春未必多煙雨，泪滴闲階长綠苔。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨二首 二 鄭谷 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5abcffa-ec7a-4422-9d49-09a96d0bcda4', '相和歌辭 長門怨二首 一', '相和歌辞 长门怨二首 一', 'e911400c-c45f-426f-a218-fc18fbb495d1', '唐', '["雨滴梧桐秋夜長，愁心和雨到昭陽。","淚痕不學君恩斷，拭却千行更萬行。"]', '["雨滴梧桐秋夜长，愁心和雨到昭陽。","泪痕不学君恩斷，拭却千行更万行。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨二首 一 劉氏媛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e55d71d3-785b-4f4a-9086-765c4641f5ee', '相和歌辭 長門怨二首 二', '相和歌辞 长门怨二首 二', 'e911400c-c45f-426f-a218-fc18fbb495d1', '唐', '["學畫蛾眉獨出羣，當時人道便承恩。","經年不見君王面，花落黃昏空掩門。"]', '["学畫蛾眉独出羣，當时人道便承恩。","經年不见君王面，花落黄昏空掩门。"]', '诗', 'shi', '', NULL, '相和歌辭 長門怨二首 二 劉氏媛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b3f2fc0-a992-4e27-8404-005465c98f8d', '相和歌辭 阿嬌怨', '相和歌辞 阿嬌怨', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["望見葳蕤舉翠華，試開金屋埽庭花。","須臾宮女傳來信，云幸平陽公主家。"]', '["望见葳蕤舉翠华，試开金屋埽庭花。","須臾宮女傳来信，云幸平陽公主家。"]', '诗', 'shi', '', NULL, '相和歌辭 阿嬌怨 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34ef326b-c8ec-4feb-bc66-24611dfdf939', '相和歌辭 班倢伃', '相和歌辞 班倢伃', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["君恩忽斷絕，妾思終未央。","巾櫛不可見，枕席空餘香。","窗暗網羅白，階秋苔蘚黃。","應門寂已閉，流涕向昭陽。"]', '["君恩忽斷絕，妾思終未央。","巾櫛不可见，枕席空餘香。","窗暗網羅白，階秋苔蘚黄。","應门寂已閉，流涕向昭陽。"]', '诗', 'shi', '', NULL, '相和歌辭 班倢伃 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('307ff50e-f4b5-453e-adb6-fd921432365e', '相和歌辭 班倢伃', '相和歌辞 班倢伃', '09e6d1c2-93a9-4b77-a2df-3ca89f754eb8', '唐', '["賤妾如桃李，君王若歲時。","秋風一已勁，搖落不勝悲。","寂寂蒼苔滿，沈沈綠草滋。","榮華非此日，指輦競何辭。"]', '["賤妾如桃李，君王若歲时。","秋风一已勁，搖落不勝悲。","寂寂蒼苔满，沈沈綠草滋。","榮华非此日，指輦競何辞。"]', '诗', 'shi', '', NULL, '相和歌辭 班倢伃 嚴識玄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ab180d2-87ce-418a-afdf-3a473f42a7d4', '相和歌辭 班倢伃三首 一', '相和歌辞 班倢伃三首 一', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["玉窗螢影度，金殿人聲絕。","秋夜守羅幃，孤燈耿不滅。"]', '["玉窗螢影度，金殿人声絕。","秋夜守羅幃，孤灯耿不滅。"]', '诗', 'shi', '', NULL, '相和歌辭 班倢伃三首 一 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('704cd99c-171d-4b5f-bbdc-0d21d559d83d', '相和歌辭 班倢伃三首 二', '相和歌辞 班倢伃三首 二', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["宮殿生秋草，君王恩幸疎。","那堪聞鳳吹，門外度金輿。"]', '["宮殿生秋草，君王恩幸疎。","那堪闻鳳吹，门外度金輿。"]', '诗', 'shi', '', NULL, '相和歌辭 班倢伃三首 二 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2bbf8f35-26a3-4cbf-aa3c-4ccab73da8b0', '相和歌辭 班倢伃三首 三', '相和歌辞 班倢伃三首 三', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["怪來妝閣閉，朝下不相迎。","總向春園裏，花間語笑聲。"]', '["怪来妝閣閉，朝下不相迎。","總向春园裏，花间語笑声。"]', '诗', 'shi', '', NULL, '相和歌辭 班倢伃三首 三 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d52e48bb-b264-4c1e-b75d-933b99d7ab4f', '相和歌辭 倢伃怨', '相和歌辞 倢伃怨', '6dff31b1-c51d-4a3b-9a3d-4bd24d82e015', '唐', '["不分君恩斷，新妝視鏡中。","容華尚春日，嬌愛已秋風。","枕席臨窗曉，幃屏向月空。","年年後庭樹，榮落在深宮。"]', '["不分君恩斷，新妝視镜中。","容华尚春日，嬌愛已秋风。","枕席臨窗晓，幃屏向月空。","年年後庭樹，榮落在深宮。"]', '诗', 'shi', '', NULL, '相和歌辭 倢伃怨 崔湜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a35a870-6e18-4b98-8770-50bc0d64cee5', '相和歌辭 倢伃怨', '相和歌辞 倢伃怨', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["長信宮中草，年年愁處生。","故侵珠履跡，不使玉階行。"]', '["长信宮中草，年年愁处生。","故侵珠履跡，不使玉階行。"]', '诗', 'shi', '', NULL, '相和歌辭 倢伃怨 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('054d55fe-ff0b-4c2e-aba2-a6b76121d513', '相和歌辭 倢伃怨', '相和歌辞 倢伃怨', 'e5629d0c-063e-4d3d-8ad4-944b91eb4535', '唐', '["賤妾裁紈扇，初搖明月姿。","君王看舞席，坐起秋風時。","玉樹清御路，金陳翳垂絲。","昭陽無分理，愁寂任前期。"]', '["賤妾裁紈扇，初搖明月姿。","君王看舞席，坐起秋风时。","玉樹清御路，金陳翳垂絲。","昭陽無分理，愁寂任前期。"]', '诗', 'shi', '', NULL, '相和歌辭 倢伃怨 張烜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8035eb5a-81dc-407b-b63c-54025b68d700', '相和歌辭 倢伃怨', '相和歌辞 倢伃怨', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["夕殿別君王，宮深月似霜。","人愁在長信，螢出向昭陽。","露裛紅蘭死，秋彫碧樹傷。","惟當合歡扇，從此篋中藏。"]', '["夕殿別君王，宮深月似霜。","人愁在长信，螢出向昭陽。","露裛紅蘭死，秋彫碧樹傷。","惟當合歡扇，從此篋中藏。"]', '诗', 'shi', '', NULL, '相和歌辭 倢伃怨 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d39fbf99-0c3f-47e9-bbe0-1799700376c2', '相和歌辭 倢伃怨', '相和歌辞 倢伃怨', '6d5797d5-d9c8-4985-82de-f4779089067b', '唐', '["長信梨花暗欲棲，應門上籥草萋萋。","春風吹花亂撲戶，班倢車聲不至啼。"]', '["长信梨花暗欲棲，應门上籥草萋萋。","春风吹花亂撲戶，班倢车声不至啼。"]', '诗', 'shi', '', NULL, '相和歌辭 倢伃怨 王沈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fba448cb-8ff0-44cf-9ad9-c0127f7e6d7d', '相和歌辭 倢伃怨', '相和歌辞 倢伃怨', 'c8b96765-1f05-47b2-9e29-9199151c2381', '唐', '["由來詠團扇，今與值秋風。","事逐時皆往，恩無日再中。","早鴻聞上苑，寒露下深宮。","顏色年年謝，相如賦豈工。"]', '["由来詠團扇，今與值秋风。","事逐时皆往，恩無日再中。","早鴻闻上苑，寒露下深宮。","顏色年年謝，相如賦豈工。"]', '诗', 'shi', '', NULL, '相和歌辭 倢伃怨 皇甫冉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e491c2f2-7780-4ec0-92e8-8591e15c6f3b', '相和歌辭 倢伃怨', '相和歌辞 倢伃怨', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["妾貌非傾國，君王忽然寵。","南山掌上來，不及新恩重。","後宮多窈窕，日日學新聲。","一落君王耳，南山又須輕。"]', '["妾貌非傾国，君王忽然寵。","南山掌上来，不及新恩重。","後宮多窈窕，日日学新声。","一落君王耳，南山又須轻。"]', '诗', 'shi', '', NULL, '相和歌辭 倢伃怨 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f712fbf-f528-49d6-84e8-5e1f66a96c33', '相和歌辭 倢伃怨', '相和歌辞 倢伃怨', '60e56738-e921-4ab7-a3b3-c2203aac059b', '唐', '["讒謗潛來起百憂，朝承恩寵暮仇讐。","火燒白玉非因玷，霜翦紅蘭不待秋。","花落昭陽誰共輦，月明長信獨登樓。","繁華事逐東流水，團扇悲歌萬古愁。"]', '["讒謗潛来起百憂，朝承恩寵暮仇讐。","火燒白玉非因玷，霜翦紅蘭不待秋。","花落昭陽誰共輦，月明长信独登楼。","繁华事逐东流水，團扇悲歌万古愁。"]', '诗', 'shi', '', NULL, '相和歌辭 倢伃怨 翁綬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('966cfa33-295a-478b-b341-eb8270b5a2f5', '相和歌辭 倢伃怨', '相和歌辞 倢伃怨', '8d78cd6a-1fed-40cc-afc1-7b90a8fa05ea', '唐', '["君恩不可見，妾豈如秋扇。","秋扇尚有時，妾身永微賤。","莫言朝花不復落，嬌容幾奪昭陽殿。"]', '["君恩不可见，妾豈如秋扇。","秋扇尚有时，妾身永微賤。","莫言朝花不复落，嬌容幾奪昭陽殿。"]', '诗', 'shi', '', NULL, '相和歌辭 倢伃怨 劉氏雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7642e6c9-6fb2-4c6e-b7c8-800251357436', '相和歌辭 長信怨', '相和歌辞 长信怨', 'c28c3c75-e5e0-48bc-a68d-4061acac97c4', '唐', '["飛燕倚身輕，爭人巧笑名。","生君棄妾意，增妾怨君情。","日落昭陽殿，秋來長信城。","寥寥金殿裏，歌吹夜無聲。"]', '["飞燕倚身轻，爭人巧笑名。","生君棄妾意，增妾怨君情。","日落昭陽殿，秋来长信城。","寥寥金殿裏，歌吹夜無声。"]', '诗', 'shi', '', NULL, '相和歌辭 長信怨 王諲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0847590-fbf2-410e-b666-699161c54582', '相和歌辭 長信怨 一', '相和歌辞 长信怨 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["金井梧桐秋葉黃，珠簾不卷夜來霜。","金爐玉枕無顏色，臥聽南宮清漏長。"]', '["金井梧桐秋葉黄，珠簾不卷夜来霜。","金爐玉枕無顏色，臥听南宮清漏长。"]', '诗', 'shi', '', NULL, '相和歌辭 長信怨 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b6f2389-2d09-4d51-982a-e7efb35113c5', '相和歌辭 長信怨 二', '相和歌辞 长信怨 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["奉帚平明金殿開，暫將團扇共裴回。","玉顏不及寒鵶色，猶帶昭陽日影來。"]', '["奉帚平明金殿开，暫將團扇共裴回。","玉顏不及寒鵶色，猶带昭陽日影来。"]', '诗', 'shi', '', NULL, '相和歌辭 長信怨 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38bf60e6-4d6f-4e72-a646-420198611898', '相和歌辭 長信怨', '相和歌辞 长信怨', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["月皎昭陽殿，霜清長信宮。","天行乘玉輦，飛燕與君同。","更有留情處，承恩樂未窮。","誰憐團扇妾，獨坐怨秋風。"]', '["月皎昭陽殿，霜清长信宮。","天行乘玉輦，飞燕與君同。","更有留情处，承恩乐未窮。","誰怜團扇妾，独坐怨秋风。"]', '诗', 'shi', '', NULL, '相和歌辭 長信怨 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('489e9d6a-f619-4103-acde-0ba0bdfca086', '相和歌辭 蛾眉怨', '相和歌辞 蛾眉怨', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["君不見宜春苑中九華殿，飛閣連連直如髮。","白日全含朱鳥窗，流雲半入蒼龍闕。","宮中綵女夜無事，學鳳吹簫弄清越。","珠簾北卷待涼風，繡戶南開向明月。","忽聞天子憶蛾眉，寶鳳銜花揲兩螭。","傳聲走馬開金屋，夾路鳴環上玉墀。","長樂彤庭宴華寢，三千美人曳光錦。","燈前含笑更羅衣，帳裏承恩薦瑤枕。","不意君心半路迴，求仙別作望仙臺。","倉琅禁闥遙相憶，紫翠巖房晝不開。","欲向人間種桃實，先從海底覓蓬萊。","蓬萊可求不可上，孤舟縹緲知何往？","黃金作盤銅作莖，晴天白露掌中擎。","王母嫣然感君意，雲車雨斾欲相迎。","飛簾觀前空怨慕，少君何事須相誤。","一朝埋沒茂陵田，賤妾蛾眉不重顧。","宮車晚出向南山，仙衛逶迤去不還。","朝晡泣對麒麟樹，樹下蒼苔日漸斑。","人生百年夜將半，對酒長歌莫長歎。","賸知白日不可思，一死一生何足算。"]', '["君不见宜春苑中九华殿，飞閣連連直如髮。","白日全含朱鸟窗，流云半入蒼龙闕。","宮中綵女夜無事，学鳳吹簫弄清越。","珠簾北卷待涼风，繡戶南开向明月。","忽闻天子憶蛾眉，寶鳳銜花揲兩螭。","傳声走马开金屋，夾路鳴环上玉墀。","长乐彤庭宴华寢，三千美人曳光錦。","灯前含笑更羅衣，帳裏承恩薦瑤枕。","不意君心半路迴，求仙別作望仙台。","倉琅禁闥遙相憶，紫翠巖房晝不开。","欲向人间種桃實，先從海底覓蓬萊。","蓬萊可求不可上，孤舟縹緲知何往？","黄金作盤銅作莖，晴天白露掌中擎。","王母嫣然感君意，云车雨斾欲相迎。","飞簾观前空怨慕，少君何事須相誤。","一朝埋沒茂陵田，賤妾蛾眉不重顧。","宮车晚出向南山，仙衛逶迤去不還。","朝晡泣对麒麟樹，樹下蒼苔日漸斑。","人生百年夜將半，对酒长歌莫长歎。","賸知白日不可思，一死一生何足算。"]', '诗', 'shi', '', NULL, '相和歌辭 蛾眉怨 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f93545e7-747e-4d12-a6c8-e484c46b2860', '相和歌辭 玉階怨', '相和歌辞 玉階怨', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["玉階生白露，夜久侵羅襪。","却下水精簾，玲瓏望秋月。"]', '["玉階生白露，夜久侵羅襪。","却下水精簾，玲瓏望秋月。"]', '诗', 'shi', '', NULL, '相和歌辭 玉階怨 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ffcd0a6-9349-4254-b0b5-ad6ed2f25dd6', '相和歌辭 宮怨', '相和歌辞 宮怨', 'd3148703-6408-4197-b38c-1604c89122c6', '唐', '["窗前好樹名玫瑰，去年花落今年開。","無情春色尚識返，君心忽斷何時來？","憶昔妝成候仙仗，宮瑣玲瓏日新上。","拊心却笑西子嚬，掩鼻誰憂鄭姬謗。","草染文章衣下履，花黏甲乙牀前帳。","三千玉貌休自誇，十二金釵獨相向。","盛衰傾奪欲何如，嬌愛飜悲逐佞諛。","重遠豈能慙沼鵠，棄前方見泣船魚。","看籠不記熏龍腦，詠扇空曾禿鼠須。","始意類蘿新託柏，終傷如薺却甘荼。","深院獨開還獨閉，鸚鵡驚飛苔覆地。","滿箱舊賜前日衣，漬枕新垂夜來淚。","痕多開鏡照還悲，綠髻青蛾尚未衰。","莫道新縑長絕比，猶逢故劒會相追。"]', '["窗前好樹名玫瑰，去年花落今年开。","無情春色尚識返，君心忽斷何时来？","憶昔妝成候仙仗，宮瑣玲瓏日新上。","拊心却笑西子嚬，掩鼻誰憂鄭姬謗。","草染文章衣下履，花黏甲乙牀前帳。","三千玉貌休自誇，十二金釵独相向。","盛衰傾奪欲何如，嬌愛飜悲逐佞諛。","重远豈能慙沼鵠，棄前方见泣船鱼。","看籠不記熏龙腦，詠扇空曾禿鼠須。","始意類蘿新託柏，終傷如薺却甘荼。","深院独开還独閉，鸚鵡驚飞苔覆地。","满箱旧賜前日衣，漬枕新垂夜来泪。","痕多开镜照還悲，綠髻青蛾尚未衰。","莫道新縑长絕比，猶逢故劒會相追。"]', '诗', 'shi', '', NULL, '相和歌辭 宮怨 長孫佐輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e73b4b4a-718f-47c2-bedb-b8d8e213a60e', '相和歌辭 宮怨', '相和歌辞 宮怨', '44c46282-131e-4541-8222-d5f36b186cd5', '唐', '["露溼晴花宮殿香，月明歌吹在昭陽。","似將海水添宮漏，共滴長門一夜長。"]', '["露溼晴花宮殿香，月明歌吹在昭陽。","似將海水添宮漏，共滴长门一夜长。"]', '诗', 'shi', '', NULL, '相和歌辭 宮怨 李益 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08c59931-b896-4d53-9230-b6da16cdc0b1', '相和歌辭 宮怨', '相和歌辞 宮怨', 'c20bb440-18ce-45cb-a362-1db7e55c7fb5', '唐', '["妾家望江口，少年家財厚。","臨江起珠樓，不賣文君酒。","當年樂貞獨，巢燕時爲友。","父兄未許人，畏妾事姑舅。","西牆鄰宋玉，窺見妾眉宇。","一旦及天聰，恩光生戶牖。","謂言入漢宮，富貴可長久。","君王縱有情，不奈陳皇后。","誰憐頰似桃，孰知腰勝柳。","今日在長門，從來不如醜。"]', '["妾家望江口，少年家財厚。","臨江起珠楼，不賣文君酒。","當年乐貞独，巢燕时爲友。","父兄未許人，畏妾事姑舅。","西牆鄰宋玉，窺见妾眉宇。","一旦及天聰，恩光生戶牖。","謂言入漢宮，富貴可长久。","君王縱有情，不奈陳皇后。","誰怜頰似桃，孰知腰勝柳。","今日在长门，從来不如醜。"]', '诗', 'shi', '', NULL, '相和歌辭 宮怨 于濆 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3c423cd-2c34-406d-baf4-30b4dbf8f87f', '相和歌辭 宮怨 一', '相和歌辞 宮怨 一', 'd0d77d95-7ff6-457c-806c-63032d3b340e', '唐', '["塵滿金爐不炷香，黃昏獨自立重廊。","笙歌何處承恩寵？一一隨風入上陽。"]', '["塵满金爐不炷香，黄昏独自立重廊。","笙歌何处承恩寵？一一隨风入上陽。"]', '诗', 'shi', '', NULL, '相和歌辭 宮怨 一 柯崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25867091-31bf-4731-b537-79b44af26988', '相和歌辭 宮怨 二', '相和歌辞 宮怨 二', 'd0d77d95-7ff6-457c-806c-63032d3b340e', '唐', '["長門槐柳半蕭疎，玉輦沈思恨有餘。","紅淚旋銷傾國態，黃金誰爲達相如。"]', '["长门槐柳半蕭疎，玉輦沈思恨有餘。","紅泪旋銷傾国態，黄金誰爲達相如。"]', '诗', 'shi', '', NULL, '相和歌辭 宮怨 二 柯崇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('63d1777f-79b2-4d73-8c80-e1c748a28310', '相和歌辭 雜怨三首 一', '相和歌辞 杂怨三首 一', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["生在綺羅下，豈識漁陽道。","良人自戍來，夜夜夢中到。","漁陽萬里遠，近於中門限。","中門逾有時，漁陽常在眼。"]', '["生在綺羅下，豈識漁陽道。","良人自戍来，夜夜梦中到。","漁陽万里远，近於中门限。","中门逾有时，漁陽常在眼。"]', '诗', 'shi', '', NULL, '相和歌辭 雜怨三首 一 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35976b04-a1c4-4346-bc19-4f6eccd925b5', '相和歌辭 雜怨三首 二', '相和歌辞 杂怨三首 二', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["良人昨日去，明日又不還。","別時各有淚，零落青樓前。"]', '["良人昨日去，明日又不還。","別时各有泪，零落青楼前。"]', '诗', 'shi', '', NULL, '相和歌辭 雜怨三首 二 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcb16ddd-7704-45a3-bd9f-a78066c896b0', '相和歌辭 雜怨三首 三', '相和歌辞 杂怨三首 三', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["君淚濡羅巾，妾淚滴路塵。","羅巾今在手，日得隨妾身。","路塵如因飛，得上君車輪。"]', '["君泪濡羅巾，妾泪滴路塵。","羅巾今在手，日得隨妾身。","路塵如因飞，得上君车輪。"]', '诗', 'shi', '', NULL, '相和歌辭 雜怨三首 三 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f7d77aa-39ab-4b24-b32f-97f2b4fe1ecb', '相和歌辭 雜怨三首 一', '相和歌辞 杂怨三首 一', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["夭桃花清晨，遊女紅粉新。","夭桃花薄暮，遊女紅粉故。","樹有百年花，人無一定顏。","花送人老盡，人悲花自閑。"]', '["夭桃花清晨，游女紅粉新。","夭桃花薄暮，游女紅粉故。","樹有百年花，人無一定顏。","花送人老尽，人悲花自闲。"]', '诗', 'shi', '', NULL, '相和歌辭 雜怨三首 一 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3e5f871-de01-40fa-a728-8657b5831f85', '相和歌辭 雜怨三首 二', '相和歌辞 杂怨三首 二', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["貧女鏡不明，寒花日少容。","暗蛩有虛織，短線無長縫。","浪水不可照，狂夫不可從。","浪水多散影，狂夫多異蹤。","持此一生薄，空成百恨濃。"]', '["貧女镜不明，寒花日少容。","暗蛩有虛织，短線無长縫。","浪水不可照，狂夫不可從。","浪水多散影，狂夫多異蹤。","持此一生薄，空成百恨濃。"]', '诗', 'shi', '', NULL, '相和歌辭 雜怨三首 二 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c3a5c44-e3c4-4cf9-a3e2-59c22ad8a19d', '相和歌辭 雜怨三首 三', '相和歌辞 杂怨三首 三', 'd7518065-3ac9-4075-b656-c0e80365e6a7', '唐', '["憶人莫至悲，至悲空自衰。","寄人莫翦衣，翦衣未必歸。","朝爲雙蒂花，暮爲四散飛。","花落却繞樹，遊子不顧期。"]', '["憶人莫至悲，至悲空自衰。","寄人莫翦衣，翦衣未必归。","朝爲雙蒂花，暮爲四散飞。","花落却繞樹，游子不顧期。"]', '诗', 'shi', '', NULL, '相和歌辭 雜怨三首 三 孟郊 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf3e6229-1f5d-4166-9ade-19d7c3f12635', '相和歌辭 子夜春歌', '相和歌辞 子夜春歌', 'b55a0e89-16ae-4996-85e9-4822994ee656', '唐', '["春氣滿林香，春遊不可忘。","落花吹欲盡，垂柳折還長。","桑女淮南曲，金鞍塞北裝。","行行小垂手，日暮渭川陽。"]', '["春氣满林香，春游不可忘。","落花吹欲尽，垂柳折還长。","桑女淮南曲，金鞍塞北裝。","行行小垂手，日暮渭川陽。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜春歌 王翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3cb8917-c2b2-4619-9fa4-0f548a512bae', '相和歌辭 子夜冬歌', '相和歌辞 子夜冬歌', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["寂寥抱冬心，裁羅又褧褧。","夜久頻挑燈，霜寒剪刀冷。"]', '["寂寥抱冬心，裁羅又褧褧。","夜久頻挑灯，霜寒剪刀冷。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜冬歌 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df4de5cf-ac53-4137-b2be-34b163ec4d73', '相和歌辭 子夜冬歌', '相和歌辞 子夜冬歌', '6884628f-dd7f-4c3d-9461-f25d5a425c6f', '唐', '["朔風扣羣木，巖霜凋百草。","借問月中人，安得長不老。"]', '["朔风扣羣木，巖霜凋百草。","借问月中人，安得长不老。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜冬歌 薛耀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4f19aab-ff6a-40e2-b499-e43a45f7515c', '相和歌辭 子夜四時歌六首 春歌二首 一', '相和歌辞 子夜四时歌六首 春歌二首 一', '21ff9f86-72e1-4ef1-9e34-944b1639b174', '唐', '["青樓含日光，綠池起風色。","贈子同心花，殷勤此何極。"]', '["青楼含日光，綠池起风色。","贈子同心花，殷勤此何極。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌六首 春歌二首 一 郭元振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea32c92c-589f-40ce-8a57-32d133e364a8', '相和歌辭 子夜四時歌六首 春歌二首 二', '相和歌辞 子夜四时歌六首 春歌二首 二', '21ff9f86-72e1-4ef1-9e34-944b1639b174', '唐', '["陌頭楊柳枝，已被春風吹。","妾心正斷絕，君懷那得知。"]', '["陌头楊柳枝，已被春风吹。","妾心正斷絕，君懷那得知。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌六首 春歌二首 二 郭元振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4113e9d5-2bdc-4951-addb-7e182fd75cc2', '相和歌辭 子夜四時歌六首 秋歌二首 一', '相和歌辞 子夜四时歌六首 秋歌二首 一', '21ff9f86-72e1-4ef1-9e34-944b1639b174', '唐', '["邀歡空佇立，望美頻迴顧。","何時復採菱？江中密相遇。"]', '["邀歡空佇立，望美頻迴顧。","何时复採菱？江中密相遇。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌六首 秋歌二首 一 郭元振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f2d99429-122c-47c4-a117-06779c58a4f5', '相和歌辭 子夜四時歌六首 秋歌二首 二', '相和歌辞 子夜四时歌六首 秋歌二首 二', '21ff9f86-72e1-4ef1-9e34-944b1639b174', '唐', '["辟惡茱萸囊，延年菊花酒。"]', '["辟惡茱萸囊，延年菊花酒。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌六首 秋歌二首 二 郭元振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a58dc2b0-7454-4599-aa4c-a06605f39978', '相和歌辭 子夜四時歌六首 冬歌二首 一', '相和歌辞 子夜四时歌六首 冬歌二首 一', '21ff9f86-72e1-4ef1-9e34-944b1639b174', '唐', '["北極嚴氣升，南至溫風謝。","調絲競短歌，拂枕憐長夜。"]', '["北極嚴氣升，南至溫风謝。","調絲競短歌，拂枕怜长夜。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌六首 冬歌二首 一 郭元振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7201ac2c-75bd-495d-a203-339fb042959a', '相和歌辭 子夜四時歌六首 冬歌二首 二', '相和歌辞 子夜四时歌六首 冬歌二首 二', '21ff9f86-72e1-4ef1-9e34-944b1639b174', '唐', '["帷橫雙翡翠，被卷兩鴛鴦。","婉態不自得，宛轉君王牀。"]', '["帷橫雙翡翠，被卷兩鴛鴦。","婉態不自得，宛轉君王牀。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌六首 冬歌二首 二 郭元振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e92a96d-aa74-4153-8314-b6df22d1e18a', '相和歌辭 子夜四時歌四首 春歌', '相和歌辞 子夜四时歌四首 春歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["秦地羅敷女，采桑綠水邊。","素手青條上，紅妝白日鮮。","蠶飢妾欲去，五馬莫留連。"]', '["秦地羅敷女，采桑綠水邊。","素手青條上，紅妝白日鲜。","蠶飢妾欲去，五马莫留連。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌四首 春歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bd5be2b-5788-42c0-a300-9d106a73d46e', '相和歌辭 子夜四時歌四首 夏歌', '相和歌辞 子夜四时歌四首 夏歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鏡湖三百里，菡萏發荷花。","五月西施采，人看隘若邪。","迴舟不待月，歸去越王家。"]', '["镜湖三百里，菡萏發荷花。","五月西施采，人看隘若邪。","迴舟不待月，归去越王家。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌四首 夏歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49194c4b-b775-4d21-a506-fc0a2ff308f1', '相和歌辭 子夜四時歌四首 秋歌', '相和歌辞 子夜四时歌四首 秋歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長安一片月，萬戶擣衣聲。","秋風吹不盡，總是玉關情。","何日平胡虜？良人罷遠征。"]', '["长安一片月，万戶擣衣声。","秋风吹不尽，總是玉关情。","何日平胡虜？良人罷远征。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌四首 秋歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35319d7e-9cf6-43b0-bfa3-991cf82a49f9', '相和歌辭 子夜四時歌四首 冬歌', '相和歌辞 子夜四时歌四首 冬歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["明朝驛使發，一夜絮征袍。","素手抽針冷，那堪把剪刀。","裁縫寄遠道，幾日到臨洮。"]', '["明朝驛使發，一夜絮征袍。","素手抽針冷，那堪把剪刀。","裁縫寄远道，幾日到臨洮。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌四首 冬歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('051a3fc4-b7c9-4345-a255-2e7887b448e5', '相和歌辭 子夜四時歌四首 春歌', '相和歌辞 子夜四时歌四首 春歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["山連翠羽屏，草接煙華席。","望盡南飛燕，佳人斷信息。"]', '["山連翠羽屏，草接煙华席。","望尽南飞燕，佳人斷信息。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌四首 春歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6335b64e-eb8c-4bfb-af43-04079f2bdd4c', '相和歌辭 子夜四時歌四首 夏歌', '相和歌辞 子夜四时歌四首 夏歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["蘭眼擡露斜，鶯脣映花老。","金龍傾漏盡，玉井敲冰早。"]', '["蘭眼擡露斜，鶯脣映花老。","金龙傾漏尽，玉井敲冰早。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌四首 夏歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8bb369b9-1505-409f-823c-346f3502e29f', '相和歌辭 子夜四時歌四首 秋歌', '相和歌辞 子夜四时歌四首 秋歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["涼漢清泬寥，衰林怨風雨。","愁聽絡緯唱，似與羇魂語。"]', '["涼漢清泬寥，衰林怨风雨。","愁听絡緯唱，似與羇魂語。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌四首 秋歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94c281fc-90b7-47c8-8e6e-a18445b158fb', '相和歌辭 子夜四時歌四首 冬歌', '相和歌辞 子夜四时歌四首 冬歌', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["南光走冷圭，北籟號空木。","年年任霜霰，不減篔簹綠。"]', '["南光走冷圭，北籟號空木。","年年任霜霰，不減篔簹綠。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜四時歌四首 冬歌 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e3884c7-3768-4f7d-abab-164219e603a1', '相和歌辭 大子夜歌二首 一', '相和歌辞 大子夜歌二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["歌謠數百種，子夜最可憐。","慷慨吐清音，明轉出天然。"]', '["歌謠數百種，子夜最可怜。","慷慨吐清音，明轉出天然。"]', '诗', 'shi', '', NULL, '相和歌辭 大子夜歌二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a473d2c3-e90d-447a-aa53-adb3b478290d', '相和歌辭 大子夜歌二首 二', '相和歌辞 大子夜歌二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["絲竹發歌響，假器揚清音。","不知歌謠妙，聲勢出口心。"]', '["絲竹發歌响，假器揚清音。","不知歌謠妙，声勢出口心。"]', '诗', 'shi', '', NULL, '相和歌辭 大子夜歌二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a18b4c1-5ce6-46b6-84ee-86fec16eb74a', '相和歌辭 子夜警歌二首 一', '相和歌辞 子夜警歌二首 一', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["鏤椀傳綠酒，雕爐熏紫煙。","誰知苦寒調，共作白雪弦。"]', '["鏤椀傳綠酒，雕爐熏紫煙。","誰知苦寒調，共作白雪弦。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜警歌二首 一 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0129f4a2-76ec-4ed8-a385-a5142a49e274', '相和歌辭 子夜警歌二首 二', '相和歌辞 子夜警歌二首 二', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["恃愛如欲進，含羞出不前。","朱口發豔歌，玉指弄嬌弦。"]', '["恃愛如欲進，含羞出不前。","朱口發豔歌，玉指弄嬌弦。"]', '诗', 'shi', '', NULL, '相和歌辭 子夜警歌二首 二 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd2f806d-530b-4172-8012-db5a51f95cbd', '相和歌辭 丁督護歌', '相和歌辞 丁督護歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["雲陽上征去，兩岸饒商賈。","吳牛喘月時，拖船一何苦。","水濁不可飲，壺漿半成土。","一唱都護歌，心摧淚如雨。","萬人鑿盤石，無由達江滸。","君看石芒碭，掩淚悲千古。"]', '["云陽上征去，兩岸饒商賈。","吳牛喘月时，拖船一何苦。","水濁不可饮，壺漿半成土。","一唱都護歌，心摧泪如雨。","万人鑿盤石，無由達江滸。","君看石芒碭，掩泪悲千古。"]', '诗', 'shi', '', NULL, '相和歌辭 丁督護歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f3a5091-8059-4f25-b30a-45381ca6d645', '相和歌辭 團扇郎', '相和歌辞 團扇郎', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["白團扇，今來此去捐。","願得入郎手，團圓郎眼前。"]', '["白團扇，今来此去捐。","願得入郎手，團圓郎眼前。"]', '诗', 'shi', '', NULL, '相和歌辭 團扇郎 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6db52079-cf43-4b08-ba0d-edbc69eebe29', '相和歌辭 團扇郎', '相和歌辞 團扇郎', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["團扇復團扇，奉君清暑殿。","秋風入庭樹，從此不相見。","上有乘鸞女，蒼蒼蟲網遍。","明年入懷袖，別是機中練。"]', '["團扇复團扇，奉君清暑殿。","秋风入庭樹，從此不相见。","上有乘鸾女，蒼蒼蟲網遍。","明年入懷袖，別是機中練。"]', '诗', 'shi', '', NULL, '相和歌辭 團扇郎 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78185292-1450-416c-bd9d-8403d9e69537', '相和歌辭 碧玉歌', '相和歌辞 碧玉歌', 'bc3ce6dd-5bcf-4826-a95e-9852e09fc0a6', '唐', '["碧玉上宮妓，出入千花林。","珠被玳瑁牀，感郎情意深。"]', '["碧玉上宮妓，出入千花林。","珠被玳瑁牀，感郎情意深。"]', '诗', 'shi', '', NULL, '相和歌辭 碧玉歌 李暇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e8ddf82-3bbc-49aa-ac97-2abdd2cd760a', '相和歌辭 懊惱曲', '相和歌辞 懊惱曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["藕絲作線難勝針，蘂粉染黃那得深。","玉白蘭芳不相顧，倡樓一笑輕千金。","莫言自古皆如此，健劒刜鐘鉛繞指。","三秋庭綠盡迎霜，惟有荷花守紅死。","西江小吏朱斑輪，柳縷吐芽香玉春。","兩股金釵已相許，不令獨作空城塵。","悠悠楚水流如馬，恨紫愁紅滿平野。","野土千年怨不平，至今燒作鴛鴦瓦。"]', '["藕絲作線难勝針，蘂粉染黄那得深。","玉白蘭芳不相顧，倡楼一笑轻千金。","莫言自古皆如此，健劒刜鐘鉛繞指。","三秋庭綠尽迎霜，惟有荷花守紅死。","西江小吏朱斑輪，柳縷吐芽香玉春。","兩股金釵已相許，不令独作空城塵。","悠悠楚水流如马，恨紫愁紅满平野。","野土千年怨不平，至今燒作鴛鴦瓦。"]', '诗', 'shi', '', NULL, '相和歌辭 懊惱曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae02eae3-4d12-45da-84a6-949f88a0bd48', '相和歌辭 讀曲歌五首 一', '相和歌辞 读曲歌五首 一', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["窗中獨自起，簾外獨自行。","愁見蜘蛛織，尋思直到明。"]', '["窗中独自起，簾外独自行。","愁见蜘蛛织，尋思直到明。"]', '诗', 'shi', '', NULL, '相和歌辭 讀曲歌五首 一 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe5ade0f-5f0b-48b0-b645-00de441422a8', '相和歌辭 讀曲歌五首 二', '相和歌辞 读曲歌五首 二', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["碓上米不舂，窗中絲罷絡。","看渠駕去車，定是無四角。"]', '["碓上米不舂，窗中絲罷絡。","看渠駕去车，定是無四角。"]', '诗', 'shi', '', NULL, '相和歌辭 讀曲歌五首 二 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3a8600d-8a45-441b-b9b1-36c08d87a691', '相和歌辭 讀曲歌五首 三', '相和歌辞 读曲歌五首 三', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["不見心相許，徒云脚漫勤。","摘荷空摘葉，是底采蓮人。"]', '["不见心相許，徒云脚漫勤。","摘荷空摘葉，是底采蓮人。"]', '诗', 'shi', '', NULL, '相和歌辭 讀曲歌五首 三 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2cde274-cda9-4603-8317-155ba71d9dc3', '相和歌辭 讀曲歌五首 四', '相和歌辞 读曲歌五首 四', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["窗外山魈立，知渠脚不多。","三更機底下，摸著是誰梭。"]', '["窗外山魈立，知渠脚不多。","三更機底下，摸著是誰梭。"]', '诗', 'shi', '', NULL, '相和歌辭 讀曲歌五首 四 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06b84ebb-073f-4ff0-9796-a615ac5d13f3', '相和歌辭 讀曲歌五首 五', '相和歌辞 读曲歌五首 五', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["郎去摘黃瓜，郎來收赤棗。","郎耕種麻地，今作西舍道。"]', '["郎去摘黄瓜，郎来收赤棗。","郎耕種麻地，今作西舍道。"]', '诗', 'shi', '', NULL, '相和歌辭 讀曲歌五首 五 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e56e4c5d-9552-4ec9-a4c5-a86e08e1ef6f', '相和歌辭 春江花月夜二首 一', '相和歌辞 春江花月夜二首 一', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["林花發岸口，氣色動江新。","此夜江中月，流光花上春。","分明石潭裏，宜照浣紗人。"]', '["林花發岸口，氣色动江新。","此夜江中月，流光花上春。","分明石潭裏，宜照浣紗人。"]', '诗', 'shi', '', NULL, '相和歌辭 春江花月夜二首 一 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ed3a7f5-c68a-40ba-b28f-50ebbfac1091', '相和歌辭 春江花月夜二首 二', '相和歌辞 春江花月夜二首 二', 'c306d73f-3f8d-455d-a993-1114979907e9', '唐', '["交甫憐瑤佩，仙妃難重期。","沈沈綠江晚，惆悵碧雲姿。","初逢花上月，言是弄珠時。"]', '["交甫怜瑤佩，仙妃难重期。","沈沈綠江晚，惆悵碧云姿。","初逢花上月，言是弄珠时。"]', '诗', 'shi', '', NULL, '相和歌辭 春江花月夜二首 二 張子容 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91019fe2-b58e-4320-a986-6a323847e944', '相和歌辭 春江花月夜', '相和歌辞 春江花月夜', 'f309e4dc-8e63-458b-8edf-b5c1873c0bd5', '唐', '["春江潮水連海平，海上明月共潮生。","灩灩隨波千萬里，何處春江無月明？","江流宛轉遶芳甸，月照花林皆似霰。","空裏流霜不覺飛，汀上白沙看不見。","江天一色無纖塵，皎皎空中孤月輪。","江畔何人初見月？江月何年初照人？","人生代代無窮已，江月年年望相似。","不知江月待何人，但見長江送流水。","白雲一片去悠悠，青楓浦上不勝愁。","誰家今夜扁舟子，何處相思明月樓？","可憐樓上月裴回，應照離人妝鏡臺。","玉戶簾中卷不去，擣衣砧上拂還來。","此時相望不相聞，願逐月華流照君。","鴻雁長飛光不度，魚龍潛躍水成文。","昨夜閑潭夢落花，可憐春半不還家。","江水流春去欲盡，江潭落月復西斜。","斜月沈沈藏海霧，碣石瀟湘無限路。","不知乘月幾人歸，落月搖情滿江樹。"]', '["春江潮水連海平，海上明月共潮生。","灩灩隨波千万里，何处春江無月明？","江流宛轉遶芳甸，月照花林皆似霰。","空裏流霜不覺飞，汀上白沙看不见。","江天一色無纖塵，皎皎空中孤月輪。","江畔何人初见月？江月何年初照人？","人生代代無窮已，江月年年望相似。","不知江月待何人，但见长江送流水。","白云一片去悠悠，青楓浦上不勝愁。","誰家今夜扁舟子，何处相思明月楼？","可怜楼上月裴回，應照離人妝镜台。","玉戶簾中卷不去，擣衣砧上拂還来。","此时相望不相闻，願逐月华流照君。","鴻雁长飞光不度，鱼龙潛躍水成文。","昨夜闲潭梦落花，可怜春半不還家。","江水流春去欲尽，江潭落月复西斜。","斜月沈沈藏海霧，碣石瀟湘無限路。","不知乘月幾人归，落月搖情满江樹。"]', '诗', 'shi', '', NULL, '相和歌辭 春江花月夜 張若虛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4912092-34c2-42fe-a9ff-b924b0dddf7f', '相和歌辭 春江花月夜', '相和歌辞 春江花月夜', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["玉樹歌闌海雲黑，花庭忽作青蕪國。","秦淮有水水無情，還向金陵漾春色。","楊家二世安九重，不御華芝嫌六龍。","百幅錦帆風力滿，連天展盡金芙蓉。","珠翠丁星復明滅，龍頭劈浪哀笳發。","千里涵空照水魂，萬枝破鼻團香雪。","漏轉霞高滄海西，頗黎枕上聞天雞。","蠻弦代雁曲如語，一醉昏昏天下迷。","四方傾動煙塵起，猶在濃香夢魂裏。","後主荒宮有曉鶯，飛來只隔西江水。"]', '["玉樹歌闌海云黑，花庭忽作青蕪国。","秦淮有水水無情，還向金陵漾春色。","楊家二世安九重，不御华芝嫌六龙。","百幅錦帆风力满，連天展尽金芙蓉。","珠翠丁星复明滅，龙头劈浪哀笳發。","千里涵空照水魂，万枝破鼻團香雪。","漏轉霞高滄海西，頗黎枕上闻天雞。","蠻弦代雁曲如語，一醉昏昏天下迷。","四方傾动煙塵起，猶在濃香梦魂裏。","後主荒宮有晓鶯，飞来只隔西江水。"]', '诗', 'shi', '', NULL, '相和歌辭 春江花月夜 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d74e9598-2653-4bb2-99b6-34f0f916858b', '相和歌辭 玉樹後庭花', '相和歌辞 玉樹後庭花', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["輕車何草草，獨唱後庭花。","玉座誰爲主，徒悲張麗華。"]', '["轻车何草草，独唱後庭花。","玉座誰爲主，徒悲張丽华。"]', '诗', 'shi', '', NULL, '相和歌辭 玉樹後庭花 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('639d9810-3074-4ec3-9d03-058b016ff14b', '相和歌辭 堂堂', '相和歌辞 堂堂', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["錢塘岸上春如織，淼淼寒潮帶晴色。","淮南遊客馬連嘶，碧草迷人歸不得。","風飄客意如吹煙，纖指殷勤傷雁弦。","一曲堂堂紅燭筵，金鯨瀉酒如飛泉。"]', '["錢塘岸上春如织，淼淼寒潮带晴色。","淮南游客马連嘶，碧草迷人归不得。","风飄客意如吹煙，纖指殷勤傷雁弦。","一曲堂堂紅燭筵，金鯨瀉酒如飞泉。"]', '诗', 'shi', '', NULL, '相和歌辭 堂堂 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('407210c8-10a9-412e-8dcb-2740914ddf70', '相和歌辭 三閣詞四首 一', '相和歌辞 三閣词四首 一', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["貴人三閣上，日晏未梳頭。","不應有恨事，嬌甚却成愁。"]', '["貴人三閣上，日晏未梳头。","不應有恨事，嬌甚却成愁。"]', '诗', 'shi', '', NULL, '相和歌辭 三閣詞四首 一 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ca59348-308c-46a9-8472-cea3b91d7718', '相和歌辭 三閣詞四首 二', '相和歌辞 三閣词四首 二', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["珠箔曲瓊鉤，子細見揚州。","北兵那得度，浪語判悠悠。"]', '["珠箔曲瓊鉤，子細见揚州。","北兵那得度，浪語判悠悠。"]', '诗', 'shi', '', NULL, '相和歌辭 三閣詞四首 二 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa1ecb79-ccad-4a2a-9194-7b86f872f0d1', '相和歌辭 三閣詞四首 三', '相和歌辞 三閣词四首 三', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["沈香帖閣柱，金縷畫門楣。","回首降幡下，已見黍離離。"]', '["沈香帖閣柱，金縷畫门楣。","回首降幡下，已见黍離離。"]', '诗', 'shi', '', NULL, '相和歌辭 三閣詞四首 三 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f94d44f-4079-460f-bdbd-474e5519bcf5', '相和歌辭 三閣詞四首 四', '相和歌辞 三閣词四首 四', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["三人出眢井，一身登檻車。","朱門漫臨水，不可見鱸魚。"]', '["三人出眢井，一身登檻车。","朱门漫臨水，不可见鱸鱼。"]', '诗', 'shi', '', NULL, '相和歌辭 三閣詞四首 四 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14539ccd-fbfb-4002-950f-e299956306aa', '相和歌辭 神弦曲', '相和歌辞 神弦曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["西山日沒東山昏，旋風吹馬馬踏雲。","畫弦素管聲淺繁，花裙綷䌨步秋塵。","桂葉刷風桂墜子，青狸哭血寒狐死。","古壁彩虬金帖尾，雨工騎入秋潭水。","百年老鴞成木魅，笑聲碧火巢中起。"]', '["西山日沒东山昏，旋风吹马马踏云。","畫弦素管声淺繁，花裙綷䌨步秋塵。","桂葉刷风桂墜子，青狸哭血寒狐死。","古壁彩虬金帖尾，雨工騎入秋潭水。","百年老鴞成木魅，笑声碧火巢中起。"]', '诗', 'shi', '', NULL, '相和歌辭 神弦曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74c51375-f0ae-45b3-8148-57b7e256b868', '相和歌辭 神弦別曲', '相和歌辞 神弦別曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["巫山小女隔雲別，松花春風山上發。","綠蓋獨穿香逕歸，白馬花竿前孑孑。","蜀江風澹水如羅，墮蘭誰泛相經過。","南山桂樹爲君死，雲衫殘汙紅脂花。"]', '["巫山小女隔云別，松花春风山上發。","綠蓋独穿香逕归，白马花竿前孑孑。","蜀江风澹水如羅，墮蘭誰泛相經過。","南山桂樹爲君死，云衫殘汙紅脂花。"]', '诗', 'shi', '', NULL, '相和歌辭 神弦別曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('753a6185-3664-44b5-adf5-1571e086c288', '相和歌辭 祠漁山神女歌 迎神', '相和歌辞 祠漁山神女歌 迎神', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["坎坎擊鼓，漁山之下。","吹洞簫，望極浦。","女巫進，紛屢舞。","陳瑤席，湛清酤。","風淒淒，又夜雨。","不知神之來兮不來，使我心兮苦復苦。"]', '["坎坎擊鼓，漁山之下。","吹洞簫，望極浦。","女巫進，紛屢舞。","陳瑤席，湛清酤。","风淒淒，又夜雨。","不知神之来兮不来，使我心兮苦复苦。"]', '诗', 'shi', '', NULL, '相和歌辭 祠漁山神女歌 迎神 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54e23ca8-53b1-4dc7-ac69-06e4067f5ab4', '相和歌辭 祠漁山神女歌 送神', '相和歌辞 祠漁山神女歌 送神', '0a9829cc-805b-4812-a86a-1b2aee6a69ad', '唐', '["紛進舞兮堂前，目眷眷兮瓊筵。","來不言兮意不傳，作暮雨兮愁空山。","悲急管兮思繁弦，神之駕兮儼欲旋。","倏雲收兮雨歇，山青青兮水潺湲。"]', '["紛進舞兮堂前，目眷眷兮瓊筵。","来不言兮意不傳，作暮雨兮愁空山。","悲急管兮思繁弦，神之駕兮儼欲旋。","倏云收兮雨歇，山青青兮水潺湲。"]', '诗', 'shi', '', NULL, '相和歌辭 祠漁山神女歌 送神 王維 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96b177ab-60c1-44cf-bd9a-50fe4c4fc1eb', '相和歌辭 祠神歌 迎神', '相和歌辞 祠神歌 迎神', '1e83089e-457c-454a-aba3-02dac6374fc6', '唐', '["蓪草頭花椰葉裙，蒲葵樹下舞蠻雲。","引領望江遙滴酒，白蘋風起水生文。"]', '["蓪草头花椰葉裙，蒲葵樹下舞蠻云。","引領望江遙滴酒，白蘋风起水生文。"]', '诗', 'shi', '', NULL, '相和歌辭 祠神歌 迎神 王叡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57ea34b3-5fb6-46b0-8686-c55fa62fdf55', '相和歌辭 祠神歌 送神', '相和歌辞 祠神歌 送神', '1e83089e-457c-454a-aba3-02dac6374fc6', '唐', '["棖棖山響荅琵琶，酒溼青莎肉飼鵶。","樹葉無聲神去後，紙錢灰出木綿花。"]', '["棖棖山响荅琵琶，酒溼青莎肉飼鵶。","樹葉無声神去後，紙錢灰出木綿花。"]', '诗', 'shi', '', NULL, '相和歌辭 祠神歌 送神 王叡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2a74a11-b43a-448c-9f5d-e895c9e60ec8', '相和歌辭 烏夜啼', '相和歌辞 烏夜啼', '08b14256-c564-4489-be33-927205119c81', '唐', '["可憐楊葉復楊花，雪淨煙深碧玉家。","烏棲不定枝條弱，城頭夜半聲啞啞。","浮萍搖蕩門前水，任罥芙蓉莫墮沙。"]', '["可怜楊葉复楊花，雪淨煙深碧玉家。","烏棲不定枝條弱，城头夜半声啞啞。","浮萍搖蕩门前水，任罥芙蓉莫墮沙。"]', '诗', 'shi', '', NULL, '相和歌辭 烏夜啼 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13451903-5007-4425-aacd-921c8124af6d', '相和歌辭 烏夜啼', '相和歌辞 烏夜啼', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["黃雲城邊烏欲棲，歸飛啞啞枝上啼。","機中織錦秦川女，碧紗如煙隔窗語。","停梭悵然憶遠人，獨宿孤房淚如雨。"]', '["黄云城邊烏欲棲，归飞啞啞枝上啼。","機中织錦秦川女，碧紗如煙隔窗語。","停梭悵然憶远人，独宿孤房泪如雨。"]', '诗', 'shi', '', NULL, '相和歌辭 烏夜啼 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1379e240-3f5a-4133-adfb-584726beff54', '相和歌辭 烏夜啼二首 一', '相和歌辞 烏夜啼二首 一', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["玉房掣鎖聲翻葉，銀箭添泉遶霜堞。","畢逋發刺月銜城，八九雛飛其母驚。","此是天上老鵶鳴，人間老鵶無此聲。","搖雜佩，耿華燭，良夜羽人彈此曲，東方曈曈赤日旭。"]', '["玉房掣鎖声翻葉，銀箭添泉遶霜堞。","畢逋發刺月銜城，八九雛飞其母驚。","此是天上老鵶鳴，人间老鵶無此声。","搖杂佩，耿华燭，良夜羽人彈此曲，东方曈曈赤日旭。"]', '诗', 'shi', '', NULL, '相和歌辭 烏夜啼二首 一 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6eaddc9d-e02c-4dbf-b048-2ba87ef3cecd', '相和歌辭 烏夜啼二首 二', '相和歌辞 烏夜啼二首 二', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["月出江林西，江林寂寂城鵶啼。","昔人何處爲此曲？今人何處聽不足。","城寒月曉馳思深，江上青草爲誰綠。"]', '["月出江林西，江林寂寂城鵶啼。","昔人何处爲此曲？今人何处听不足。","城寒月晓驰思深，江上青草爲誰綠。"]', '诗', 'shi', '', NULL, '相和歌辭 烏夜啼二首 二 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc1124b1-22cb-4556-8078-54998b4973f7', '相和歌辭 烏夜啼', '相和歌辞 烏夜啼', '0df5a45d-efe9-4b4f-be36-4ca79d1b0a22', '唐', '["曾波隔夢渚，一望青楓林。","有烏在其間，達曉自悲吟。","是時月黑天，四野煙雨深。","如聞生離哭，其聲痛人心。","悄悄夜正長，空山響哀音。","遠客不可聽，坐愁華髮侵。","既非蜀帝魂，恐是恆山禽。","四子各分散，母聲猶至今。"]', '["曾波隔梦渚，一望青楓林。","有烏在其间，達晓自悲吟。","是时月黑天，四野煙雨深。","如闻生離哭，其声痛人心。","悄悄夜正长，空山响哀音。","远客不可听，坐愁华髮侵。","既非蜀帝魂，恐是恆山禽。","四子各分散，母声猶至今。"]', '诗', 'shi', '', NULL, '相和歌辭 烏夜啼 李羣玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c9f73b3-1088-48aa-b4c6-8506d0047799', '相和歌辭 烏夜啼', '相和歌辞 烏夜啼', 'cffe5078-65a3-4b73-9d54-6590b97ba7af', '唐', '["衆鳥各歸枝，烏烏爾不棲。","還應知妾恨，故向綠窗啼。"]', '["衆鸟各归枝，烏烏爾不棲。","還應知妾恨，故向綠窗啼。"]', '诗', 'shi', '', NULL, '相和歌辭 烏夜啼 聶夷中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4dbdb10-93e6-4174-84d9-0ca91e4171a6', '相和歌辭 烏夜啼', '相和歌辞 烏夜啼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["城上歸時晚，庭前宿處危。","月明無葉樹，霜滑有風枝。","啼澀飢喉咽，飛低凍翅垂。","畫堂鸚鵡鳥，冷暖不相知。"]', '["城上归时晚，庭前宿处危。","月明無葉樹，霜滑有风枝。","啼澀飢喉咽，飞低凍翅垂。","畫堂鸚鵡鸟，冷暖不相知。"]', '诗', 'shi', '', NULL, '相和歌辭 烏夜啼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fcd98df-b017-4b6b-8c1d-441bab09b03c', '相和歌辭 烏夜啼', '相和歌辞 烏夜啼', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["庭樹烏，爾何不向別處棲？","夜夜夜半當戶啼。","家人把燭出洞戶，驚棲失羣飛落樹。","一飛直欲飛上天，回回不離舊棲處。","未明重繞主人屋，欲下空中黑相觸。","風飄雨溼亦不移，君家樹頭多好枝。"]', '["庭樹烏，爾何不向別处棲？","夜夜夜半當戶啼。","家人把燭出洞戶，驚棲失羣飞落樹。","一飞直欲飞上天，回回不離旧棲处。","未明重繞主人屋，欲下空中黑相觸。","风飄雨溼亦不移，君家樹头多好枝。"]', '诗', 'shi', '', NULL, '相和歌辭 烏夜啼 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1954c0fe-9100-4652-b9ee-4ae3dc34ac45', '相和歌辭 烏夜啼', '相和歌辞 烏夜啼', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["忽忽南飛返，危弦共怨悽。","暗霜移樹宿，殘夜遶枝啼。","咽絕聲重敍，愔淫思乍迷。","不妨還報喜，誤使玉顏低。"]', '["忽忽南飞返，危弦共怨悽。","暗霜移樹宿，殘夜遶枝啼。","咽絕声重敍，愔淫思乍迷。","不妨還報喜，誤使玉顏低。"]', '诗', 'shi', '', NULL, '相和歌辭 烏夜啼 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a650c60-d583-479e-b014-f72ae071cdc4', '相和歌辭 烏棲曲', '相和歌辞 烏棲曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["姑蘇臺上烏棲時，吳王宮裏醉西施。","吳歌楚舞歡未畢，青山猶銜半邊日。"]', '["姑蘇台上烏棲时，吳王宮裏醉西施。","吳歌楚舞歡未畢，青山猶銜半邊日。"]', '诗', 'shi', '', NULL, '相和歌辭 烏棲曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b19827-d759-4f46-ad60-4c95661e7021', '相和歌辭 烏棲曲', '相和歌辞 烏棲曲', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["白馬逐牛車，黃昏入狹斜。","狹斜柳樹烏爭宿，爭枝未得飛上屋。","東房少婦壻從軍，每聽烏啼知夜分。"]', '["白马逐牛车，黄昏入狹斜。","狹斜柳樹烏爭宿，爭枝未得飞上屋。","东房少婦壻從軍，每听烏啼知夜分。"]', '诗', 'shi', '', NULL, '相和歌辭 烏棲曲 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e93985-8694-48cd-af67-054478b5a597', '相和歌辭 烏棲曲', '相和歌辞 烏棲曲', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["章華宮人夜上樓，君王望月西山頭。","夜深宮殿門不鎖，白露滿山山葉墮。"]', '["章华宮人夜上楼，君王望月西山头。","夜深宮殿门不鎖，白露满山山葉墮。"]', '诗', 'shi', '', NULL, '相和歌辭 烏棲曲 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f859f612-323e-45ba-aad9-18cf91428424', '相和歌辭 烏棲曲', '相和歌辞 烏棲曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["西山作宮潮滿池，宮烏曉鳴茱萸枝。","吳姬自唱采蓮曲，君王昨夜舟中宿。"]', '["西山作宮潮满池，宮烏晓鳴茱萸枝。","吳姬自唱采蓮曲，君王昨夜舟中宿。"]', '诗', 'shi', '', NULL, '相和歌辭 烏棲曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14ac7bda-d0fc-47fd-b824-b71f6ebfe7b2', '相和歌辭 棲烏曲二首 一', '相和歌辞 棲烏曲二首 一', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["蛾眉曼臉傾城國，鳴環動佩新相識。","銀漢斜臨白玉堂，芙蓉行障掩燈光。"]', '["蛾眉曼臉傾城国，鳴环动佩新相識。","銀漢斜臨白玉堂，芙蓉行障掩灯光。"]', '诗', 'shi', '', NULL, '相和歌辭 棲烏曲二首 一 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08c6ae60-efc8-4fc0-b9c8-0aaed09a803f', '相和歌辭 棲烏曲二首 二', '相和歌辞 棲烏曲二首 二', 'bcc19379-0cd3-45d1-985f-8aa6bf5c5476', '唐', '["畫舸雙艚錦爲纜，芙蓉花發蓮葉暗。","門前月色映橫塘，感郎中夜渡瀟湘。"]', '["畫舸雙艚錦爲纜，芙蓉花發蓮葉暗。","门前月色映橫塘，感郎中夜渡瀟湘。"]', '诗', 'shi', '', NULL, '相和歌辭 棲烏曲二首 二 劉方平 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ac317e6-a69f-4e17-b73a-f7775331b25d', '相和歌辭 莫愁樂', '相和歌辞 莫愁乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["儂居石城下，郎到石城遊。","自郎石城出，長在石城頭。"]', '["儂居石城下，郎到石城游。","自郎石城出，长在石城头。"]', '诗', 'shi', '', NULL, '相和歌辭 莫愁樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cecf507-4b41-428f-ba64-141d0c7492b7', '相和歌辭 莫愁曲', '相和歌辞 莫愁曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["草生隴坂下，鵶噪城堞頭。","何人此城裏，城角栽石榴。","青絲繫五馬，黃金絡雙牛。","白魚駕蓮船，夜作十里遊。","歸來無人識，暗上沈香樓。","羅牀倚瑤瑟，殘月傾簾鉤。","今日槿花落，明朝梧樹秋。","若負平生意，何名作莫愁。"]', '["草生隴坂下，鵶噪城堞头。","何人此城裏，城角栽石榴。","青絲繫五马，黄金絡雙牛。","白鱼駕蓮船，夜作十里游。","归来無人識，暗上沈香楼。","羅牀倚瑤瑟，殘月傾簾鉤。","今日槿花落，明朝梧樹秋。","若負平生意，何名作莫愁。"]', '诗', 'shi', '', NULL, '相和歌辭 莫愁曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aadd63e4-92bc-4d8d-9272-94e63ac260a8', '相和歌辭 估客樂', '相和歌辞 估客乐', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["海客乘天風，將船遠行役。","譬如雲中鳥，一去無蹤跡。"]', '["海客乘天风，將船远行役。","譬如云中鸟，一去無蹤跡。"]', '诗', 'shi', '', NULL, '相和歌辭 估客樂 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49a7fdb4-f899-42a1-a13f-8397020dc267', '相和歌辭 估客樂', '相和歌辞 估客乐', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["估客無住著，有利身即行。","出門求火伴，入戶辭父兄。","父兄相教示，求利莫求名。","求名有所避，求利無不營。","火伴相勒縛，賣假莫賣誠。","交關少交假，交假本生輕。","自茲相將去，誓死意不更。","一解市頭語，便無鄉里情。","鍮石打臂釧，糯米炊項瓔。","歸來村中賣，敲作金玉聲。","村中田舍娘，貴賤不敢爭。","所費百錢本，已得十倍贏。","顏色轉光淨，飲食亦甘馨。","子本頻蕃息，貨賂日兼幷。","求珠駕滄海，采玉上荆衡。","北買党項馬，西擒吐蕃鸚。","炎洲布火浣，蜀地錦織成。","越婢脂肉滑，奚僮眉眼明。","通算衣食費，不計遠近程。","經營天下徧，却到長安城。","城中東西市，聞客次第迎。","迎客兼說客，多財爲勢傾。","客心本明黠，聞語心已驚。","先問十常侍，次求百公卿。","侯家與主第，點綴無不精。","歸來始安坐，富與王家勍。","市卒酒肉臭，縣胥家舍成。","豈惟絕言語，奔走極使令。","大兒販材木，巧識梁棟形。","小兒販鹽鹵，不入州縣征。","一身偃市利，突若截海鯨。","鉤距不敢下，下則牙齒橫。","生爲估客樂，判爾樂一生。"]', '["估客無住著，有利身即行。","出门求火伴，入戶辞父兄。","父兄相教示，求利莫求名。","求名有所避，求利無不營。","火伴相勒縛，賣假莫賣誠。","交关少交假，交假本生轻。","自茲相將去，誓死意不更。","一解市头語，便無乡里情。","鍮石打臂釧，糯米炊項瓔。","归来村中賣，敲作金玉声。","村中田舍娘，貴賤不敢爭。","所費百錢本，已得十倍贏。","顏色轉光淨，饮食亦甘馨。","子本頻蕃息，貨賂日兼幷。","求珠駕滄海，采玉上荆衡。","北買党項马，西擒吐蕃鸚。","炎洲布火浣，蜀地錦织成。","越婢脂肉滑，奚僮眉眼明。","通算衣食費，不計远近程。","經營天下徧，却到长安城。","城中东西市，闻客次第迎。","迎客兼说客，多財爲勢傾。","客心本明黠，闻語心已驚。","先问十常侍，次求百公卿。","侯家與主第，点綴無不精。","归来始安坐，富與王家勍。","市卒酒肉臭，縣胥家舍成。","豈惟絕言語，奔走極使令。","大兒販材木，巧識梁棟形。","小兒販鹽鹵，不入州縣征。","一身偃市利，突若截海鯨。","鉤距不敢下，下則牙齒橫。","生爲估客乐，判爾乐一生。"]', '诗', 'shi', '', NULL, '相和歌辭 估客樂 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bee0dc6f-92c2-4285-8e0a-8f36529025b7', '相和歌辭 賈客樂', '相和歌辞 賈客乐', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["金陵向西賈客多，船中生長樂風波。","欲發移船近江口，船頭祭神各澆酒。","停杯共說遠行期，入蜀經蠻遠別離。","金多衆中爲上客，夜夜算緡眠獨遲。","秋江初月猩猩語，孤帆夜發滿湘渚。","水工持檝防暗灘，直過山邊及前侶。","年年逐利西復東，姓名不在縣籍中。","農夫稅多長辛苦，棄業長爲販賣翁。"]', '["金陵向西賈客多，船中生长乐风波。","欲發移船近江口，船头祭神各澆酒。","停杯共说远行期，入蜀經蠻远別離。","金多衆中爲上客，夜夜算緡眠独遲。","秋江初月猩猩語，孤帆夜發满湘渚。","水工持檝防暗灘，直過山邊及前侶。","年年逐利西复东，姓名不在縣籍中。","農夫稅多长辛苦，棄業长爲販賣翁。"]', '诗', 'shi', '', NULL, '相和歌辭 賈客樂 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33dfbf78-71db-4d5f-bba2-4832620a2f8f', '相和歌辭 賈客詞', '相和歌辞 賈客词', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["賈客無定遊，所遊惟利幷。","眩俗雜良苦，乘時知重輕。","心計析秋毫，搖鉤侔懸衡。","錐刀既無棄，轉化日已盈。","邀福禱波神，施財遊化城。","妻約雕金釧，女垂貫珠纓。","高貲比封君，奇貨通倖卿。","趨時鷙鳥思，藏鏹盤龍形。","大艑浮通川，高樓次旗亭。","行止皆有樂，關梁似無征。","農夫何爲者？辛苦事寒耕。"]', '["賈客無定游，所游惟利幷。","眩俗杂良苦，乘时知重轻。","心計析秋毫，搖鉤侔懸衡。","錐刀既無棄，轉化日已盈。","邀福禱波神，施財游化城。","妻約雕金釧，女垂貫珠纓。","高貲比封君，奇貨通倖卿。","趨时鷙鸟思，藏鏹盤龙形。","大艑浮通川，高楼次旗亭。","行止皆有乐，关梁似無征。","農夫何爲者？辛苦事寒耕。"]', '诗', 'shi', '', NULL, '相和歌辭 賈客詞 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50e90a6b-8c23-493e-be1b-63ca5d30010c', '相和歌辭 賈客詞', '相和歌辞 賈客词', '614823fd-ee12-4d3a-8272-54c705644217', '唐', '["賈客燈下起，猶言發已遲。","高山有疾路，暗行終不疑。","寇盜伏其路，猛獸來相追。","金玉四散去，空囊委路岐。","揚州有大宅，白骨無地歸。","少婦當此日，對鏡弄花枝。"]', '["賈客灯下起，猶言發已遲。","高山有疾路，暗行終不疑。","寇盜伏其路，猛獸来相追。","金玉四散去，空囊委路岐。","揚州有大宅，白骨無地归。","少婦當此日，对镜弄花枝。"]', '诗', 'shi', '', NULL, '相和歌辭 賈客詞 劉駕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0dc28dbc-d080-47fc-b44a-229e310c187a', '相和歌辭 襄陽樂', '相和歌辞 襄陽乐', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["大堤花月夜，長江春水流。","東風正上信，春夜特來遊。"]', '["大堤花月夜，长江春水流。","东风正上信，春夜特来游。"]', '诗', 'shi', '', NULL, '相和歌辭 襄陽樂 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9322a025-9168-4abc-a815-1d4a235cee67', '相和歌辭 襄陽曲二首 一', '相和歌辞 襄陽曲二首 一', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["蕙草嬌紅蕚，時光舞碧雞。","城中美年少，相見白銅鞮。"]', '["蕙草嬌紅蕚，时光舞碧雞。","城中美年少，相见白銅鞮。"]', '诗', 'shi', '', NULL, '相和歌辭 襄陽曲二首 一 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b0a9bf8-1708-44c2-ad48-e7bbfd01583e', '相和歌辭 襄陽曲二首 二', '相和歌辞 襄陽曲二首 二', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["少年襄陽地，來往襄陽城。","城中輕薄子，知妾解秦箏。"]', '["少年襄陽地，来往襄陽城。","城中轻薄子，知妾解秦箏。"]', '诗', 'shi', '', NULL, '相和歌辭 襄陽曲二首 二 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b074b75-44be-4068-bc31-c4f2cea7287f', '相和歌辭 襄陽曲', '相和歌辞 襄陽曲', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["大堤女兒郎莫尋，三三五五結同心。","清晨對鏡冶容色，意欲取郎千萬金。"]', '["大堤女兒郎莫尋，三三五五結同心。","清晨对镜冶容色，意欲取郎千万金。"]', '诗', 'shi', '', NULL, '相和歌辭 襄陽曲 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cecb680e-5015-4391-8108-4bde2026cd28', '相和歌辭 襄陽曲', '相和歌辞 襄陽曲', '4b5512c2-3199-4ae5-8613-fd55924a8388', '唐', '["襄陽堤路長，草碧楊柳黃。","誰家女兒臨夜妝，紅羅帳裏有燈光。","雀釵翠羽動明璫，欲出不出脂粉香。","同居女伴正衣裳，中庭寒月白如霜。","賈生十八稱才子，空得門前一斷腸。"]', '["襄陽堤路长，草碧楊柳黄。","誰家女兒臨夜妝，紅羅帳裏有灯光。","雀釵翠羽动明璫，欲出不出脂粉香。","同居女伴正衣裳，中庭寒月白如霜。","賈生十八稱才子，空得门前一斷腸。"]', '诗', 'shi', '', NULL, '相和歌辭 襄陽曲 李端 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d05f4524-071a-4914-97f3-bed8e9683a48', '相和歌辭 大堤曲', '相和歌辞 大堤曲', 'db8c386d-e29f-47b9-a015-0fae6b9e00ee', '唐', '["南國多佳人，莫若大堤女。","玉牀翠羽帳，寶袜蓮花炬。","魂處自目成，色授開心許。","迢迢不可見，日暮空愁予。"]', '["南国多佳人，莫若大堤女。","玉牀翠羽帳，寶袜蓮花炬。","魂处自目成，色授开心許。","迢迢不可见，日暮空愁予。"]', '诗', 'shi', '', NULL, '相和歌辭 大堤曲 張柬之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55b11522-995c-490d-ada6-d82404b72473', '相和歌辭 大堤曲', '相和歌辞 大堤曲', '08b14256-c564-4489-be33-927205119c81', '唐', '["二八嬋娟大堤女，開鑪相對依江渚。","待客登樓向水看，邀郎卷幔臨花語。","細雨濛濛溼芰荷，巴東商侶挂帆多。","自傳芳酒涴紅袖，誰調妍妝迴翠蛾。","珍簟華燈夕陽後，當鑪理瑟矜纖手。","月落星微五鼓聲，春風搖蕩窗前柳。","歲歲逢迎沙岸間，北人多識綠雲鬟。","無端嫁與五陵少，離別煙波傷玉顏。"]', '["二八嬋娟大堤女，开鑪相对依江渚。","待客登楼向水看，邀郎卷幔臨花語。","細雨濛濛溼芰荷，巴东商侶挂帆多。","自傳芳酒涴紅袖，誰調妍妝迴翠蛾。","珍簟华灯夕陽後，當鑪理瑟矜纖手。","月落星微五鼓声，春风搖蕩窗前柳。","歲歲逢迎沙岸间，北人多識綠云鬟。","無端嫁與五陵少，離別煙波傷玉顏。"]', '诗', 'shi', '', NULL, '相和歌辭 大堤曲 楊巨源 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c1974fa-bf89-4fec-9ea1-bdc9dff1cd6e', '相和歌辭 大堤曲', '相和歌辞 大堤曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["漢水臨襄陽，花開大堤暖。","佳期大堤下，淚向南雲滿。","春風復無情，吹我夢魂散。","不見眼中人，天長音信斷。"]', '["漢水臨襄陽，花开大堤暖。","佳期大堤下，泪向南云满。","春风复無情，吹我梦魂散。","不见眼中人，天长音信斷。"]', '诗', 'shi', '', NULL, '相和歌辭 大堤曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a84913-0d25-4120-8b74-8c2a8d8815c7', '相和歌辭 大堤曲', '相和歌辞 大堤曲', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["妾家住橫塘，紅紗滿桂香。","青雲教綰頭上髻，明月與作耳邊璫。","蓮風起，江畔春。","大堤上，留北人。","郎食鯉魚尾，妾食猩猩脣。","莫指襄陽道，綠浦歸帆少。","今日菖蒲花，明朝楓樹老。"]', '["妾家住橫塘，紅紗满桂香。","青云教綰头上髻，明月與作耳邊璫。","蓮风起，江畔春。","大堤上，留北人。","郎食鯉鱼尾，妾食猩猩脣。","莫指襄陽道，綠浦归帆少。","今日菖蒲花，明朝楓樹老。"]', '诗', 'shi', '', NULL, '相和歌辭 大堤曲 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5022a1cb-449b-4dcc-8b78-33e9e5914d02', '相和歌辭 大堤行', '相和歌辞 大堤行', '20006a9f-ad85-44c8-a5ea-df55c005e3f5', '唐', '["大堤行樂處，車馬相馳突。","歲歲春草生，踏青二三月。","王孫挾珠彈，遊女矜羅韈。","攜手今莫同，江花爲誰發。"]', '["大堤行乐处，车马相驰突。","歲歲春草生，踏青二三月。","王孫挾珠彈，游女矜羅韈。","携手今莫同，江花爲誰發。"]', '诗', 'shi', '', NULL, '相和歌辭 大堤行 孟浩然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eba1e722-419d-4f72-9c78-07ab2d9bfa84', '相和歌辭 三洲歌', '相和歌辞 三洲歌', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["團圓莫作波中月，潔白莫爲枝上雪。","月隨波動碎潾潾，雪似梅花不堪折。","李娘十六青絲髮，畫帶雙花爲君結。","門前有路輕離別，惟恐歸來舊香滅。"]', '["團圓莫作波中月，潔白莫爲枝上雪。","月隨波动碎潾潾，雪似梅花不堪折。","李娘十六青絲髮，畫带雙花爲君結。","门前有路轻離別，惟恐归来旧香滅。"]', '诗', 'shi', '', NULL, '相和歌辭 三洲歌 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eab098c6-ae6f-453c-9d58-43cd1f1e2abb', '相和歌辭 拔蒲歌', '相和歌辞 拔蒲歌', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["拔蒲來，領郎鏡湖邊。","郎心在何處？莫趂新蓮去。","拔得無心蒲，問郎看好無。"]', '["拔蒲来，領郎镜湖邊。","郎心在何处？莫趂新蓮去。","拔得無心蒲，问郎看好無。"]', '诗', 'shi', '', NULL, '相和歌辭 拔蒲歌 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b343dfb8-3432-42f9-affd-9d096f5b5b5e', '相和歌辭 楊叛兒', '相和歌辞 楊叛兒', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["君歌楊叛兒，妾勸新豐酒。","何許最關人，烏啼白門柳。","烏啼隱楊花，君醉留妾家。","博山爐中沈香火，雙咽一氣凌紫霞。"]', '["君歌楊叛兒，妾勸新豐酒。","何許最关人，烏啼白门柳。","烏啼隐楊花，君醉留妾家。","博山爐中沈香火，雙咽一氣凌紫霞。"]', '诗', 'shi', '', NULL, '相和歌辭 楊叛兒 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7788b533-8d77-41b7-a401-9e1f4cb66182', '相和歌辭 常林歡', '相和歌辞 常林歡', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["宜城酒熟花覆橋，沙晴綠鴨鳴咬咬。","穠桑繞舍麥如尾，幽軋鳴機雙燕巢。","馬聲特特荆門道，蠻水揚光色如草。","錦薦金爐夢正長，東家呃喔雞鳴早。"]', '["宜城酒熟花覆橋，沙晴綠鴨鳴咬咬。","穠桑繞舍麦如尾，幽軋鳴機雙燕巢。","马声特特荆门道，蠻水揚光色如草。","錦薦金爐梦正长，东家呃喔雞鳴早。"]', '诗', 'shi', '', NULL, '相和歌辭 常林歡 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54b45313-84ba-446a-9cbe-f58304b1c29b', '相和歌辭 江南弄', '相和歌辞 江南弄', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["江南弄，巫山連楚夢，行雨行雲幾相送。","瑤軒金谷上春時，玉童仙女無見期。","紫露香煙眇難託，清風明月遙相思。","遙相思，草徒綠，爲聽雙飛鳳凰曲。"]', '["江南弄，巫山連楚梦，行雨行云幾相送。","瑤軒金谷上春时，玉童仙女無见期。","紫露香煙眇难託，清风明月遙相思。","遙相思，草徒綠，爲听雙飞鳳凰曲。"]', '诗', 'shi', '', NULL, '相和歌辭 江南弄 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29d98345-e050-49c2-89cb-88dbdcd0af97', '相和歌辭 江南弄', '相和歌辞 江南弄', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["江中綠霧起涼波，天上疊巘紅嵯峨。","水風浦雲生老竹，渚瞑蒲帆如一幅。","鱸魚千頭酒百斛，酒中倒臥南山綠。","吳歈越吟未終曲，江上團團帖寒玉。"]', '["江中綠霧起涼波，天上叠巘紅嵯峨。","水风浦云生老竹，渚瞑蒲帆如一幅。","鱸鱼千头酒百斛，酒中倒臥南山綠。","吳歈越吟未終曲，江上團團帖寒玉。"]', '诗', 'shi', '', NULL, '相和歌辭 江南弄 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d8fb7db-36fd-40f1-b120-dc58e0d8b039', '相和歌辭 采蓮曲', '相和歌辞 采蓮曲', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["玉溆花紅發，金塘水碧流。","相逢畏相失，並著采蓮舟。"]', '["玉溆花紅發，金塘水碧流。","相逢畏相失，並著采蓮舟。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f27da66-1e73-4bee-91a4-9de2d9545fc2', '相和歌辭 采蓮曲', '相和歌辞 采蓮曲', 'feb1b440-a02e-4e74-8f62-faadc8d7e153', '唐', '["妾家越水邊，搖艇入江煙。","既覓同心侶，復采同心蓮。","折藕絲能脆，開花葉正圓。","春歌弄明月，歸棹落花前。"]', '["妾家越水邊，搖艇入江煙。","既覓同心侶，复采同心蓮。","折藕絲能脆，开花葉正圓。","春歌弄明月，归棹落花前。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲 徐彥伯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b98a1f96-5eaa-4d8d-ae39-4a7a38b6eb1e', '相和歌辭 采蓮曲', '相和歌辞 采蓮曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["若耶溪邊采蓮女，笑隔荷花共人語。","日照新妝水底明，風飄香袖空中舉。","岸上誰家遊冶郎，三三五五映垂楊。","紫騮嘶入落花去，見此踟躕空斷腸。"]', '["若耶溪邊采蓮女，笑隔荷花共人語。","日照新妝水底明，风飄香袖空中舉。","岸上誰家游冶郎，三三五五映垂楊。","紫騮嘶入落花去，见此踟躕空斷腸。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04adc73f-5d2d-4a17-9254-28a80a52069f', '相和歌辭 采蓮曲', '相和歌辞 采蓮曲', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["稽山罷霧鬱嵯峨，鏡水無風也自波。","莫言春度芳菲盡，別有中流采芰荷。"]', '["稽山罷霧鬱嵯峨，镜水無风也自波。","莫言春度芳菲尽，別有中流采芰荷。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc566dcd-4892-4c67-87ad-6f65ff3b4e04', '相和歌辭 采蓮曲三首 一', '相和歌辞 采蓮曲三首 一', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["吳姬越豔楚王妃，爭弄蓮舟水溼衣。","來時浦口花迎入，采罷江頭月送歸。"]', '["吳姬越豔楚王妃，爭弄蓮舟水溼衣。","来时浦口花迎入，采罷江头月送归。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲三首 一 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eac61312-dec6-4712-a34a-9a71969af9d5', '相和歌辭 采蓮曲三首 二', '相和歌辞 采蓮曲三首 二', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["荷葉羅裙一色裁，芙蓉向臉兩邊開。","亂入池中看不見，聞歌始覺有人來。"]', '["荷葉羅裙一色裁，芙蓉向臉兩邊开。","亂入池中看不见，闻歌始覺有人来。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲三首 二 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('efce77ad-b87b-4f3f-a33f-5732adb9440e', '相和歌辭 采蓮曲三首 三', '相和歌辞 采蓮曲三首 三', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["越女作桂舟，還將桂爲檝。","湖上水渺漫，清江初可涉。","摘取芙蓉花，莫摘芙蓉葉。"]', '["越女作桂舟，還將桂爲檝。","湖上水渺漫，清江初可涉。","摘取芙蓉花，莫摘芙蓉葉。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲三首 三 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2036833d-b04f-49fe-b709-3eccd090f147', '相和歌辭 采蓮曲二首 一', '相和歌辞 采蓮曲二首 一', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["雖聽采蓮曲，詎識采蓮心。","漾檝愛花遠，回船愁浪深。","煙生極浦色，日落半江陰。","同侶憐波靜，看妝墮玉簪。"]', '["雖听采蓮曲，詎識采蓮心。","漾檝愛花远，回船愁浪深。","煙生極浦色，日落半江陰。","同侶怜波静，看妝墮玉簪。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲二首 一 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b2be4af-0264-4adc-80c4-0691ad752f41', '相和歌辭 采蓮曲二首 二', '相和歌辞 采蓮曲二首 二', '35f5fc85-e44a-4035-8ba7-4d6b03d80243', '唐', '["涔陽女兒花滿頭，毿毿同汎木蘭舟。","春風日暮南湖裏，爭唱菱歌不肯休。"]', '["涔陽女兒花满头，毿毿同汎木蘭舟。","春风日暮南湖裏，爭唱菱歌不肯休。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲二首 二 戎昱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bbe77207-c21e-4f74-9e94-fee4f8cb57fc', '相和歌辭 采蓮曲', '相和歌辞 采蓮曲', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["淺渚荷花繁，深塘菱葉疎。","獨往方自得，恥邀淇上姝。","廣江無術阡，大澤絕方隅。","浪中海童語，流下鮫人居。","春雁時隱舟，新荷復滿湖。","采采乘日暮，不思賢與愚。"]', '["淺渚荷花繁，深塘菱葉疎。","独往方自得，恥邀淇上姝。","廣江無術阡，大澤絕方隅。","浪中海童語，流下鮫人居。","春雁时隐舟，新荷复满湖。","采采乘日暮，不思賢與愚。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5aee2c13-785a-4735-8a13-069d126a37f6', '相和歌辭 采蓮曲二首 一', '相和歌辞 采蓮曲二首 一', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["弄舟朅來南塘水，荷葉映身摘蓮子。","暑衣清淨鴛鴦喜，作浪舞花驚不起。","殷勤護惜纖纖指，水菱初熟多新刺。"]', '["弄舟朅来南塘水，荷葉映身摘蓮子。","暑衣清淨鴛鴦喜，作浪舞花驚不起。","殷勤護惜纖纖指，水菱初熟多新刺。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲二首 一 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a4822fe-71f9-448f-923f-ea4061d09e2f', '相和歌辭 采蓮曲二首 二', '相和歌辞 采蓮曲二首 二', '11289b06-5a69-43a6-bbb8-98bc7e15ec06', '唐', '["采蓮朅來水無風，蓮潭如鏡松如龍。","夏衫短袖交斜紅，豔歌笑鬬新芙蓉，戲魚住聽蓮花東。"]', '["采蓮朅来水無风，蓮潭如镜松如龙。","夏衫短袖交斜紅，豔歌笑鬬新芙蓉，戲鱼住听蓮花东。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲二首 二 鮑溶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ee9b746-0c42-41af-bd85-630f391f7c59', '相和歌辭 采蓮曲', '相和歌辞 采蓮曲', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["秋江岸邊蓮子多，采蓮女兒凭船歌。","青房圓實齊戢戢，爭前競折蕩漾波。","試牽綠莖下尋藕，斷處絲多刺傷手。","白練束腰袖半卷，不插玉釵妝梳淺。","船中未滿度前洲，借問誰家家住遠。","歸時共待暮潮上，自弄芙蓉還蕩槳。"]', '["秋江岸邊蓮子多，采蓮女兒凭船歌。","青房圓實齊戢戢，爭前競折蕩漾波。","試牽綠莖下尋藕，斷处絲多刺傷手。","白練束腰袖半卷，不插玉釵妝梳淺。","船中未满度前洲，借问誰家家住远。","归时共待暮潮上，自弄芙蓉還蕩槳。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d07a19f-fe9d-467d-a06a-a8795cb13783', '相和歌辭 采蓮曲', '相和歌辞 采蓮曲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["菱葉縈波荷颭風，荷花深處小船通。","逢郎欲語低頭笑，碧玉搔頭落水中。"]', '["菱葉縈波荷颭风，荷花深处小船通。","逢郎欲語低头笑，碧玉搔头落水中。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5f2d36f-9597-41a7-99cc-5ff88b7c8c79', '相和歌辭 采蓮曲', '相和歌辞 采蓮曲', '405848e7-8d14-42db-a593-f688fd279870', '唐', '["越江女，越江蓮。","齊菡萏，雙嬋娟。","嬉遊向何處？","采摘且同船。","浩唱發容與，清波生漪漣。","時逢島嶼泊，幾共鴛鴦眠。","襟袖既盈溢，馨香亦相傳。","薄暮歸去來，苧羅生碧煙。"]', '["越江女，越江蓮。","齊菡萏，雙嬋娟。","嬉游向何处？","采摘且同船。","浩唱發容與，清波生漪漣。","时逢島嶼泊，幾共鴛鴦眠。","襟袖既盈溢，馨香亦相傳。","薄暮归去来，苧羅生碧煙。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮曲 僧齊己 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f0f728d-0c02-4fd4-9976-ba6f0cba1c12', '相和歌辭 采蓮歸', '相和歌辞 采蓮归', 'eaee4526-06e8-4038-83c7-7262edd19178', '唐', '["采蓮歸，綠水芙蓉衣，秋風起浪鳧雁飛。","桂棹蘭橈下長浦，羅裙玉腕搖輕櫓。","葉嶼花潭極望平，江謳越吹相思苦。","相思苦，佳期不可駐。","塞外征夫猶未還，江南采蓮今已暮。","今已暮，摘蓮花，今渠那必盡倡家。","官道城南把桑葉，何如江上采蓮花？","蓮花復蓮花，花葉何重疊。","葉翠本羞眉，花紅彊如頰。","佳人不茲期，悵望別離時。","牽花憐共蒂，折藕愛連絲。","故情何處所？新物徒華滋。","不惜南津交佩解，還羞北海雁書遲。","采蓮歌有節，采蓮夜未歇。","正逢浩蕩江上風，又值徘徊江上月。","蓮浦夜相逢，吳姬越女何丰茸。","共問寒江千里外，征客關山更幾重。"]', '["采蓮归，綠水芙蓉衣，秋风起浪鳧雁飞。","桂棹蘭橈下长浦，羅裙玉腕搖轻櫓。","葉嶼花潭極望平，江謳越吹相思苦。","相思苦，佳期不可駐。","塞外征夫猶未還，江南采蓮今已暮。","今已暮，摘蓮花，今渠那必尽倡家。","官道城南把桑葉，何如江上采蓮花？","蓮花复蓮花，花葉何重叠。","葉翠本羞眉，花紅彊如頰。","佳人不茲期，悵望別離时。","牽花怜共蒂，折藕愛連絲。","故情何处所？新物徒华滋。","不惜南津交佩解，還羞北海雁书遲。","采蓮歌有節，采蓮夜未歇。","正逢浩蕩江上风，又值徘徊江上月。","蓮浦夜相逢，吳姬越女何丰茸。","共问寒江千里外，征客关山更幾重。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮歸 王勃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ff96bd0-5cde-4fff-aa80-de11819ccd23', '相和歌辭 采蓮女', '相和歌辞 采蓮女', '279468d4-48db-402e-9185-d8eb7a150748', '唐', '["采蓮女，采蓮舟，春日春江碧水流。","蓮衣承玉釧，蓮刺罥銀鉤。","薄暮斂容歌一曲，氛氳香氣滿汀洲。"]', '["采蓮女，采蓮舟，春日春江碧水流。","蓮衣承玉釧，蓮刺罥銀鉤。","薄暮斂容歌一曲，氛氳香氣满汀洲。"]', '诗', 'shi', '', NULL, '相和歌辭 采蓮女 閻朝隱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dabbe1b-2f16-498b-a1e7-be13ab466eca', '相和歌辭 湖邊采蓮婦', '相和歌辞 湖邊采蓮婦', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["小姑織白紵，未解將人語。","大嫂采芙蓉，溪湖千萬重。","長兄行不在，莫使外人逢。","願學秋胡婦，真心比古松。"]', '["小姑织白紵，未解將人語。","大嫂采芙蓉，溪湖千万重。","长兄行不在，莫使外人逢。","願学秋胡婦，真心比古松。"]', '诗', 'shi', '', NULL, '相和歌辭 湖邊采蓮婦 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a782bd15-160a-4ffd-803e-35334740fbff', '相和歌辭 張靜婉采蓮曲', '相和歌辞 張静婉采蓮曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["蘭膏墜髮紅玉春，燕釵拖頸拋盤雲。","城西楊柳向嬌晚，門前溝水波潾潾。","麒麟公子朝天客，珮馬璫璫鐺度春陌。","掌中無力舞衣輕，翦斷鮫綃破春碧。","抱月飄煙一尺腰，麝臍龍髓憐嬌饒。","秋羅拂衣碎光動，露重花多香不銷。","鸂鶒膠膠塘水滿，綠萍如粟蓮莖短。","一夜西風送雨來，粉痕零落愁紅淺。","船頭折藕絲暗牽，藕根蓮子相留連。","郎心似月月易缺，十五十六清光圓。"]', '["蘭膏墜髮紅玉春，燕釵拖頸拋盤云。","城西楊柳向嬌晚，门前溝水波潾潾。","麒麟公子朝天客，珮马璫璫鐺度春陌。","掌中無力舞衣轻，翦斷鮫綃破春碧。","抱月飄煙一尺腰，麝臍龙髓怜嬌饒。","秋羅拂衣碎光动，露重花多香不銷。","鸂鶒膠膠塘水满，綠萍如粟蓮莖短。","一夜西风送雨来，粉痕零落愁紅淺。","船头折藕絲暗牽，藕根蓮子相留連。","郎心似月月易缺，十五十六清光圓。"]', '诗', 'shi', '', NULL, '相和歌辭 張靜婉采蓮曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac2ea361-8c0d-4c98-b95e-bfcc95443067', '相和歌辭 鳳笙曲', '相和歌辞 鳳笙曲', 'e3813c1b-e287-4602-ac85-11dc1c4c9633', '唐', '["憶昔王子晉，鳳笙遊雲空。","揮手弄白日，安能戀青宮。","豈無嬋娟子，結念羅帳中。","憐壽不貴色，身世兩無窮。"]', '["憶昔王子晉，鳳笙游云空。","揮手弄白日，安能戀青宮。","豈無嬋娟子，結念羅帳中。","怜壽不貴色，身世兩無窮。"]', '诗', 'shi', '', NULL, '相和歌辭 鳳笙曲 沈佺期 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08746182-6421-4271-a4fd-35fef6bf09f5', '相和歌辭 鳳吹笙曲', '相和歌辞 鳳吹笙曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["仙人十五愛吹笙，學得崑丘彩鳳鳴。","始聞鍊氣餐金液，復道朝天赴玉京。","玉京迢迢幾千里，鳳笙去去無邊已。","欲歎離聲發絳脣，更嗟別調流纖指。","此時惜別詎堪聞，此地相看未忍分。","重吟真曲和清吹，却奏仙歌響綠雲。","綠雲紫氣向函關，訪道應尋緱氏山。","莫學吹笙王子晉，一遇浮丘斷不還。"]', '["仙人十五愛吹笙，学得崑丘彩鳳鳴。","始闻鍊氣餐金液，复道朝天赴玉京。","玉京迢迢幾千里，鳳笙去去無邊已。","欲歎離声發絳脣，更嗟別調流纖指。","此时惜別詎堪闻，此地相看未忍分。","重吟真曲和清吹，却奏仙歌响綠云。","綠云紫氣向函关，訪道應尋緱氏山。","莫学吹笙王子晉，一遇浮丘斷不還。"]', '诗', 'shi', '', NULL, '相和歌辭 鳳吹笙曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11626f58-4066-4818-b22d-d23bd4b25a9b', '相和歌辭 采菱曲', '相和歌辞 采菱曲', '783d770f-a248-4c04-ac0f-1f8468714731', '唐', '["濁水菱葉肥，清水菱葉鮮。","義不游濁水，志士多苦言。","潮沒具區藪，潦深雲夢田。","朝隨北風去，暮逐南風還。","浦口多漁家，相與邀我船。","飯稻以終日，羹蓴將永年。","方冬水物窮，又欲休山樊。","盡室相隨從，所貴無憂患。"]', '["濁水菱葉肥，清水菱葉鲜。","義不游濁水，志士多苦言。","潮沒具區藪，潦深云梦田。","朝隨北风去，暮逐南风還。","浦口多漁家，相與邀我船。","飯稻以終日，羹蓴將永年。","方冬水物窮，又欲休山樊。","尽室相隨從，所貴無憂患。"]', '诗', 'shi', '', NULL, '相和歌辭 采菱曲 儲光羲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('303d9236-55b2-4dea-8967-74d66f440450', '相和歌辭 采菱行', '相和歌辞 采菱行', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["白馬湖平秋日光，紫菱如錦綵鸞翔。","盪舟遊女滿中央，采菱不顧馬上郎。","爭多逐勝紛相向，時轉蘭橈破輕浪。","長鬟弱袂動參差，釵影釧文浮蕩漾。","笑語哇咬顧晚暉，蓼花綠岸扣舷歸。","歸來共到市橋步，野蔓繫船萍滿衣。","家家竹樓臨廣陌，下有連檣多估客。","攜觴薦芰夜經過，醉踏大堤相應歌。","屈平祠下沅江水，月照寒波白煙起。","一曲南音此地聞，長安北望三千里。"]', '["白马湖平秋日光，紫菱如錦綵鸾翔。","盪舟游女满中央，采菱不顧马上郎。","爭多逐勝紛相向，时轉蘭橈破轻浪。","长鬟弱袂动參差，釵影釧文浮蕩漾。","笑語哇咬顧晚暉，蓼花綠岸扣舷归。","归来共到市橋步，野蔓繫船萍满衣。","家家竹楼臨廣陌，下有連檣多估客。","携觴薦芰夜經過，醉踏大堤相應歌。","屈平祠下沅江水，月照寒波白煙起。","一曲南音此地闻，长安北望三千里。"]', '诗', 'shi', '', NULL, '相和歌辭 采菱行 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5a58448-98ea-4e6f-b2b3-d3c04f93d3fa', '相和歌辭 陽春歌', '相和歌辞 陽春歌', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["長安白日照春空，綠楊結煙桑褭風。","披香殿前花始紅，流芳發色繡戶中。","繡戶中，相經過。","飛燕皇后輕身舞，紫宮夫人絕世歌。"]', '["长安白日照春空，綠楊結煙桑褭风。","披香殿前花始紅，流芳發色繡戶中。","繡戶中，相經過。","飞燕皇后轻身舞，紫宮夫人絕世歌。"]', '诗', 'shi', '', NULL, '相和歌辭 陽春歌 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fed32503-f4b9-47b0-8a8a-0d674b54aaa2', '相和歌辭 陽春曲', '相和歌辞 陽春曲', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["雲母空窗曉煙薄，香昏龍氣凝輝閣。","霏霏霧雨杏花天，簾外春威著羅幕。","曲欄伏檻金麒麟，沙苑芳郊連翠茵。","廐馬何能齧芳草，路人不敢隨流塵。"]', '["云母空窗晓煙薄，香昏龙氣凝輝閣。","霏霏霧雨杏花天，簾外春威著羅幕。","曲欄伏檻金麒麟，沙苑芳郊連翠茵。","廐马何能齧芳草，路人不敢隨流塵。"]', '诗', 'shi', '', NULL, '相和歌辭 陽春曲 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fb6e6f3-551d-4f6b-8e7e-259bc409c3c0', '相和歌辭 陽春曲', '相和歌辞 陽春曲', '998a453e-7ad8-44a7-ac68-91abf4146a26', '唐', '["紫錦紅囊香滿風，金鸞玉軾搖丁冬。","沙鷗白羽翦晴碧，野桃紅豔燒春空。","芳草綿延鎖平地，壠蝶雙雙舞幽翠。","鳳叫龍吟白日長，落花聲底仙娥醉。"]', '["紫錦紅囊香满风，金鸾玉軾搖丁冬。","沙鷗白羽翦晴碧，野桃紅豔燒春空。","芳草綿延鎖平地，壠蝶雙雙舞幽翠。","鳳叫龙吟白日长，落花声底仙娥醉。"]', '诗', 'shi', '', NULL, '相和歌辭 陽春曲 莊南傑 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('249801a1-6d2e-4b26-9daf-10ab3aa0fa5b', '相和歌辭 陽春曲', '相和歌辞 陽春曲', '2f390450-2daa-424a-9330-8269402ce797', '唐', '["爲口莫學阮嗣宗，不言是非非至公。","爲手須似朱雲輩，折檻英風至今在。","男兒結髮事君親，須斅前賢多慷慨。","歷數雍熙房與杜，魏公姚公宋開府。"]', '["爲口莫学阮嗣宗，不言是非非至公。","爲手須似朱云輩，折檻英风至今在。","男兒結髮事君親，須斅前賢多慷慨。","歷數雍熙房與杜，魏公姚公宋开府。"]', '诗', 'shi', '', NULL, '相和歌辭 陽春曲 僧貫休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a73d7bc0-d427-4363-9cff-b17eecd95e9d', '相和歌辭 朝雲引', '相和歌辞 朝云引', 'aff13fc2-5a00-4377-82e1-6a8e636e4aaf', '唐', '["巴西巫峽指巴東，朝雲觸石上朝空。","巫山巫峽高何已，行雨行雲一時起。","一時起，三春暮。","若言來，且就陽臺路。"]', '["巴西巫峽指巴东，朝云觸石上朝空。","巫山巫峽高何已，行雨行云一时起。","一时起，三春暮。","若言来，且就陽台路。"]', '诗', 'shi', '', NULL, '相和歌辭 朝雲引 郎大家宋氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1863f14-2d00-47ca-bb8c-3996c3bacb2a', '相和歌辭 上雲樂', '相和歌辞 上云乐', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["金天之西，白日所沒。","康老胡雛，生彼月窟。","巉巖儀容，[戌]削風骨。","碧玉炅炅雙目瞳，黃金拳拳兩鬢紅。","華蓋垂下睫，嵩嶽臨上脣。","不覩譎詭貌，豈知造化神。","大道是文康之嚴父，元氣乃文康之老親。","撫頂弄盤古，推車轉天輪。","云見日月初生時，鑄冶火精與水銀。","陽烏未出谷，顧兔半藏身。","女媧戲黃土，團作愚下人。","散在六合間，濛濛如沙塵。","生死了不盡，誰明此胡是仙真。","西海栽若木，東溟植扶桑。","別來幾多時，枝葉萬里長。","中國有七聖，半路頹鴻荒。","陛下應運起，龍飛入咸陽。","赤眉立盆子，白水興漢光。","叱咤四海動，洪濤爲簸揚。","舉足蹋紫微，天關自開張。","老胡感至德，東來進仙倡。","五色師子，九苞鳳凰。","是老胡雞犬，鳴舞飛帝鄉。","淋灕颯沓，進退成行。","能胡歌，獻漢酒。","跪雙膝，並兩肘。","散花指天舉素手，拜龍顏，獻聖壽。","北斗戾，南山摧。","天子九九八十一[萬]歲，長傾萬歲杯。"]', '["金天之西，白日所沒。","康老胡雛，生彼月窟。","巉巖儀容，[戌]削风骨。","碧玉炅炅雙目瞳，黄金拳拳兩鬢紅。","华蓋垂下睫，嵩嶽臨上脣。","不覩譎詭貌，豈知造化神。","大道是文康之嚴父，元氣乃文康之老親。","撫頂弄盤古，推车轉天輪。","云见日月初生时，鑄冶火精與水銀。","陽烏未出谷，顧兔半藏身。","女媧戲黄土，團作愚下人。","散在六合间，濛濛如沙塵。","生死了不尽，誰明此胡是仙真。","西海栽若木，东溟植扶桑。","別来幾多时，枝葉万里长。","中国有七聖，半路頹鴻荒。","陛下應運起，龙飞入咸陽。","赤眉立盆子，白水兴漢光。","叱咤四海动，洪濤爲簸揚。","舉足蹋紫微，天关自开張。","老胡感至德，东来進仙倡。","五色師子，九苞鳳凰。","是老胡雞犬，鳴舞飞帝乡。","淋灕颯沓，進退成行。","能胡歌，獻漢酒。","跪雙膝，並兩肘。","散花指天舉素手，拜龙顏，獻聖壽。","北斗戾，南山摧。","天子九九八十一[万]歲，长傾万歲杯。"]', '诗', 'shi', '', NULL, '相和歌辭 上雲樂 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22abc39e-e43e-4644-97f0-08053b5fa3ee', '相和歌辭 上雲樂', '相和歌辞 上云乐', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["飛香走紅滿天春，花龍盤盤上紫雲。","三千宮女列金屋，五十弦瑟海上聞。","大江碎碎銀沙路，嬴女機中斷煙素。","斷煙素，縫舞衣，八月一日君前舞。"]', '["飞香走紅满天春，花龙盤盤上紫云。","三千宮女列金屋，五十弦瑟海上闻。","大江碎碎銀沙路，嬴女機中斷煙素。","斷煙素，縫舞衣，八月一日君前舞。"]', '诗', 'shi', '', NULL, '相和歌辭 上雲樂 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df572f9e-bc85-4b4b-bf6a-05b06c3244dc', '相和歌辭 鳳臺曲', '相和歌辞 鳳台曲', 'efabfbd9-153d-4b78-9136-a6a5d4f9d9e9', '唐', '["鳳臺何逶迤，嬴女管參差。","一旦綵雲至，身去無還期。","遺曲此臺上，世人多學吹。","一吹一落淚，至今憐玉姿。"]', '["鳳台何逶迤，嬴女管參差。","一旦綵云至，身去無還期。","遺曲此台上，世人多学吹。","一吹一落泪，至今怜玉姿。"]', '诗', 'shi', '', NULL, '相和歌辭 鳳臺曲 王無競 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('430909e6-8bce-4974-9700-05083ebb3bd3', '相和歌辭 鳳臺曲', '相和歌辞 鳳台曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嘗聞秦帝女，傳得鳳凰聲。","是日逢仙子，當時別有情。","人吹彩簫去，天借綠雲迎。","曲在身不返，空餘弄玉名。"]', '["嘗闻秦帝女，傳得鳳凰声。","是日逢仙子，當时別有情。","人吹彩簫去，天借綠云迎。","曲在身不返，空餘弄玉名。"]', '诗', 'shi', '', NULL, '相和歌辭 鳳臺曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('970e1233-9d3b-4ee6-92c1-1491ffc37bfa', '相和歌辭 鳳凰曲', '相和歌辞 鳳凰曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["嬴女吹玉簫，吟弄天上春。","青鸞不獨去，更有攜手人。","影滅彩雲斷，遺聲落西秦。"]', '["嬴女吹玉簫，吟弄天上春。","青鸾不独去，更有携手人。","影滅彩云斷，遺声落西秦。"]', '诗', 'shi', '', NULL, '相和歌辭 鳳凰曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ffad7e2-6272-472d-a10d-7495d6de3e7f', '相和歌辭 君道曲', '相和歌辞 君道曲', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["大君若天覆，廣運無不至。","軒后爪牙常先太山稽，如心之使臂。","小白鴻翼於夷吾，劉葛魚水本無二。","土扶可成牆，積德爲厚地。"]', '["大君若天覆，廣運無不至。","軒后爪牙常先太山稽，如心之使臂。","小白鴻翼於夷吾，劉葛鱼水本無二。","土扶可成牆，積德爲厚地。"]', '诗', 'shi', '', NULL, '相和歌辭 君道曲 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4da16564-5084-4550-a435-5373c8a82ae2', '舞曲歌辭 吳俞兒舞歌 劒俞', '舞曲歌辞 吳俞兒舞歌 劒俞', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["枝月喉，櫂霜脊，北斗離離在寒碧。","龍魂清，虎尾白，秋照海心同一色。","纛影吒沙干影側，神豪髮直。","四睨之人股佶栗，欲定不定定不得。","舂牘殘，兒且止。","狄胡有膽大如山，怖亦死。"]', '["枝月喉，櫂霜脊，北斗離離在寒碧。","龙魂清，虎尾白，秋照海心同一色。","纛影吒沙干影側，神豪髮直。","四睨之人股佶栗，欲定不定定不得。","舂牘殘，兒且止。","狄胡有膽大如山，怖亦死。"]', '诗', 'shi', '', NULL, '舞曲歌辭 吳俞兒舞歌 劒俞 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29d4e6ab-d0d6-4848-8457-3eeae711bfec', '舞曲歌辭 吳俞兒舞歌 矛俞', '舞曲歌辞 吳俞兒舞歌 矛俞', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["手盤風，頭背分，電光戰扇，欲刺敲心留半綫。","纏肩繞脰，𧞔合眩旋。","卓植赴列，奪避中節。","前衝函禮穴，上指孛彗滅，與君一用來有截。"]', '["手盤风，头背分，電光戰扇，欲刺敲心留半綫。","纏肩繞脰，𧞔合眩旋。","卓植赴列，奪避中節。","前衝函禮穴，上指孛彗滅，與君一用来有截。"]', '诗', 'shi', '', NULL, '舞曲歌辭 吳俞兒舞歌 矛俞 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2df650b4-1432-4b09-b37d-1068b6f67955', '舞曲歌辭 吳俞兒舞歌 弩俞', '舞曲歌辞 吳俞兒舞歌 弩俞', '37141540-d31f-4016-b1c0-0f45248e4abe', '唐', '["牛來開弦，人爲置鏃。","捩機關，迸山谷。","鹿駭澀，隼擊遲。","析毫中睫，洞腋分龜。","達堅壘，殘雄師。","可以冠猛樂壯曲，抑揚蹈厲，有裂犀兕之氣者非公與。"]', '["牛来开弦，人爲置鏃。","捩機关，迸山谷。","鹿駭澀，隼擊遲。","析毫中睫，洞腋分龟。","達堅壘，殘雄師。","可以冠猛乐壯曲，抑揚蹈厲，有裂犀兕之氣者非公與。"]', '诗', 'shi', '', NULL, '舞曲歌辭 吳俞兒舞歌 弩俞 陸龜蒙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('551ff4cc-f942-44ea-942a-9e97dedc5431', '舞曲歌辭 東海有勇婦', '舞曲歌辞 东海有勇婦', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["梁山感杞妻，慟哭爲之傾。","金石忽暫開，都由激深情。","東海有勇婦，何慙蘇子卿。","學劒越處子，超騰若流星。","捐軀報夫讐，萬死不顧生。","白刃耀素雪，蒼天感精誠。","十步兩躩躍，三呼一交兵。","斬首掉國門，蹴踏五藏行。","割此伉儷憤，粲然大義明。","北海李使君，飛章奏天庭。","舍罪警風俗，流芳播滄瀛。","志在列女籍，竹帛已光榮。","淳于免詔獄，漢主爲緹縈。","津妾一櫂歌，脫父於嚴刑。","十子若不肖，不如一女英。","豫讓斬空衣，有心竟無成。","要離殺慶忌，壯夫素所輕。","妻子亦何辜，焚之買虛名。","豈如東海婦，事立獨揚名。"]', '["梁山感杞妻，慟哭爲之傾。","金石忽暫开，都由激深情。","东海有勇婦，何慙蘇子卿。","学劒越处子，超腾若流星。","捐軀報夫讐，万死不顧生。","白刃耀素雪，蒼天感精誠。","十步兩躩躍，三呼一交兵。","斬首掉国门，蹴踏五藏行。","割此伉儷憤，粲然大義明。","北海李使君，飞章奏天庭。","舍罪警风俗，流芳播滄瀛。","志在列女籍，竹帛已光榮。","淳于免詔獄，漢主爲緹縈。","津妾一櫂歌，脫父於嚴刑。","十子若不肖，不如一女英。","豫讓斬空衣，有心竟無成。","要離殺慶忌，壯夫素所轻。","妻子亦何辜，焚之買虛名。","豈如东海婦，事立独揚名。"]', '诗', 'shi', '', NULL, '舞曲歌辭 東海有勇婦 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('673630ef-4ca3-46fd-bfa7-99c842c5d502', '舞曲歌辭 章和二年中', '舞曲歌辞 章和二年中', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["雲蕭素，風拂拂，麥芒如篲黍和粟。","關中父老百領襦，關東吏人乏詬租。","健犢春耕土膏黑，菖蒲叢叢沿水脈。","殷勤爲我下田鉏，百錢攜賞絲桐客。","遊春漫光塢花白，野林散香神降席。","拜神得壽獻天子，七星貫斷姮娥死。"]', '["云蕭素，风拂拂，麦芒如篲黍和粟。","关中父老百領襦，关东吏人乏詬租。","健犢春耕土膏黑，菖蒲叢叢沿水脈。","殷勤爲我下田鉏，百錢携賞絲桐客。","游春漫光塢花白，野林散香神降席。","拜神得壽獻天子，七星貫斷姮娥死。"]', '诗', 'shi', '', NULL, '舞曲歌辭 章和二年中 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('488a3222-a997-4caa-9dcd-f0833c98b8c9', '舞曲歌辭 公莫舞歌', '舞曲歌辞 公莫舞歌', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["方花古礎排九楹，刺豹淋血盛銀甖。","華筵鼓吹無桐竹，長刀直立割鳴箏。","橫楣麤錦生紅緯，日炙錦嫣王未醉。","腰下三看寶玦光，項莊掉箾攔前起。","材官小臣公莫舞，座上真人赤龍子。","芒碭雲瑞抱天回，咸陽王氣清如水。","鐵樞鐵楗重束關，大旗五丈撞雙環。","漢王今日須秦印，絕臏刳腸臣不論。"]', '["方花古礎排九楹，刺豹淋血盛銀甖。","华筵鼓吹無桐竹，长刀直立割鳴箏。","橫楣麤錦生紅緯，日炙錦嫣王未醉。","腰下三看寶玦光，項莊掉箾攔前起。","材官小臣公莫舞，座上真人赤龙子。","芒碭云瑞抱天回，咸陽王氣清如水。","鐵樞鐵楗重束关，大旗五丈撞雙环。","漢王今日須秦印，絕臏刳腸臣不論。"]', '诗', 'shi', '', NULL, '舞曲歌辭 公莫舞歌 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68880a1b-7d86-45b6-8eba-ef33f0687a14', '舞曲歌辭 拂舞辭', '舞曲歌辞 拂舞辞', 'c5f95f75-00b0-4da7-b0dd-5b6b2f3efa0e', '唐', '["吳娥聲絕天，空雲閑裴回。","門外滿車馬，亦須生綠苔。","尊有烏程酒，勸君千萬壽。","全勝漢武錦樓上，曉望晴寒飲花露。","東方日不破，天光無老時。","丹成作蛇乘白霧，千年重化玉井龜。","從蛇作龜二千載，吳堤綠草年年在。","背有八卦稱神仙，邪鱗頑甲滑腥涎。"]', '["吳娥声絕天，空云闲裴回。","门外满车马，亦須生綠苔。","尊有烏程酒，勸君千万壽。","全勝漢武錦楼上，晓望晴寒饮花露。","东方日不破，天光無老时。","丹成作蛇乘白霧，千年重化玉井龟。","從蛇作龟二千載，吳堤綠草年年在。","背有八卦稱神仙，邪鱗頑甲滑腥涎。"]', '诗', 'shi', '', NULL, '舞曲歌辭 拂舞辭 李賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73ef28f7-b681-4cc4-9edf-36484e085d5f', '舞曲歌辭 白鳩辭', '舞曲歌辞 白鳩辞', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["鏗鳴鐘，考朗鼓。","歌白鳩，引拂舞。","白鳩之白誰與鄰，霜衣雪襟誠可珍。","含哺七子能平均，食不咽，性安馴。","首農政，鳴陽春。","天子刻玉杖，鏤形賜耆人。","白鷺亦白非純真，外潔其色心匪仁。","闕五德，無司晨。","胡爲啄我葭下之紫鱗，鷹鸇鵰鶚，貪而好殺。","鳳皇雖大聖，不願以爲臣。"]', '["鏗鳴鐘，考朗鼓。","歌白鳩，引拂舞。","白鳩之白誰與鄰，霜衣雪襟誠可珍。","含哺七子能平均，食不咽，性安馴。","首農政，鳴陽春。","天子刻玉杖，鏤形賜耆人。","白鷺亦白非純真，外潔其色心匪仁。","闕五德，無司晨。","胡爲啄我葭下之紫鱗，鷹鸇鵰鶚，貪而好殺。","鳳皇雖大聖，不願以爲臣。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白鳩辭 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8981911c-da27-4a25-bffb-a8cc1aa7cdfa', '舞曲歌辭 獨漉篇', '舞曲歌辞 独漉篇', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["獨漉水中泥，水濁不見月。","不見月尚可，水深行人沒。","越鳥從南來，胡鷹亦北度。","我欲彎弓向天射，惜其中道失歸路。","落葉別樹，飄零隨風。","客無所託，悲與此同。","羅帷舒卷，似有人開。","明月直入，無心可猜。","雄劒挂壁，時時龍鳴。","不斷犀象，繡澀苔生。","國恥未雪，何由成名。","神鷹夢澤，不顧鴟鳶。","爲君一擊，摶鵬九天。"]', '["独漉水中泥，水濁不见月。","不见月尚可，水深行人沒。","越鸟從南来，胡鷹亦北度。","我欲彎弓向天射，惜其中道失归路。","落葉別樹，飄零隨风。","客無所託，悲與此同。","羅帷舒卷，似有人开。","明月直入，無心可猜。","雄劒挂壁，时时龙鳴。","不斷犀象，繡澀苔生。","国恥未雪，何由成名。","神鷹梦澤，不顧鴟鳶。","爲君一擊，摶鵬九天。"]', '诗', 'shi', '', NULL, '舞曲歌辭 獨漉篇 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae2ca5e0-6550-4704-8c4f-41d44eb616ef', '舞曲歌辭 獨漉歌', '舞曲歌辞 独漉歌', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["獨獨漉漉，鼠食貓肉。","烏日中，鶴露宿，黃河水直人心曲。"]', '["独独漉漉，鼠食貓肉。","烏日中，鹤露宿，黄河水直人心曲。"]', '诗', 'shi', '', NULL, '舞曲歌辭 獨漉歌 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a5d7a69-ea86-4ae5-9803-916d1ab42243', '舞曲歌辭 白紵辭二首 一', '舞曲歌辞 白紵辞二首 一', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["洛陽梨花落如霰，河陽桃葉生復齊。","坐恐玉樓春欲盡，紅綿粉絮裛妝啼。"]', '["洛陽梨花落如霰，河陽桃葉生复齊。","坐恐玉楼春欲尽，紅綿粉絮裛妝啼。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白紵辭二首 一 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c76eb85-1424-46f2-a5e8-67630b99e553', '舞曲歌辭 白紵辭二首 二', '舞曲歌辞 白紵辞二首 二', '07f07897-ed45-4a0e-9f07-dcbdbfd2f11f', '唐', '["董賢女弟在椒風，窈窕繁華貴後宮。","璧帶金釭皆翡翠，一朝零落變成空。"]', '["董賢女弟在椒风，窈窕繁华貴後宮。","璧带金釭皆翡翠，一朝零落变成空。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白紵辭二首 二 崔國輔 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('027b81b2-f5e9-4357-b7d2-1ef89413539d', '舞曲歌辭 白紵辭二首 一', '舞曲歌辞 白紵辞二首 一', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["玉纓翠珮雜輕羅，香汗微漬朱顏酡，爲君起唱白紵歌。","清聲褭雲思繁多，凝笳哀琴時相和。","金壺半傾芳夜促，梁塵霏霏暗紅燭。","令君安坐聽終曲，墜葉飄花難再復。"]', '["玉纓翠珮杂轻羅，香汗微漬朱顏酡，爲君起唱白紵歌。","清声褭云思繁多，凝笳哀琴时相和。","金壺半傾芳夜促，梁塵霏霏暗紅燭。","令君安坐听終曲，墜葉飄花难再复。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白紵辭二首 一 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cabe847-e6b0-4012-9629-20a965ef3778', '舞曲歌辭 白紵辭二首 二', '舞曲歌辞 白紵辞二首 二', '4014b243-6cbb-453e-ae74-3ac99bfdefcb', '唐', '["躡珠履，步瓊筵。","輕身起舞紅燭前，芳姿豔態妖且妍。","迴眸轉袖暗催弦，涼風蕭蕭流水急。","月華泛豔紅蓮溼，牽裙攬帶翻成泣。"]', '["躡珠履，步瓊筵。","轻身起舞紅燭前，芳姿豔態妖且妍。","迴眸轉袖暗催弦，涼风蕭蕭流水急。","月华泛豔紅蓮溼，牽裙攬带翻成泣。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白紵辭二首 二 楊衡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e3e6d44-452e-4d2a-a4ef-1432ea95da22', '舞曲歌辭 白紵辭三首 一', '舞曲歌辞 白紵辞三首 一', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["揚清歌，發皓齒，北方佳人東鄰子。","且吟白紵停淥水，長袖拂面爲君起。","寒雲夜卷霜海空，胡風吹天飄塞鴻。","玉顏滿堂樂未終，館娃日落歌吹濛。"]', '["揚清歌，發皓齒，北方佳人东鄰子。","且吟白紵停淥水，长袖拂面爲君起。","寒云夜卷霜海空，胡风吹天飄塞鴻。","玉顏满堂乐未終，館娃日落歌吹濛。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白紵辭三首 一 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1d0535f-ea83-4c32-afc7-6a2e6fd5ed64', '舞曲歌辭 白紵辭三首 二', '舞曲歌辞 白紵辞三首 二', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["月寒江清夜沈沈，美人一笑千黃金。","垂羅舞縠揚哀音，郢中白雪且莫吟，子夜吳歌動君心。","動君心，冀君賞。","願作天池雙鴦鴦，一朝飛去青雲上。"]', '["月寒江清夜沈沈，美人一笑千黄金。","垂羅舞縠揚哀音，郢中白雪且莫吟，子夜吳歌动君心。","动君心，冀君賞。","願作天池雙鴦鴦，一朝飞去青云上。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白紵辭三首 二 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b88b6153-68dc-4be5-8c54-d2b41ae658ea', '舞曲歌辭 白紵辭三首 三', '舞曲歌辞 白紵辞三首 三', 'c9f24fee-b387-48bb-866a-7f30cdc279a0', '唐', '["吳刀翦綵縫舞衣，明妝麗服奪春輝。","揚眉轉袖若雪飛，傾城獨立世所稀。","激楚結風醉忘歸，高堂月落燭已微，玉釵挂纓君莫違。"]', '["吳刀翦綵縫舞衣，明妝丽服奪春輝。","揚眉轉袖若雪飞，傾城独立世所稀。","激楚結风醉忘归，高堂月落燭已微，玉釵挂纓君莫違。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白紵辭三首 三 李白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14039c2f-d729-44b8-9a3d-6872f26134e0', '舞曲歌辭 白紵歌二首 一', '舞曲歌辞 白紵歌二首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["天河漫漫北斗粲，宮中烏啼知夜半。","新縫白紵舞衣成，來遲邀得吳王迎。","低鬟轉面掩雙袖，玉釵浮動秋風生。","酒多夜長夜未曉，月明燈光兩相照，後庭歌聲更窈窕。"]', '["天河漫漫北斗粲，宮中烏啼知夜半。","新縫白紵舞衣成，来遲邀得吳王迎。","低鬟轉面掩雙袖，玉釵浮动秋风生。","酒多夜长夜未晓，月明灯光兩相照，後庭歌声更窈窕。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白紵歌二首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d179b5ca-f7ba-4b1b-8dae-311ef942a6e0', '舞曲歌辭 白紵歌二首 二', '舞曲歌辞 白紵歌二首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["館娃宮中春日暮，荔枝木瓜花滿樹。","城頭烏棲休擊鼓，青娥彈瑟白紵舞。","夜天燑燑不見星，宮中火照西江明。","美人醉起無次第，墮釵遺佩滿中庭。","此時但願可君意，回晝爲宵亦不寐，年年奉君君莫棄。"]', '["館娃宮中春日暮，荔枝木瓜花满樹。","城头烏棲休擊鼓，青娥彈瑟白紵舞。","夜天燑燑不见星，宮中火照西江明。","美人醉起無次第，墮釵遺佩满中庭。","此时但願可君意，回晝爲宵亦不寐，年年奉君君莫棄。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白紵歌二首 二 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18174707-b8de-4a21-8b90-08b2a03a5ce8', '舞曲歌辭 白紵歌', '舞曲歌辞 白紵歌', '1c9c325a-5ebf-42a7-a8c9-644f1e17a32a', '唐', '["皎皎白紵白且鮮，將作春衫稱少年。","裁縫長短不能定，自持刀尺向姑前。","復恐蘭膏汙纖指，常遣傍人收墮珥。","衣裳著時寒食下，還把玉鞭鞭白馬。"]', '["皎皎白紵白且鲜，將作春衫稱少年。","裁縫长短不能定，自持刀尺向姑前。","复恐蘭膏汙纖指，常遣傍人收墮珥。","衣裳著时寒食下，還把玉鞭鞭白马。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白紵歌 張籍 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8872bb07-22f7-4cd9-9e74-280338f0e83a', '舞曲歌辭 白紵歌', '舞曲歌辞 白紵歌', 'dbb37cbd-be84-419a-a619-47c9e48e04a6', '唐', '["翠帷雙卷出傾城，龍劒破匣霜月明。","朱脣掩抑悄無聲，金簧玉磬宮中生。"]', '["翠帷雙卷出傾城，龙劒破匣霜月明。","朱脣掩抑悄無声，金簧玉磬宮中生。"]', '诗', 'shi', '', NULL, '舞曲歌辭 白紵歌 柳宗元 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('153dd336-48dc-4173-a668-e9b90b2304fb', '舞曲歌辭 冬白紵歌', '舞曲歌辞 冬白紵歌', 'fadd002b-cc87-4e2a-a4d1-dc20bde90e86', '唐', '["吳宮夜長宮漏款，簾幕四垂燈焰暖。","西施自舞王自管，雪紵翻翻鶴翎散。","促節牽繁舞腰嬾，舞腰嬾，王罷飲。","蓋覆西施鳳花錦，身作匡牀臂爲枕。","朝佩摐摐王晏寢，酒醒閽報門無事。","子胥死後言爲諱，近王之臣諭王意。","共笑越王窮惴惴，夜夜抱冰寒不睡。"]', '["吳宮夜长宮漏款，簾幕四垂灯焰暖。","西施自舞王自管，雪紵翻翻鹤翎散。","促節牽繁舞腰嬾，舞腰嬾，王罷饮。","蓋覆西施鳳花錦，身作匡牀臂爲枕。","朝佩摐摐王晏寢，酒醒閽報门無事。","子胥死後言爲諱，近王之臣諭王意。","共笑越王窮惴惴，夜夜抱冰寒不睡。"]', '诗', 'shi', '', NULL, '舞曲歌辭 冬白紵歌 元稹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a6340e9-f163-4ef8-95ef-ba841990a606', '舞曲歌辭 霓裳辭十首 一', '舞曲歌辞 霓裳辞十首 一', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["弟子部中留一色，聽風聽水作霓裳。","散聲未足重來授，直到牀前見上皇。"]', '["弟子部中留一色，听风听水作霓裳。","散声未足重来授，直到牀前见上皇。"]', '诗', 'shi', '', NULL, '舞曲歌辭 霓裳辭十首 一 王建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e35cdd52-0037-44b4-880c-30f3ae13e7a1', '舞曲歌辭 霓裳辭十首 二', '舞曲歌辞 霓裳辞十首 二', '9e7ec19a-3d8c-4b67-abd7-bb4cc803ce4e', '唐', '["中管五弦初半曲，遙教合上隔簾聽。","一聲聲向天頭落，效得仙人夜唱經。"]', '["中管五弦初半曲，遙教合上隔簾听。","一声声向天头落，效得仙人夜唱經。"]', '诗', 'shi', '', NULL, '舞曲歌辭 霓裳辭十首 二 王建 shi');
